	[10001] = {
		id = 10001,
		text = "听到「绝症」这个词，一直努力反击的小鱼，\
突然觉得有些反胃，失去了直视对方的力量",
	},
	[10003] = {
		id = 10003,
		text = "她抹了一下有水汽的玻璃，看向窗外，\
看向窗外深空之海，静默燃烧的、鲸鱼般的天上众星",
	},
	[10005] = {
		id = 10005,
		text = "喔。你不会是想让我无证驾驶吧？",
	},
	[10006] = {
		id = 10006,
		text = "人生只是一局大富翁而已，别把地产看得太重。",
	},
	[10007] = {
		id = 10007,
		text = "随便你，文件爱看不看，不看就直接签吧。",
	},
	[10008] = {
		id = 10008,
		text = "你叫￡莣叻僾，来自火星天，是吧。",
	},
	[10009] = {
		id = 10009,
		text = "长按对话框相当于连续点按\
屏幕左上出现通讯框时也可以按！",
	},
	[10010] = {
		id = 10010,
		text = "517版本将添加地图内容",
	},
	[10011] = {
		id = 10011,
		text = "触摸小鱼的身体，她会有所反应\
根据屏幕提示，试着转向正面吧\
然后，寻找让「手」变红的部位……",
	},
	[10012] = {
		id = 10012,
		text = "从这个故事以「小鱼上大当」为开端来看，其实也大概可以猜到……小鱼绝对不是一个非常可靠的人。\
不过，「假助手」对小鱼的观感还不太坏。\
作为一个笨手笨脚的临时船员，她最大的好处是不反驳自己。",
	},
	[10013] = {
		id = 10013,
		text = "虽然派她去给生态舱的绿植浇水的时候，她浇坏了放在一边的音响。\
但在修完音响以后，她给船上选的BGM的品味，算是勉强过关。",
	},
	[20001] = {
		id = 20001,
		text = "赛文楼德大王",
