	[51000102] = {
		id = 51000102,
		text = "※可使用「都城机票」进行接机。\
\
※每日可免费抽取一次。\
\
※（仅首次）累积200次接机后，获得一次自选6★幻形机会。\
\
※获取6★产物的综合概率为4.01%。\
获取6★幻形的综合概率为1.55%，6★武器的综合概率为0.98%，6★家具的综合概率为1.48%。\
\
※有一定几率获得超稀有的【特殊6★】武器。\
\
※每100次接机必得6★幻形。\
\
※接机获取5★内容的基础概率为7.00%，5★武器的基础概率为3.50%，5★家具的基础概率为3.50%，5★内容的综合概率为12.00%。最多10次接机必定获取5★或以上武器或家具。\
\
※接机获取4★内容的基础概率为62.99%，3★内容的基础概率为21.00%\
\
※第2次到第7次获得相同角色时，每次都会转化为对应角色的【星位之钉】和【珊瑚劫灰】*20。\
第8次及以后获得相同角色时，转化为【珊瑚劫灰】*50。\
\
※在计算相同角色数量时，同一角色的不同幻形，都视为同一角色。\
\
※每获得一把6★武器，获得【珊瑚劫灰】*20。每获得一把5★武器，获得【珊瑚劫灰】*5。每获得一把4★武器，获得【时枝化石】*20。每获得一把3★武器，获得【时枝化石】*10。\
※每获得一件6★家具，获得【珊瑚劫灰】*20。每获得一件5★家具，获得【珊瑚劫灰】*5。",
	},
