	[51100102] = {
		id = 51100102,
		text = "※可使用「诺伦机票」进行接机。\
限定UP幻形的接机成功概率将大幅提升。\
限定UP幻形不会加入常驻接机「异枝与重聚」。\
\
※本接机属于「幻形活动接机」,在任意「幻形活动接机」中未获取6★幻形的累计接机次数，会一直累计于「幻形活动接机」中，与其它接机的接机次数保底相互独立计算，互不影响。\
\
※获取6★产物的综合概率为4.01%。\
获取6★幻形的基础概率为1.80%，6★幻形的综合概率为2.53%，UP6★幻形的综合概率为1.55%。\
\
※每100次接机必得UP6★幻形。\
\
※接机获取5★内容的基础概率为7.00%，5★武器的基础概率为3.50%，5★家具的基础概率为3.50%，5★内容的综合概率为12.00%。最多10次接机必定获取5★或以上武器或家具。\
\
※接机获取4★内容的基础概率为62.99%，3★内容的基础概率为21.00%\
\
※获得非UP的6★内容时，可以选择「扭转命运」，重新获得一次6★内容，其中有10%概率为UP的6★幻形。\
「扭转命运」未获得UP6★幻形时，必定获得与原内容相同类型的6★内容。\
「扭转命运」不会影响「每100次接机必得」的累计接机次数。\
\
※第2次到第7次获得相同角色时，每次都会转化为对应角色的【星位之钉】和【珊瑚劫灰】*20。\
第8次及以后获得相同角色时，转化为【珊瑚劫灰】*50。\
\
※在计算相同角色数量时，同一角色的不同幻形，都视为同一角色。\
\
※每获得一把6★武器，获得【珊瑚劫灰】*20。每获得一把5★武器，获得【珊瑚劫灰】*5。每获得一把4★武器，获得【时枝化石】*20。每获得一把3★武器，获得【时枝化石】*10。\
※每获得一件6★家具，获得【珊瑚劫灰】*20。每获得一件5★家具，获得【珊瑚劫灰】*5。",
	},
