	[529001] = {
		id = 529001,
		text = "由莎乐美治下的金星政府发行，在太阳系流通最广的货币。\
外观轮廓类似扇贝，象征维纳斯（金星）的诞生。",
	},
	[529002] = {
		id = 529002,
		text = "处理后的金刚凝胶，太阳系最贵重的等价物之一。\
是一种外观随机的奇石，传统上认为凝聚成火焰形状者为最佳。\
诺伦的炬火，常能燃起人类的争端。",
	},
	[529003] = {
		id = 529003,
		text = "远航中的种种收获、无用而广受追捧的奇物，最终转化成了兑换实用补给的配额点数。\
使用补给配额，可以在「远航支援商店」兑换远航时的强化效果。",
	},
	[529004] = {
		id = 529004,
		text = "在游戏中游历的种种经验，可以提升玩家等级。",
	},
	[529005] = {
		id = 529005,
		text = "时如珊瑚，其枝偶尔卷曲，落入自身之内。\
连时间也无法逃离时间。",
	},
	[529006] = {
		id = 529006,
		text = "时如珊瑚，其迹为劫灰。\
以炼金术拆解足够稀有之物，偶尔也能见到时间的余烬。",
	},
	[529007] = {
		id = 529007,
		text = "可以等额兑换诺伦炬。\
诺伦尼姆在太阳系中的投影形式之一：空间反流体投影。\
拥有与「黏性」相反的特质，据说它正是构造跃迁航道之风。",
	},
	[529008] = {
		id = 529008,
		text = "据说是「莲花王宫酒店的VIP点数」……但这可能是赛文楼德大王的恶作剧。\
通常用于兑换家具。",
	},
