	[83000001] = {
		id = 83000001,
		text = "【内天体】$内天体有6个部位，每个部位的内天体都提供一定基础属性，与1个<span color=\"#ff6c00\">星芒</>。其中<span color=\"#ff6c00\">心念引擎</>额外提供1个星芒。\
<span color=\"#ff6c00\">相同星芒</>在同一角色身上叠加时，会产生多种叠加效果。\
内天体没有套装效果，套装决定的是熔铸时的星芒倾向（几率已标注在熔铸界面中）。",
	},
	[83000002] = {
		id = 83000002,
		text = "【内天体】$内天体有6个部位，每个部位的内天体都提供一定基础属性，与1个<span color=\"#ff6c00\">星芒</>。其中<span color=\"#ff6c00\">心念引擎</>额外提供1个星芒。\
<span color=\"#ff6c00\">相同星芒</>在同一角色身上叠加时，会产生多种叠加效果。\
内天体没有套装效果，套装决定的是熔铸时的星芒倾向（几率已标注在熔铸界面中）。",
	},
	[83000003] = {
		id = 83000003,
		text = "【剧情树】$在<span color=\"#ff6c00\">时珊瑚树</>中，你可以任意跳转时空，前往你曾经抵达过的<span color=\"#ff6c00\">故事节点</>。\
请注意，跳转时空的行为，会放弃当前的故事进度。\
这棵树上的故事分支，由你在实际游戏中的选择而开放。\
有时，某些故事分支会被<span color=\"#ff6c00\">锁住</>，暂时无法前往。\
而在某些<span color=\"#ff6c00\">故事节点</>，你会把经历写成<span color=\"#ff6c00\">信件</>，发送给自己。\
那些被锁住的分支，往往就是在拆开特定的<span color=\"#ff6c00\">信件</>以后，你才能意识到，如何走向另一种不同的方向。",
	},
	[83000004] = {
		id = 83000004,
		text = "【日常任务/每日危航】$每天04:00，危航调度处会发放<span color=\"#ff6c00\">4个日常任务</>、<span color=\"#ff6c00\">6张危航许可</>。\
使用1张危航许可，可进行1次每日危航战斗。\
另外，你在游戏中可能会获得一种叫做<span color=\"#ff6c00\">杀手朋友券</>的物品。\
在完成每日危航的战斗后，每使用1张杀手朋友券，可以<span color=\"#ff6c00\">多获得1份奖励</>。\
当危航许可不足时，杀手朋友券还可以<span color=\"#ff6c00\">充当危航许可使用</>。",
	},
	[83000005] = {
		id = 83000005,
		text = "【梦境灵修】$每7天开启一期，每期6天，周一休息并结算排名。\
在梦境灵修中，你可以挑战当期BOSS，根据总评分获取排名，以及相应的分段奖励。\
BOSS分为多级难度，战胜低级BOSS后，自动提升一级难度，直到最高难度为止。\
每个难度首次胜利时，可以得到相应奖励。\
无论胜利或失败，均可获得一定评分。胜利用时越短，或失败情况下造成伤害越多，评分越高。\
可以重复挑战，自动记录更高评分。\
|【分区限制】$每个角色每期只能挑战一个BOSS。\
每个BOSS的评分都有独立排行，所有BOSS总分有总排行。\
|【排名奖励】$仅根据总排行的分段，发放分段奖励。\
进入梦境灵修界面时，将自动领取上期奖励。",
	},
	[83000006] = {
		id = 83000006,
		text = "【累积充值】$本次测试中的累积充值金额数，可继承至公测。\
已在本次测试中领取的累积充值奖励，可以直接在公测中再次领取。\
（前戏测试限定奖励除外，前戏测试限定奖励将通过邮件发放）",
	},
	[83000007] = {
		id = 83000007,
		text = "【月天签名】$每次购买月天签名，立刻获得300诺伦透镜与30天生效时间。\
生效期间，每日登录时，可领取380诺伦炬。（凌晨4：00刷新，GMT+8）\
重复购买可叠加天数，但不可超过90天。\
当剩余天数大于60天时，无法继续购买。\
如因特殊情况导致重复购买，无法增加时间，并直接返还XXX诺伦透镜。\
生效期间，因未登录而未领取的诺伦炬，将不会返还。",
	},
	[83000008] = {
		id = 83000008,
		text = "【充值返还】$本次测试期间，充值的金额将按照超值比例，在公测时返还对应数量的诺伦透镜。\
充值0~50美元范围内的金额，将按1:200比例，返还约2.94倍付费价值的诺伦透镜。\
充值50~200美元范围内的金额，将按1:150比例，返还约2.21倍付费价值的诺伦透镜。\
充值200~500美元范围内的金额，将按1:125比例，返还约1.84倍付费价值的诺伦透镜。\
充值500美元以上的金额，将按1:100比例，返还约1.47倍付费价值的诺伦透镜。\
充值返还发放方式：公测后，将以邮件形式发放。\
|【月天签名返还】$本次【前戏测试】期间，「月天签名」的最大购买数量为3张。您购买的所有「月天签名」，均可在公测时等量生效。\
购买「月天签名」的花费，也将计入本次测试的充值总额，按照充值返还规则进行返还。\
|【初心套装返还】$本次【前戏测试】期间，您购买的「初心套装」中的家具，可以直接在公测中再次领取。\
购买「初心套装」的花费，也将计入本次测试的充值总额，按照充值返还规则进行返还。\
|【其它商城礼包】$本次【前戏测试】期间，购买其它未特别提及的商城礼包的花费，都将计入本次测试的充值总额，按照充值返还规则进行返还。\
其它未特别提及的商城礼包附加内容仅作测试用途，不作返还，望悉知。",
	},
