	[92100010] = {
		id = 92100010,
		text = "人的命运值多少钱？天上的星星又值多少钱？\
人类不解答这种问题，猴子获得智慧以后就变得很忙，忙着对老鼠做实验。\
——直到价格标出，智人的文明才睁大惊惶的眼。\
而现在……已是第一份《本命星转让协议》签署之后的第十年。",
	},
