	[94100010] = {
		id = 94100010,
		text = "时为22世纪末，当今时代是由「星相」构筑起的全新文明时代。\
一位高中女生，小鱼，正准备把自己的本命星，卖给「复乐园理事会」……",
	},
	[94100011] = {
		id = 94100011,
		text = "从骗局中救出了小鱼的「假助手」，竟然是「三十六义人」之一的信风。\
一年前，信风与太阳系最有权势的人，理事卿莎乐美，同归于尽……",
	},
	[94100012] = {
		id = 94100012,
		text = "回到一年后的「现在」，你结束了回忆。\
刚才的理事会军官已经逃跑，也许以后我们还会遇到他，但现在就先不管他了。",
	},
	[94100020] = {
		id = 94100020,
		text = "？？？",
	},
	[94100030] = {
		id = 94100030,
		text = "你用本命星的能力，「看见」了小鱼其实没有绝症。\
接下来，你想知道，关于小鱼的自身安全，她怎么想……",
	},
	[94100031] = {
		id = 94100031,
		text = "",
	},
	[94100040] = {
		id = 94100040,
		text = "你觉得关于李先生的一切都很可疑，于是放弃了他的委托。",
	},
	[94100041] = {
		id = 94100041,
		text = "李先生很可疑，但你也并不是一个简单的路人佣兵。\
你觉得，不如继续下去，看看事情的变化……",
	},
	[94100051] = {
		id = 94100051,
		text = "金星天的商场菇已经近在眼前。\
该「卸货」了。",
	},
	[94100052] = {
		id = 94100052,
		text = "金星天的商场菇已经近在眼前。\
但你还想稍微多观察一下……",
	},
	[94100060] = {
		id = 94100060,
		text = "李先生的事告一段落，你从「中间人」那里接到了新的委托。\
调查妻子的出轨——私家侦探的工作，也归佣兵管吗？",
	},
	[94100070] = {
		id = 94100070,
		text = "你觉得伯恩斯这个人给你的印象不太好。\
为了伯恩斯夫人的安全，你提出要见一见她。",
	},
	[94100071] = {
		id = 94100071,
		text = "本节点可获取信件：「所以暂时将你眼睛闭了起来」",
	},
	[94100080] = {
		id = 94100080,
		text = "在伯恩斯事件中，你意外察觉，理事会的寡头与军阀们，竟然曾对理事卿见死不救。\
但理事卿逝去后的一年里，他们又纷纷为此严重后悔了，因为他们无法在争斗中压过「中枢」。\
……「中枢」？那是什么？",
	},
	[94100090] = {
		id = 94100090,
		text = "为了收拾「中枢」高官公子罗密欧，你派小鱼引蛇出洞。",
	},
	[94100091] = {
		id = 94100091,
		text = "在见面时，你看清了罗密欧的本命星能力。\
为此，你决定让他遇到生命中的朱丽叶……",
	},
	[94100100] = {
		id = 94100100,
		text = "伯恩斯与罗密欧事件之后，你打算去找一位你认识的「消息灵通人士」，打听缇缇和船长的下落。",
	},
	[94100110] = {
		id = 94100110,
		text = "一块出现了神秘数字的，半损坏的屏幕。\
和一块据说是「理事卿遗物」的宝石。\
你选择先看前者。",
	},
	[94100111] = {
		id = 94100111,
		text = "本节点可获取信件：「实用乱杀装置」",
	},
	[94100120] = {
		id = 94100120,
		text = "离开帝星祭典，告别消息灵通人士，你回到无序之都。\
下一份佣兵工作，是货运飞船失踪案……它会带给你什么关于缇缇或者船长的线索吗？",
	},
	[94100130] = {
		id = 94100130,
		text = "人的头骨，一位跨越了时间的信使……\
而你恰好有缇缇交给你的，「一把钥匙」。",
	},
	[94100131] = {
		id = 94100131,
		text = "？？？",
	},
	[94100140] = {
		id = 94100140,
		text = "海盗们的真实身份，竟是在这一年里，与缇缇一同对抗「中枢」的队友。\
你与海盗们一起做了一个假头骨，回去交差。",
	},
	[94100150] = {
		id = 94100150,
		text = "你想要找一个机会，以「义人」的身份，解救奴隶。\
但大部分奴隶，比如那位中枢店主的「灯扇人」，都仍对主人完全忠诚，绝对不愿离开自己的主人。",
	},
	[94100151] = {
		id = 94100151,
		text = "？？？",
	},
	[94100160] = {
		id = 94100160,
		text = "真命总统、第二行星无眠至权、冬日帝星照耀的受命者、复乐园第一理事卿、总控四天之主——\
以奇怪的形象，从天而降。",
	},
	[94100170] = {
		id = 94100170,
		text = "你依靠「拆信」规避了某种巨大的风险。\
然后，你掌控了斋藤大佐召唤出的理事卿机仆，折服了理事会的成员们。",
	},
	[94100171] = {
		id = 94100171,
		text = "本节点可获取信件：「风与听者渐行渐远」",
	},
	[94100180] = {
		id = 94100180,
		text = "作为「理事卿之声」，你开始治理你忠诚的理事会。\
在这段时间里，你认识了清凉院眠眠，你的专属女仆……",
	},
	[94100181] = {
		id = 94100181,
		text = "？？？",
	},
	[94100190] = {
		id = 94100190,
		text = "你没有忘记你最初的目的——首先，你想利用理事会的关系网，查到缇缇与船长的更多信息，以及那些不为人知的「中枢」隐秘。",
	},
	[94100191] = {
		id = 94100191,
		text = "上楼吗？还是在楼下坐坐？\
你想，可以先陪小鱼在吧台喝点什么。",
	},
	[94100200] = {
		id = 94100200,
		text = "义尽的……科斯明？\
你在震惊中听了下去。\
调查员所揭露的故事，令你知晓了中枢成立的来龙去脉……但那又是你宁愿自己从未知晓的。",
	},
	[94100201] = {
		id = 94100201,
		text = "？？？",
	},
	[94100210] = {
		id = 94100210,
		text = "辩才姬是业界知名的大律师，但她完全缺乏法律常识。\
在与她的聊天中，你注意到了一些东西，觉得那可能包含着她成名的秘密之一。",
	},
	[94100220] = {
		id = 94100220,
		text = "本节点可获取信件：【无义的悼亡】\
本节点已是本次测试时珊瑚树的最远点，这封信件在本次测试中暂无使用途径，敬请期待后续更新……",
	},
	[94100221] = {
		id = 94100221,
		text = "本节点已是本次测试时珊瑚树的最远点，敬请期待后续更新……",
	},
	[94100222] = {
		id = 94100222,
		text = "本节点已是本次测试时珊瑚树的最远点，敬请期待后续更新……",
	},
