	[104193010] = {
		id = 104193010,
		text = "技术手段胜利",
	},
	[104220001] = {
		id = 104220001,
		text = "你驶入了一片空域，从四周散布的残骸来看，有一大批本以为自己是猎人的海盗变成了猎物。你并不清楚是谁对他们下的手，不过他们已经离开了，这片空域只剩下绵延不绝的战舰残骸和装备废料。\
但在把它看成「寻宝之旅」前，还是要注意海盗们的优良传统：包括但不限于诡雷和自动炮台的各种陷阱。",
	},
	[104220002] = {
		id = 104220002,
		text = "你的战舰收到一段信息，内容是一个顶着滑稽冗长头衔的海盗头子，要求你把手头的货物全部贡献出来，当成这片空域的「秩序维护费」。\
他煞有介事地吹嘘着他麾下的「义警」的骁勇善战，这群杂牌军已经占据了地利，甚至连舰炮都已经预热完毕，只等你给出一个答复。",
	},
	[104220003] = {
		id = 104220003,
		text = "这片星区似乎在庆祝什么节日，你甚至从舷窗都能看到五颜六色的礼花和灯光。",
	},
	[104220004] = {
		id = 104220004,
		text = "本来这只是一次惯例的全舰自检，但是自检程序运行之后没多久，整艘船就断电了。\
接着，伴着响彻全船的报警声和紧急照明灯的灯光，你的船员们查到了这次飞船跳闸趴窝的原因：船上的原材料加工设备负荷过高，短路了。",
	},
	[104220005] = {
		id = 104220005,
		text = "人活得够久就总会碰到各种各样奇怪事情。你明明只是打算在星区里的酒吧找人打听一点消息，可是刚坐上吧台，点的酒水就被邻座的人帮忙买了单。\
不速之客是一位追求刺激的职业赌徒。他说法他赌的第一场——今天会不会遇见一位有资本上桌的人——已经赢了，所以想邀请你一起前往赌桌，见证他的第二次胜利。",
	},
	[104220006] = {
		id = 104220006,
		text = "在进入这个星区时，护盾发生仪、星相仪和雷达同时发出了啸叫。\
你不偏不倚冲进了一条高速移动的大量小行星组成的小行星带，大量撞在护盾上的微型小行星严重干扰了读数。不过在你确认了小行星带的内容后，船员们的尖叫声一点都不比仪器小。\
在船员和仪器都平复下来以后，一个奢侈的烦恼摆在了大家面前：我们的停留时间和开采设备只允许开采一部分小行星带，而各个区域的矿脉构成都不完全相同。",
	},
	[104220007] = {
		id = 104220007,
		text = "这个空间站云集了无数伤病患者，从历经血战的船员到身患旧疾的老人。\
一群医生正在这里开展临时的义诊。他们来自一个闻名遐迩的无国界组织，没有固定的诊所。\
考虑到药物和医疗设备都是耗材，他们的医疗服务也需要收费，但比大医院低廉很多。",
	},
	[104220008] = {
		id = 104220008,
		text = "一道流星划过船上的观景窗。这其实在星际航行中是司空见惯的事情，但星相仪的读数可不常见——它是所谓的许愿星！",
	},
	[104220009] = {
		id = 104220009,
		text = "一只巨大的败者孤零零地飘荡在附近，它早已死去很久，但它身上却有异常高的能量读数。\
调查之后，你发现导致它成为「败者」的那次燔祭，其实只是莫名中断，而并结束。\
王星辐照的能量仍然在它体内，并未固化成型。这样的能量完全可以稍作加工，为你所用。",
	},
	[104220010] = {
		id = 104220010,
		text = "在你飞船附近出现了一些异常读数。考虑到可能的袭击，你用探测器确认了一下。\
异常读数的来源，是一团无主的云状魔力团。从周围的痕迹来看，应该是有人在准备一场术法，而在准备过程中遭到了别人的袭击，只能仓皇逃跑。\
你可以对这团魔力加以干涉，让它为你所用。但这团魔力即将消散，所以需要思考一下，使用何种干涉手段，取得风险与效果的平衡。",
	},
	[104220011] = {
		id = 104220011,
		text = "明明船里的空气过滤系统工作正常，可你却闻到了一股不祥的刺鼻气味。在宇宙中，这种情形只可能是由超凡因素引发。\
一场不正规的燔祭仪式——在神秘的建筑中，有大量形迹可疑的邪教徒，还有缭绕全场的硫磺气味，以及堆放在中央祭坛上的一些，极其违法的……祭品。\
「燔祭」本该是「人对星的仪式」，但你却发现这场仪式的献祭对象，是一个伪装成王星的「败者」。",
	},
	[104220012] = {
		id = 104220012,
		text = "一场突发的诺伦航道乱流。在乱流中，太空的景象变得扭曲模糊。\
奇特的颜色和光芒交织在一起，你立刻让引擎满速运转，可是脱离这片乱流并不简单。货舱的锁被引力扯开了，有一批货物被甩了出去。\
现在，虽然你勉强离开了乱流中心，但你从取景窗都还能看到货柜信标的光点——那个在乱流中心做着布朗运动的就是了。",
	},
	[104220013] = {
		id = 104220013,
		text = "你进入这片空域没多久，附近科研空间站的主管就嚷嚷说你干扰了他们的观测数据。\
不过，在你用自己的数据补上之后，主管立刻变得兴高采烈起来，邀请你去空间站做客。\
愉快的聊天时光很快就结束了。作为提供海量数据的报酬，主管慷慨地提供了一份模块化设备的设计稿。\
可惜你临时基地里的加工中心性能有限，对产物要求越高，造出一堆废品的概率就越高。而且这份设计稿阅后即焚，毕竟它还在专利保护期。",
	},
	[104220014] = {
		id = 104220014,
		text = "有一艘无人废船孤零零的在这个星区飘荡。从褪色的表面来看，这艘船已经在这里漂泊了很久。船身上巨大的破洞也在无声诉说它当年的经历。\
你登上了这艘船。墙壁上的控制面板和显示屏已经失去了光彩，只剩下模糊的残影。你小心翼翼地穿行在狭窄的走廊和房间之间，不时发现一些废弃的设备和物品，它们曾经是这艘船的生命线和活力源泉。\
而现在，这艘船上除了你以外，唯一还会动的，是仍在这艘废船上徘徊的警卫机器人。",
	},
	[104220015] = {
		id = 104220015,
		text = "一艘巨大的商船正在展销。一封标题为《请不要错过这些星际珍宝！》的邮件飞进了你的通知栏。\
邮件内容包括了各式各样的物品，从罕见的宝石到古老的文物，从高科技装备到稀有的资源，东西实在是太多了。哪怕是拖滑动条，这封邮件你也拖了一分钟才到底。\
你注定只能量力而行。",
	},
	[104291001] = {
		id = 104291001,
		text = "你收到了一个微弱的识别信号。根据信号的格式来看，这个信号来自于一艘本应在百年前就失联了的巨型空间站。\
保险起见，你在前往信号源的路上查了下这个空间站的信息，但却发现这个空间站消失的原因就语焉不详，就好像从理事会到这个空间站所属的公司上上下下都在刻意隐瞒一样。\
靠近空间站后，仔细观察着它的外观。它的外表已经被时间和太空中的微陨石磨损得不成样子，布满裂痕和凹陷。从外壳的破裂处透出阴暗的灯光，使你产生一种不安的感觉。\
但你舰上的远距离扫描仪显示里面有着明显异样的信号。这个空间站失踪百年的原因或许和这个信号有关……",
	},
	[104291002] = {
		id = 104291002,
		text = "以一个沉寂百年的空间站来说，这里有些过于热闹了——无数机器人在这个空间站徘徊着。还好，空间站本身也足够大，有的是空间让你一边前进一边和他们玩捉迷藏。\
你穿过一条条昏暗的走廊，注意力紧绷地观察着每一个角落。随着你的脚步，废弃空间站的秘密逐渐揭开。你发现了房间内的控制面板，通过它你能够获取有关这个空间站的信息。\
突然，一阵机械声响起。你回过头，目光与一台安保机器人那发着红光的摄像头打了个正着。毫无感情的电子合成音从这个铁皮罐头里响起。“本空间站已下达人员净空命令！立即离开！否则将采取强制措施！”",
	},
	[104291003] = {
		id = 104291003,
		text = "你在附近调查了一圈。除了遗迹里的微弱动静——远距离扫描仪扫描的结果是安保机器人——外遗迹里似乎没什么太奇怪的地方。看起来你是第一个访客。\
不过不是最后一个：飞船捕捉到了一个跃迁信号。很快，一艘舰身画满了各种花纹，一副嘻哈风格外观的飞船到来。\
飞船的主人注意到你后就用公开频道向你发通信。“嗨，哥们！到得早啊！介不介意兄弟搭把手，有财大家一起发？”一张笑嘻嘻的男人的大脸把屏幕挤得满满当当。好吧，探险家或者说拾荒者里这种自来熟性格的确不算少。",
	},
	[104291004] = {
		id = 104291004,
		text = "“当你看到一只蟑螂时，就意味着附近有一千只。”这里的安保机器人让你想起这句话。从大量机器人中杀出重围后，你快速的向空间站深处的信号源冲刺。\
到不只是因为得躲蟑螂，还有一个原因是你收到了来自自己飞船的远距离通讯，有别的飞船也来到了这个空间站。觊觎这里的人不止你一个。\
当到达空间站最深处时，一个穿着机甲的男人挡在你的面前。他的机甲看起来是崭新的，准是那个“别的飞船”的人。你试着跟他对话说明自己不打算对人动武，但他没有回复你。仔细一看，他的表情扭曲，目光失去焦点，彷佛失去了理智。\
你不由得看向他的背后。他背后有着一个不知是什么的发光体。看起来这就是那个信号源。“本空间站已下达人员净空命令！”之前机器人的电子音重新在你脑中回荡起来。这个空间站之前净空人员是因为这个？",
	},
	[104291005] = {
		id = 104291005,
		text = "事实证明，十个笑嘻嘻的自来熟里八个都不是好东西。那个大块头在进入空间站后没多久，就找到机会甩开了你自己一个人向着深处的信号源全速冲刺。\
你的提案只是六四分账，但他的算盘打的看起来是他一个人独吞。为了避免这种事情发生，你也赶紧冲了进去。随着你们二人的相对距离越来越短，你感受到一种不寻常的能量弥漫在周围，让你的心跳加速。\
在空间站深处，你重新见到了他。之前那张笑嘻嘻的蠢脸说真的不怎么讨喜，可他现在这副目光失去焦点，表情空洞扭曲，彷佛失去了理智的样子更惹人厌。\
你不由得看向他的背后。他背后有着一个不知是什么的发光体，看起来这就是那个信号源。这人是不聪明没错，但他这么快失去了理智会不会和那个发光体有关？",
	},
	[104291006] = {
		id = 104291006,
		text = "很凑巧的是，你手边的控制面板有个大大的红色按键，还写着紧急锁定。\
你猛地敲下那个按钮，转身狂奔。在你逃跑时，眼角余光瞥到身后的屏蔽门轰的一声关了起来，把机器人隔在了门外。蒙对了！\
脚步刚停下来，你就收到了来自自己飞船的远距离通讯，有别的飞船也来到了这个空间站。觊觎这里的人不止你一个。\
当到达空间站最深处时，你看见一个发出黄绿色光芒的奇怪发光体。虽然听不到声音，但你知道这就是那个信号源。你只看着光芒就能认知到这道光是有生命有要传达的信息的，他在邀请——\
败者！还是有智慧的高级败者！你下意识咬了一下舌尖，痛觉让你恢复了神智。他在试图控制你。看起来得先应付一下这个麻烦的家伙。",
	},
	[104291007] = {
		id = 104291007,
		text = "常识告诉我们，这个大块头这种笑法是那种明明心里有别的算盘，但是却试图让人认为他毫无心机的笑法。背对着这种人的下一秒背上就会多出一个刀柄——刀身在身体里。\
你决定自己一个人先他一步冲入空间站，留下他在公频气急败坏，一边骂娘一边急匆匆的下船。\
当到达空间站最深处时，你看见一个发出黄绿色光芒的奇怪发光体。虽然听不到声音，但你知道这就是那个信号源。你只看着光芒就能认知到这道光是有生命有要传达的信息的，他在邀请——\
败者！还是有智慧的高级败者！你下意识咬了一下舌尖，痛觉让你恢复了神智。他在试图控制你。看起来得先应付一下这个麻烦的家伙。",
	},
	[104291008] = {
		id = 104291008,
		text = "你选择了与这个失去理智的人展开战斗。你明白，他说到底只是个被钱蒙蔽了双眼的拾荒客，没有对他下死手的必要。\
留手的结果是战斗结束的比预期的晚。在漫长的战斗之后，他躺在地上，昏迷不醒。你确认了他的生理状况，看起来这个大块头再睡十多个小时候就能醒了。没有错手杀死一个不该死的人，这让你感觉很好——不过是不是有些太好了？\
你环顾四周，发现一开始还在的那个发光体已经消失了。它在战斗的混乱中找到了逃脱的机会。虽然你未能亲眼目睹它的离去，但你可以感觉到它的消失才是让你心里产生宁静和安全感的原因。\
现在，这个空间站看起来安全了。该走人了……不过这个遗迹该怎么办？",
	},
	[104291009] = {
		id = 104291009,
		text = "既然这个大块头和他的新朋友关系这么好，那么我们也没必要再纠缠下去。你急忙穿过空间站的走廊，寻找着通往出口的路线。心跳加速，你时刻保持着警觉，生怕遭遇更多的危险。\
在逃离的过程中，你突然来到了空间站的控制中心。你不禁停下脚步，凝视着这个曾经承载着命运之轮的地方。你的心中涌起一种奇妙的感觉，仿佛能够感受到百年前居民们留下的足迹和他们的决意。\
在这一刻，你意识到这个废弃空间站之前的神秘消失其实是当时的居民主动对外屏蔽了这里。他们为了保护外界，将这个地方隐藏起来，防止这个败者危害他人。而现在，这个责任落在了你的手上……",
	},
	[104291010] = {
		id = 104291010,
		text = "你脑中的压力时轻时重。这个败者也意识到控制你是一件很困难的事情，但他也还在犹豫要不要继续拿你当傀儡。\
这种时候就需要推一把。你开始回忆你之前的经历，除你之外的那个陌生的外来者——压力瞬间减轻了。看起来这个败者决定去改向他伸出魔爪。\
现在，你必须尽快离开这个废弃空间站。不只是为了你自己，还为了那个非自愿替你争取时间的垫背倒霉鬼和这个败者本身。出去之后，你第一件事就是通知理事会的人要求他们派出专门的人处理这件事。\
但出去之前你还有一些时间，而你的逃跑路线碰巧路过这个空间站的主仓库，准确的说，你人现在就在它门口……",
	},
	[104291011] = {
		id = 104291011,
		text = "身为败者应该比人类更加明白柿子挑软的捏这个道理。既然它不明白，那么就该让他长长教训。\
这个败者几乎没有任何战斗能力，你起手的一记试探攻击就让他丢盔弃甲开始求饶。它开出的价码还算琳琅满目：在这个空间站积累的财产，百年前它和理事会交易的内幕，甚至是它自己愿意为你当牛做马。但这些加起来都不如它彻底消失带给你的安心感诱人。\
事情结束了，你像电影结局的演出一样事了拂衣去，留下一个遗迹给事后收尾的人。毕竟你有自己的事情要忙：这个败者在求饶时提到了它和理事会有交易。理事会当年换了什么？为了什么？这件事应该可以好好深挖一下内幕，你甚至为此把它被干掉后留下的碎片带了回来……",
	},
	[104292001] = {
		id = 104292001,
		text = "你航行的飞船正穿越一片无垠的虚空。突然，一处异常的闪光吸引了你的注意力。\
那是一道反光，反光的物体是一个……保险箱？你把这个箱子捞上了船。\
这个保险箱明显价值不菲。单是保险箱上这个采用约翰逊保密协议的电子锁它的价格就够你的船整整一次定期检修的检修费，更不提拿来做这个保险箱箱体的材料价格预估下来起码是锁价格后面再加个零。\
你搜索了下可能的失主。发现网上有人讨论说一群穿着打扮就像古代地球某个国家的黑手党——这个国家好像叫「意大利」？——的组织正在找这个箱子，甚至闹了好几场流血冲突。看起来他们是真的很重视这个箱子……………………",
	},
	[104292002] = {
		id = 104292002,
		text = "你明智地选择将发现的保险箱归还给黑帮团伙。在一个空间站的暗巷中，你与黑帮的代表会面，交还了保险箱。这个自称为教父的黑帮代表表达了对你的感激之情，并保证会给予你适当的报酬。\
你以为这个故事已经结束，然而，过了一两天，另一个陌生黑帮也开始找起了这个保险箱。这一群自称他们的证据更加有说服力：船主公开了箱子的内容物外几乎所有的信息。\
看起来前一个黑帮只是在冒领。但现在箱子的确不在你手边，而且这个新黑帮的样子让你不由得怀疑这个箱子里的东西大概有些麻烦。",
	},
	[104292003] = {
		id = 104292003,
		text = "你决定保留那个被你捡到的保险箱，好奇心驱使你想弄清楚这个保险箱里到底有什么。然而，过了一两天，黑帮团伙找到了你，要求归还保险箱。话语中充满了黑帮惯例的“你不听我的话的话可得吃不了兜着走”的暗示。\
不过有两个问题：1，虽然嘴上说的难听，但这群黑帮看起来也并没像他们自吹自擂的那么强大，摆平他们其实不算什么难事儿。2，你搜到了一些新的消息，似乎还有另一群黑帮也在找这个箱子…………\
你意识到自己陷入了（至少）两个黑帮之间的争斗中，成为了这场争夺战的焦点。这个保险箱或者说他的内容物可能远比你想象的更有价值，而围绕着他即将展开一场大风波……",
	},
	[104292004] = {
		id = 104292004,
		text = "你告知了新的黑帮保险箱的去处。他们的代表臭着一张脸感谢了你。\
