你要考虑的内容是这个箱子到底是谁的，以及内容物是什么。这次看起来还是动用一下理事会的关系比较好。然后，事情又出现了新的变化。在这个星区附近的理事会的一名高官才是这个保险箱的真正的主人，而这个箱子里的东西是他贪污的赃物。\
