	[104292005] = {
		id = 104292005,
		text = "围绕着这个保险箱的乐子就没停过。过了几天后，原本意气风发带着保险箱离开的黑帮又找了回来，但这一次他们灰头土脸，为首的出面人脸上甚至还能看到包扎。\
他们几乎是抱着你的腿求着你让你帮忙保护他们一段时间，在这几天，有许多人因为这个保险箱而找上他们，小半个帮派的人都受伤或失踪——这种场合的失踪明显意味着不知道尸体被丢进了哪条阴沟——他们现在最后的救命稻草只剩下你了。\
不过更大的乐子源于你在理事会的关系。通过可靠渠道证实，在这个星区附近的理事会的一名高官才是这个保险箱的真正的主人，而这个箱子里的东西是他贪污的赃物。\
这场围绕着保险箱的台风刮了回来，事情变得越来越有趣了。",
