		text = "你跟着参与了这场猴戏，顺利的摆平了他们抢回了这个不属于在场任何人的保险箱。\
接下来的发展让你想起了黑帮电影的固定桥段之一：兔死狗烹。雇你来的这群不长眼的家伙决定让你永远闭嘴，来保证这个保险箱的事情再没有任何人知道。然后就是你把他们也揍得满地找牙。\
你带着这个保险箱回去后又过了一周。保险箱的失主亲自找到了你，为自己的小弟居然蠢到试图灭你口这点向你低头谢罪，同时表示愿意割一大笔肉来换取他的小秘密的安全。不过这个问题明显还有另一个解法……",
