	[104292008] = {
		id = 104292008,
		text = "本来你觉得既然他们提出虎口夺食，那么他们自然已经做好了准备。但你并没有想到他们居然以失败收场了。而你更没想到的是他们还被对方抓了几条舌头，在拷问下招出了他们的雇主就是这个理事会官员这件事。果然只有蠢货才会去干黑道这行。\
过了几天，这条结论得到了二次证实：最早拿走保险箱的黑帮又找到你这里了。这次他带着他刚刚享受过胜利的“强大军团”过来，打算确保保险箱的事情只有他们自己知道，这样他们能把这个箱子卖出一个非常好的价位。\
你立刻代失主从他们那里赎回了箱子——用拳头。好吧，现在这个箱子的闹剧也开始让人觉得无聊了，该把这个箱子怎么办？",
