	[104292009] = {
		id = 104292009,
		text = "你决定给这群可怜巴巴的落水狗当一次保镖。接下来，你经历了一场规模不小的战斗：狗急跳墙的理事会官员为了找回赃物居然动用了理事会在台面上的武装力量。难怪这群黑帮会满地找牙。\
在整件事情彻底平息后，留下的只剩下一个巨大的烂摊子：狗急跳墙的官员本身和他的私兵一起被你们摆平了，留下了一大堆私产。事情莫名其妙地变成了分赃大会。但，反正能拿到钱，结果好就没问题。",
	},
	[104292010] = {
		id = 104292010,
		text = "“保险箱风暴”平息的速度和他发起的速度一样都快的离谱。在你回绝了他们的恳求之后没多久，这群黑帮就仿佛从来没存在在这个世界上过一样。而你自己作为最早发现它的人，现在却完全无人关心。\
这么个灯下黑的状况其实是你乐见的：这个箱子的问题非常大。纵观全局，无论是最早的理事会官员，还是几任接手人，他们拿到这个保险箱后似乎都被这个箱子（或者说它的内容物）所影响，行事方针变的过于冒进和欠考虑，而且对箱子的占有欲也异常的强，这群哪怕被全灭也不愿意放手箱子的黑帮就是最好的证据。\
你通过理事会的关系再次确认后得知这个被贪下来的赃物出自土星天星环的某个巨型败者残骸，而这个官员在抢回保险箱后做的第一件事是准备「对土星天星环的实地调研」。这个箱子里究竟藏了什么……？",
	},
	[104292011] = {
		id = 104292011,
		text = "保险箱脱手还是脱晚了点。在你把这个烫手山芋丢出去后隔天，一条“理事会重拳出击捣毁本地黑帮”的新闻就传遍了大街小巷。你很清楚这其实是那个官员的灭口之举。\
就这个行动时间和规模来看，这记铁拳应该本来会砸到你自己头上，现在仅仅只是因为箱子又易主了所以那个官员需要先确保箱子而已。而对你的灭口尝试也肯定会开始。\
不过有这些时间就已经够了——你做好了准备，静等这条疯狗咬上门。\
在你打发那群不自量力的打手之后，这个箱子让人哭笑不得的又回到了你的手上——为什么这群打手抢回箱子后会带着它出任务？\
发病的狂犬肯定需要处理，还是先考虑怎么处理这个问题比较好，为什么每个人都对这个箱子有异常强的占有欲这种事情可以后面再研究。",
	},
	[104292012] = {
		id = 104292012,
		text = "有一种电子游戏的分类叫做塔防。这种游戏的玩法是会不断有人来攻击玩家，玩家需要做好防御击溃攻击方。从这种解构主义的角度来说，你一直在围绕着这个箱子玩塔防。而现在，敌人的头目，保险箱的原主人，理事会的官员本身出现了。\
身为文化人和办公室政治家，这个理事会官员的面子做的比较足，没有上来就舞刀弄枪。不过他在和我们交涉时表现的明显不太对劲：他宁愿散尽自己的几乎全部财产也想把这个箱子要回来带着它去土星天，就好像只要得到它那么世间再没任何值得他关心的事情了一样。土星天和这个箱子里究竟有什么东西？这么仔细想想，之前你一直坚持把这个箱子留在手边也很奇怪……",
	},
	[104293001] = {
		id = 104293001,
		text = "你的船正在常规巡航，船员们忙碌地执行各自的任务。突然间，控制面板上传来一道警报声，一道神秘的裂隙在你们的观测范围极限处出现了。\
接下来的事情几乎在瞬间发生：那个裂隙缓缓张开，顺着裂隙你勉强可见里面有无数机器人正准备从裂缝中涌出。它们的身形扭曲，机械肢体闪烁着危险的光芒，仿佛是从未知的恶梦中诞生的恶魔。\
毫无疑问，这是一个危险的突发事件，而他落在了我们肩上 。这样的问题该如何解决？",
	},
	[104293002] = {
		id = 104293002,
		text = "你毫不犹豫地选择主动出击，迎接这突如其来的威胁。当你靠近裂缝时，裂缝中的机器人们突然涌出，组成了大量的机械敌人。就造型而言，他们的样子与败者没有不同。而更让人迟疑的是那裂缝仍然存在于机器人敌群的背后，这个神秘的通道的另一端似乎还有更多惊喜等着我们。\
你迅速观察了周围的局势，面对这群敌人和裂缝的双重威胁，你需要做出关键的决策。是选择与敌人战斗，试图消灭这个威胁，还是冒险进入裂缝，探索其中的未知领域？",
	},
	[104293003] = {
		id = 104293003,
		text = "单是观测到的机器人可能还好，但裂缝后几乎能够确定不止这些。考虑到这层，你决定采取明智的策略，选择后撤并寻求其他人类的支援。你下令舰船迅速调整航向，脱离危险区域。\
在你后撤的过程中，裂缝中也在不断涌出新的机器人。你一边通知着星域附近的所有人类——无论理事会，中枢，还是中立派——一边在观测距离极限尽可能的收集他们的信息。\
幸运的是，你的求援并没有被忽视。几艘理事会和中枢的战舰捕捉到了你的信号，迅速赶到战场与你汇合，形成了一个临时的战时同盟。\
作为这个临时舰队的指挥官（理事会和中枢都拒绝服从对方的人的命令），你需要决定应对这场突发危机的方针。",
	},
	[104293004] = {
		id = 104293004,
		text = "你果断决定先解决敌人，再深入调查裂缝的秘密。毕竟，只有将看门的敌人消灭，才能保证自己接下来的行动不受干扰。\
你利用战舰和机甲的连携攻势与敌人展开了激烈的对抗，火光在战场上闪烁。随着战斗的进行，你的优势愈发明显。最终，随着一发舰炮射击，机器人们的防御被正式击溃。\
然而，这并不是他们的终结。溃败的机器人们绝大部分在后退重组，但你注意到其中一小部分机器人聚合成了一个巨大能量核心的样子。这个核心闪烁着神秘的光芒，显然具有巨大的能量——虽然从你船上的读数来看能量在不断的衰弱。而那道裂缝的强度似乎也和这颗核心一样在变的衰弱。",
	},
	[104293005] = {
		id = 104293005,
		text = "你认识到与其与可见的敌人战斗，还不如将注意力放在裂缝背后的潜在敌人上，因为它们可能更具威胁性。\
决定行动方针后，你和你的战舰开始尝试穿越巨兽的防御空档钻进裂缝之中。还好，这些敌人的火力无法快速击溃你的护盾，所以这个挑战并不算难。\
裂缝中的景象与正常的宇宙空间截然不同，你能观测到的只有指向裂缝另一端的切伦科夫辐射，以及充斥四处的大量的小机器人。这些小机器人无休止地穿行、转动着。然而，他们对你的舰船并不构成直接的威胁，仅仅只是在某种规则下自动运行着。你小心翼翼地避开它们，继续前进。\
你的战舰在裂缝中穿梭，经过一段时间的探索，发现裂缝深处居然有着一个巨型结构。这个巨型结构向你发送了一个通信请求——他表示他是这些机器人的控制单元，在这里他反而无法攻击你，所以希望和能成功杀进来的你“好好谈谈”。",
	},
	[104293006] = {
		id = 104293006,
		text = "双方的兵力严阵以待，气氛紧张而焦灼。\
不知是哪一方开的第一枪，但一眨眼的功夫，整个战场上就布满了双方准备已久的各式炮弹、激光、导弹、机甲等。\
随着战斗的进行，你开始注意到机器人们似乎有着固定的逻辑。它们的行动模式不太随机，而是按照一定的规则进行。这种不太智能的表现应该可以加以利用。\
但利用它的话，显然就得进行一番详细精确的战术制定和执行了。你们临时拼凑的同盟能够执行这样的战术吗？",
	},
	[104293007] = {
		id = 104293007,
		text = "你与临时拼凑的舰队集结在裂缝远处，小心避免刺激机器人直接开火。与一群不知究竟有多少的敌人直接交战的风险太过庞大，但他们是机器人，所以电子战应该是个可以考虑的手段。\
在一段时间的观察后，一艘友军的战舰告诉你他们侦测到奇怪的控制信号从裂缝深处传出，裂缝外的机器人都是通过这个信号控制的。这个发现为你提供了一个关键的信息：影响信号将意味着胜利。",
	},
	[104293008] = {
		id = 104293008,
		text = "在你调查核心时，核心突然向你发送了通信请求。\
你接入通信后，这颗核心开始向你陈述他们的来历和目的。他们解释道，他们是被研发出来的自律机械，旨在与「天敌」——一段额外的解释后你才明白指的是败者——进行战斗。他们来到这个地方，并非是与人类本身有什么敌意，而是在他们的观测下人类或多或少都有败者的特征。\
这番话让你思考良久。如今太阳系的人类文明都管败者叫做败者，天敌这个称呼过于奇怪。于是你巧妙地问了几个问题试图套话，结果算是意料之外情理之中：这群机器人至少肯定不是如今的太阳系文明制造的，而他们的造物主似乎已经灭亡，所以没人继续维护他们的思考逻辑，他们才会闹出今天这样的乱子。\
既然已知今天发生的一切都只是一场天大的误会，那么这些机器人也决定先行离开这里。但有一个问题还留在你心里：这些机器人是来自于遥远的未来吗？不然为什么他们会有人类将成为败者的结论？",
	},
	[104293009] = {
		id = 104293009,
		text = "你决定先答应控制单元的请求。毕竟听他说完再干掉他也不迟。\
控制单元开始向你陈述他们的来历和目的。他们解释道，他们是被研发出来的自律机械，旨在与「天敌」——一段额外的解释后你才明白指的是败者——进行战斗。他们来到这个地方，并非是与人类本身有什么敌意，而是在他们的观测下人类或多或少都有败者的特征。\
这番话让你思考良久。如今太阳系的人类文明都管败者叫做败者，天敌这个称呼过于奇怪。于是你巧妙地问了几个问题试图套话，结果算是意料之外情理之中：这群机器人至少肯定不是如今的太阳系文明制造的，而他们的造物主似乎已经灭亡，所以没人继续维护他们的思考逻辑，他们才会闹出今天这样的乱子。\
既然已知今天发生的一切都只是一场天大的误会，那么这些机器人也决定先行离开这里。但有一个问题还留在你心里：这些机器人是来自于遥远的未来吗？不然为什么他们会有人类将成为败者的结论？",
	},
	[104293010] = {
		id = 104293010,
		text = "你们的舰队一边与机器人远远的周旋，一边尝试现场黑入这些机器人。\
经过不懈的努力，你们终于成功地编写出了一种程序，这种程序能够伪造机器人的遥控信号，让他们的军队溃不成军。\
在快速的分发与安装程序后，战斗正式开始。机器人很快就意识到了你们在做什么，但无法有效抵抗来自病毒和舰队的双重攻击。他们的防御系统逐渐崩溃，战斗能力受到严重削弱。随着时间的推移，他们开始出现系统故障，不再可能挽回败局。\
最终，在涌出的机器人被解决后，裂缝自身关闭了自己，留下大量被黑掉但还没破坏掉的机器人在外面。\
这场不大不小的乱子迎来了结局，不过你的船员突然进来告诉你说他们初步调查了一下回收回来的机器人，这些机器人看来……他们应用的技术和如今的技术体系完全不同？这可是个大发现，应该会有很多人对此感兴趣。",
	},
