		text = "+20<img src=\"srpg_res02\" size=\"33,33\" verticaloffset=\"-3\"></>金刚凝胶，+20<img src=\"srpg_res03\" size=\"33,33\" verticaloffset=\"-3\"></>影响因子",
	},
	[107930101] = {
		id = 107930101,
		text = "+10<img src=\"srpg_res02\" size=\"33,33\" verticaloffset=\"-3\"></>金刚凝胶，获得<img src=\"srpg_item\" size=\"33,33\" verticaloffset=\"-3\"></>「机器人的残骸」",
	},
	[107930102] = {
		id = 107930102,
		text = "+30<img src=\"srpg_res01\" size=\"33,33\" verticaloffset=\"-3\"></>赎罪奖券",
	},
	[108200011] = {
		id = 108200011,
		text = "手快有，手慢无，区区几个陷阱算不上什么。",
	},
	[108200012] = {
		id = 108200012,
		text = "从设计之初，机器人就是拿来做这个的。",
	},
	[108200013] = {
		id = 108200013,
		text = "太空时代的宝库，自然由太空时代的怪盗解决。",
	},
	[108200014] = {
		id = 108200014,
		text = "",
	},
	[108200021] = {
		id = 108200021,
		text = "很不巧，动武这事还是我们更专业。",
	},
	[108200022] = {
		id = 108200022,
		text = "拿那个爆炸箱装些赎金给他们，我们来放个漂亮的大烟花。",
	},
	[108200023] = {
		id = 108200023,
		text = "就这么直接顶着火力离开吧。",
	},
	[108200024] = {
		id = 108200024,
		text = "",
	},
	[108200031] = {
		id = 108200031,
		text = "航行已经让船员们都够累了，大家刚好放个假，顺便让船开始自检。",
	},
	[108200032] = {
		id = 108200032,
		text = "应该有节日优惠吧？",
	},
	[108200033] = {
		id = 108200033,
		text = "既然有这么多人，应该可以顺便找找买家。",
	},
	[108200034] = {
		id = 108200034,
		text = "嗯……比赛规则里没写「禁止职业选手参赛」。",
	},
	[108200041] = {
		id = 108200041,
		text = "这台老设备的确有些过时了。",
	},
	[108200042] = {
		id = 108200042,
		text = "让它过载着把最后的余热发挥完吧。",
	},
	[108200043] = {
		id = 108200043,
		text = "其实只要把少量部件换成随手采集的光叶纤维，这头老驴就还能继续拉磨盘。",
	},
	[108200051] = {
		id = 108200051,
		text = "账户里的赎罪奖券还有一些盈余。",
	},
	[108200052] = {
		id = 108200052,
		text = "挪用一些维护预算，应该问题不大。",
	},
	[108200053] = {
		id = 108200053,
		text = "一口气搞到这么多研究用耗材的机会可不多。",
	},
	[108200054] = {
		id = 108200054,
		text = "保证稳赢不输的必胜策略，就是不要上桌。",
	},
	[108200061] = {
		id = 108200061,
		text = "白送的东西，除了飞来横祸，我们都要。",
	},
	[108200062] = {
		id = 108200062,
		text = "贵金属总能拿来换别的东西，但别的东西不一定能换贵金属。",
	},
	[108200063] = {
		id = 108200063,
		text = "诺伦尼姆储备多少都不嫌多。",
	},
	[108200064] = {
		id = 108200064,
		text = "居然有化石，这在研究上可是大有用途。",
	},
	[108200071] = {
		id = 108200071,
		text = "上一次去医院是什么时候？",
	},
	[108200072] = {
		id = 108200072,
		text = "之前的战斗的旧伤偶尔也在隐隐作痛。",
	},
	[108200073] = {
		id = 108200073,
		text = "把治疗机会留给更需要它的人们吧。",
	},
	[108200074] = {
		id = 108200074,
		text = "这些医生精湛的只有医术，应该不会拒绝得到一些防身术。",
	},
	[108200081] = {
		id = 108200081,
		text = "你闭起双眼，开始向它祈祷。",
	},
	[108200082] = {
		id = 108200082,
		text = "奢求更多，可能会得不偿失。",
	},
	[108200083] = {
		id = 108200083,
		text = "神秘的力量开始在体内回荡，你的小小心思被它捕捉到了。",
	},
	[108200084] = {
		id = 108200084,
		text = "临渊羡鱼，不如退而结网——而当你有网的时候，主动捕捉大鱼也是一个备选项。",
	},
	[108200091] = {
		id = 108200091,
		text = "相遇的时候，并非商队的营业时间，\
但他们还是热情地发来讯息，招呼你去消费一番。",
	},
	[108200092] = {
		id = 108200092,
		text = "虽然他们的本业是海盗，但做起生意来的态度不算太差，甚至可以给出「中等偏下」的好评——也就是明显高于某些网红小吃店主。\
不过，如果你在他们面前露出破绽，他们可能就会对你的实力重新评估，来决定要不要继续在你面前扮商人了。",
	},
	[108200093] = {
		id = 108200093,
		text = "相遇的时候，并非商队的营业时间，\
但他们还是热情地发来讯息，招呼你去消费一番。",
	},
	[108200094] = {
		id = 108200094,
		text = "相遇的时候，并非商队的营业时间，\
但他们还是热情地发来讯息，招呼你去消费一番。",
	},
	[108200095] = {
		id = 108200095,
		text = "这些「异宝」的来源显然不合法……所以价格也「异常」昂贵。\
但，物有所值。",
	},
	[108200096] = {
		id = 108200096,
		text = "你在茫茫宇宙中遇见了三十六义人之一「信风」的崇拜者。这对你并不是什么新鲜事，但小鱼还是觉得蛮值得她偷偷自豪一下的。",
	},
	[108200101] = {
		id = 108200101,
		text = "",
	},
	[108200102] = {
		id = 108200102,
		text = "",
	},
	[108200103] = {
		id = 108200103,
		text = "",
	},
	[108200104] = {
		id = 108200104,
		text = "",
	},
	[108200105] = {
		id = 108200105,
		text = "",
	},
	[108200106] = {
		id = 108200106,
		text = "",
	},
	[108200111] = {
		id = 108200111,
		text = "看看它伪装王星的底气。",
	},
	[108200112] = {
		id = 108200112,
		text = "向「败者」祈求的是什么？「失败」吗？",
	},
	[108200113] = {
		id = 108200113,
		text = "与骗子的交易从来都不会有什么好结果，而与执法部门的交易只是多半没有。",
	},
	[108200114] = {
		id = 108200114,
		text = "「理事卿之声」今天还有更重要的行程。",
	},
	[108200121] = {
		id = 108200121,
		text = "既然海神已经收下了供品，那就不该再让风暴毁掉这艘船。",
	},
	[108200122] = {
		id = 108200122,
		text = "一边是饿扁肚子，另一边是承受一些可以修复的伤害，孰轻孰重一目了然。",
	},
	[108200131] = {
		id = 108200131,
		text = "该死的专利侵权费。还是按加工中心的性能来吧。",
	},
	[108200132] = {
		id = 108200132,
		text = "科学总是伴随着失败和牺牲……反正最多也就牺牲一份蓝图。",
	},
	[108200133] = {
		id = 108200133,
		text = "成功由10%的才能、20%的努力、30%的谨慎和40%的运气组成。",
	},
	[108200134] = {
		id = 108200134,
		text = "人有多大胆，船有多大产。",
	},
	[108200141] = {
		id = 108200141,
		text = "除了这些不长眼的机器人外，没人介意你挪用无主的资源。",
	},
	[108200142] = {
		id = 108200142,
		text = "对逝去的生命抱持一些额外的尊重吧。",
	},
	[108200151] = {
		id = 108200151,
		text = "消费主义是害人邪道……不过这些东西看着不错，就买一点。",
	},
	[108200152] = {
		id = 108200152,
		text = "接下来还得过日子的……",
	},
	[108200153] = {
		id = 108200153,
		text = "买买买买买买！",
	},
	[108200154] = {
		id = 108200154,
		text = "奸商的嘴，骗人的鬼。",
	},
	[108910011] = {
		id = 108910011,
		text = "这么巨大的遗迹里肯定有无数的财富和秘密等着我们。",
	},
	[108910012] = {
		id = 108910012,
		text = "这个遗迹过于古怪了。花几分钟调查一下周围也不算晚。",
	},
	[108910013] = {
		id = 108910013,
		text = "整件事危险的气味都快溢出来了，撤吧。",
	},
	[108910021] = {
		id = 108910021,
		text = "我们并不归贵地管辖。",
	},
	[108910022] = {
		id = 108910022,
		text = "OK，我们从你眼前离开，仅限你眼前。",
	},
	[108910031] = {
		id = 108910031,
		text = "好啊，不过麻烦你交点入伙钱。",
	},
	[108910032] = {
		id = 108910032,
		text = "去去去，晓不晓得先到先得？",
	},
	[108910041] = {
		id = 108910041,
		text = "冤有头债有主，我们只是自卫反击。",
	},
	[108910042] = {
		id = 108910042,
		text = "这个鬼东西绝对不秒，撤！",
	},
	[108910051] = {
		id = 108910051,
		text = "冤有头债有主，我们只是自卫反击。",
	},
	[108910052] = {
		id = 108910052,
		text = "这个鬼东西绝对不秒，撤！",
	},
	[108910061] = {
		id = 108910061,
		text = "你想找玩伴的话外面有的是。",
	},
	[108910062] = {
		id = 108910062,
		text = "人心不足蛇吞象这句话听过吗，败者？",
	},
	[108910071] = {
		id = 108910071,
		text = "你想找玩伴的话外面有的是。",
	},
	[108910072] = {
		id = 108910072,
		text = "人心不足蛇吞象这句话听过吗，败者？",
	},
	[108910081] = {
		id = 108910081,
		text = "解决这个空间站的危害让他重新启用可是大功一件，没有功劳也有苦劳吧。",
	},
	[108910082] = {
		id = 108910082,
		text = "这么大的空间站总会被别人发现，趁着第三个第四个人来之前先卷卷细软赶紧跑。",
	},
	[108910091] = {
		id = 108910091,
		text = "以现在对败者的研究来看，只要做好准备它就不足为惧。让理事会里的专业人士处理吧。",
	},
	[108910092] = {
		id = 108910092,
		text = "趁着潘多拉的魔盒里面的魑魅魍魉还没飞出去赶紧把他合上。那艘没人用的飞船就收拾一下废弃掉吧。",
	},
	[108910101] = {
		id = 108910101,
		text = "出去之后告诉理事会消息时可得去掉点关键信息了。",
	},
	[108910102] = {
		id = 108910102,
		text = "夜长梦多，越早离开越好。而且这些情报本身就可以找理事会换钱。",
	},
	[108910111] = {
		id = 108910111,
		text = "对这些碎片进行施术可以一定程度上重现它经历的事情。",
	},
	[108910112] = {
		id = 108910112,
		text = "一百年说长也不算长，理事会内肯定还有认得它的人……",
	},
	[108920011] = {
		id = 108920011,
		text = "这个箱子感觉再留着要出事，还是还回去吧。",
	},
	[108920012] = {
		id = 108920012,
		text = "这个箱子里看起来有不少好宝贝啊。",
	},
	[108920013] = {
		id = 108920013,
		text = "这么个烫手山芋哪儿来的回哪儿去。",
	},
	[108920021] = {
		id = 108920021,
		text = "既然事办错了那么就尽力挽回吧。",
	},
	[108920022] = {
		id = 108920022,
		text = "无论内容物是什么，这个保险箱都绝对不是什么好东西，还是远远躲开为好。",
	},
	[108920031] = {
		id = 108920031,
		text = "还请收下，毕竟这么贵重的东西丢了主人一定非常着急。",
	},
	[108920032] = {
		id = 108920032,
		text = "这个箱子的价值越来越高了，我们大概能办个拍卖会？",
	},
	[108920041] = {
		id = 108920041,
		text = "这么大的热闹当然要保证最好的观众席。",
	},
	[108920042] = {
		id = 108920042,
		text = "有句老话叫做火中取栗。",
	},
	[108920051] = {
		id = 108920051,
		text = "额外的高危补助麻烦你们做好准备。",
	},
	[108920052] = {
		id = 108920052,
		text = "我们围观就好，自己接的麻烦自己慢慢消化。",
	},
	[108920061] = {
		id = 108920061,
		text = "一旦售出，概不退换。小心惹祸上身。",
	},
	[108920062] = {
		id = 108920062,
		text = "你还留着这个保险箱的原因之一是你有这个掸掉飞来的火星的能力。",
	},
	[108920071] = {
		id = 108920071,
		text = "选项A：接受他的封口费",
	},
	[108920072] = {
		id = 108920072,
		text = "抱歉，你晚来了一分钟，举报信我已经寄出去了……理事会的奖金可不比你开的价码低。",
	},
	[108920081] = {
		id = 108920081,
		text = "***先生，你也不想让你自己失去工作对吧？嘿嘿嘿……",
	},
	[108920082] = {
		id = 108920082,
		text = "等到这个箱子的失主事发被革职后，箱子的密码肯定能套出来。",
	},
	[108920091] = {
		id = 108920091,
		text = "引发了这一堆事情的保险箱的内容物一定很值钱。",
	},
	[108920092] = {
		id = 108920092,
		text = "这个该死的箱子大概本身就克主，还是不要留在手边为好。",
	},
	[108920101] = {
		id = 108920101,
		text = "想要搞清楚这个谜底最好的手段就是自己研究。",
	},
	[108920102] = {
		id = 108920102,
		text = "直面它的风险难以预期。不如让理事会消化这个箱子，反正你可以通过理事会的渠道调出研究记录。",
	},
	[108920111] = {
		id = 108920111,
		text = "",
	},
	[108920121] = {
		id = 108920121,
		text = "这个箱子看起来真的不太对劲，还是拿他卖个好价钱吧。",
	},
	[108920122] = {
		id = 108920122,
		text = "你贪污的小秘密我们会帮你保密，不过我们也有些想调查的东西……",
	},
	[108930011] = {
		id = 108930011,
		text = "看起来他们还没开始攻击。无论交涉还是战斗都要抢占先机！",
	},
	[108930012] = {
		id = 108930012,
		text = "小心驶得万年船，尤其没人知道他们有多强。",
	},
	[108930013] = {
		id = 108930013,
		text = "那个裂缝距离很远。给我们通信范围内的所有空间站通知这件事，然后在远处等税金发挥作用就好。",
	},
	[108930021] = {
		id = 108930021,
		text = "这群看门狗大概不会乖乖放我们进去……",
	},
	[108930022] = {
		id = 108930022,
		text = "比起这些敌人，还是它背后的裂缝更危险。",
	},
	[108930031] = {
		id = 108930031,
		text = "硬碰硬的时候到了。炮灰的储备还足够吗，机器人？",
	},
	[108930032] = {
		id = 108930032,
		text = "他们的底牌很可能没出完，谨慎为上。",
	},
	[108930041] = {
		id = 108930041,
		text = "赶紧解决这个核心，免得夜长梦多。",
	},
	[108930042] = {
		id = 108930042,
		text = "整件事都透着一股子莫名其妙的味道。稍微调查一下那个核心。",
	},
	[108930051] = {
		id = 108930051,
		text = "我们之间没什么好谈。",
	},
	[108930052] = {
		id = 108930052,
		text = "没准这能成为人类和新种族的第一次接触呢……？",
	},
	[108930061] = {
		id = 108930061,
		text = "比起可能的满盘皆输，还是小胜更能接受。",
	},
	[108930062] = {
		id = 108930062,
		text = "虽然阵营不同，但他们都是职业军人，应该能够胜任这个挑战。",
	},
	[108930071] = {
		id = 108930071,
		text = "",
	},
	[108930081] = {
		id = 108930081,
		text = "",
	},
	[108930091] = {
		id = 108930091,
		text = "虽然留下了大量不解之谜，但至少这些机器人的问题不用再操心了。",
	},
	[108930101] = {
		id = 108930101,
		text = "",
	},
	[108930102] = {
		id = 108930102,
		text = "",
	},
	[109000001] = {
		id = 109000001,
		text = "测试商人a",
	},
	[110000001] = {
		id = 110000001,
		text = "测试商人a相关描述",
	},
	[111100001] = {
		id = 111100001,
		text = "来袭敌人",
	},
	[111100002] = {
		id = 111100002,
		text = "来袭敌人",
	},
	[111100003] = {
		id = 111100003,
		text = "来袭敌人",
	},
	[111100004] = {
		id = 111100004,
		text = "来袭敌人",
	},
