		text = "事件描述",
	},
	[113210002] = {
		id = 113210002,
		text = "（临时）游荡的医疗设施。",
	},
	[113210003] = {
		id = 113210003,
		text = "（临时）努力生存吧。",
	},
	[113210004] = {
		id = 113210004,
		text = "来打一架",
	},
	[113210005] = {
		id = 113210005,
		text = "选择你的结盟势力",
	},
	[113210006] = {
		id = 113210006,
		text = "（临时）向你问好。",
	},
	[113210007] = {
		id = 113210007,
		text = "（临时）值得探索……",
	},
	[113210008] = {
