	},
	[113210012] = {
		id = 113210012,
		text = "（临时）值得探索……",
	},
	[113210013] = {
		id = 113210013,
		text = "（临时）值得探索……",
	},
	[113210014] = {
		id = 113210014,
		text = "（临时）值得探索……",
	},
	[113211000] = {
		id = 113211000,
		text = "在<span color=\"#ff6c00\">总览界面</>中，可以看到<span color=\"#ff6c00\">败者首领</>还有多少回合抵达，以及其它各种有用的信息。\
在初次体验远航时，就对<span color=\"#ff6c00\">败者首领</>一串三，也许并不是新人的正常追求……\
本次的「引导式远航」，只要胜过第一个<span color=\"#ff6c00\">败者首领</>，就可成功结束了。\
也请在后续的挑战中，不必立刻追求完全的「通关」。\
战胜了任何一个<span color=\"#ff6c00\">败者首领</>，都会得到奖励。\
请利用这些奖励<span color=\"#ff6c00\">成长</>起来，然后获取完全的<span color=\"#ff6c00\">胜利</>吧。",
	},
	[113211001] = {
		id = 113211001,
		text = "星图上的<span color=\"#ff6c00\">有色连线</>，代表了「已经探索」，前往时不需要消耗回合。\
而<span color=\"#ff6c00\">白色连线</>的相邻坐标，需要消耗1回合，跃迁抵达。\
<span color=\"#ff6c00\">无连线</>的坐标，不可直接抵达。",
	},
	[113211002] = {
		id = 113211002,
		text = "在单次远航期间，我们会获得一种名为<span color=\"#ff6c00\">金刚凝胶</>的资源（航程结束时不保留）。\
金刚凝胶可以做很多事，包括建造建筑、晋升建筑、刷新选择、替换队员……\
宇宙中的游商，也支持用金刚凝胶购买货物。",
	},
	[113211003] = {
		id = 113211003,
		text = "一般的遭遇战过后，奖励是3选1的<span color=\"#ff6c00\">建筑蓝图</>。\
造出<span color=\"#ff6c00\">建筑</>以后，会让你在战斗中获得一些……强大的，或者稀奇古怪的能力。\
有了<span color=\"#ff6c00\">建筑蓝图</>，就可以安排工人来建造。\
星图上有<span color=\"#ff6c00\">建筑格</>，去那里部署你的新建筑吧。",
	},
	[113211004] = {
		id = 113211004,
		text = "手中的<span color=\"#ff6c00\">建筑蓝图</>超过<span color=\"#ff6c00\">10张</>时，就无法获得新的建筑蓝图了。\
请时刻注意这一点，否则就只能放弃多出的建筑蓝图，白白浪费。",
	},
	[113211005] = {
		id = 113211005,
		text = "<span color=\"#ff6c00\">拆除</>建筑时，返还30金刚凝胶。\
因此，有不需要的<span color=\"#ff6c00\">建筑蓝图</>时，可以在空的<span color=\"#ff6c00\">建筑格</>上操作一番，换取金刚凝胶，也可有效避免手中的建筑蓝图达到10张。\
<span color=\"#ff6c00\">召回</>建筑时，需要花费金刚凝胶。（在本次教学中，临时免费）\
被<span color=\"#ff6c00\">召回</>的建筑，将化作建筑蓝图，回归手中。\
请注意，在<span color=\"#ff6c00\">建筑格界面上方</>，可以<span color=\"#ff6c00\">快捷选择</>所有建筑格。",
	},
	[113211006] = {
		id = 113211006,
		text = "许多建筑的名字里，存在着相同的字眼，比如火星、木星、海王、冥王、黑月……等等。它们被称为<span color=\"#ff6c00\">字段</>。\
在建筑蓝图的卡框下方，也标识着这张建筑蓝图的<span color=\"#ff6c00\">字段</>。\
获得<span color=\"#ff6c00\">字段</>建筑时，星图界面上会亮起一格计数。\
当计数格凑满一竖条时，<span color=\"#ff6c00\">字段效果</>就会生效。",
	},
	[113211007] = {
		id = 113211007,
		text = "当你有3个同样的建筑时，你可以选择<span color=\"#ff6c00\">晋升</>1个建筑，使其变强，并获得一个<span color=\"#ff6c00\">异宝</>作为奖励。\
晋升的操作，仍然是在<span color=\"#ff6c00\">建筑格</>完成。\
<span color=\"#ff6c00\">晋升</>建筑时，花费50金刚凝胶。\
你获得了3张相同的<span color=\"#ff6c00\">建筑蓝图</>，现在回到前面的<span color=\"#ff6c00\">建筑格</>，去试试晋升吧。",
	},
	[113211008] = {
		id = 113211008,
		text = "许多建筑的效果描述里，存在着相同的字眼，这被称为<span color=\"#ff6c00\">关键词</>。\
异宝的<span color=\"#ff6c00\">关键词</>，以及部分角色技能中的<span color=\"#ff6c00\">关键词</>，也都是通用的。\
除了通用的建筑以外，也有一些建筑的效果，只对特定角色生效。",
	},
	[113211009] = {
		id = 113211009,
		text = "己方角色在下一场战斗中，会继承前一场战斗的<span color=\"#ff6c00\">HP</>。\
——也就是说，在高压难度之下，角色的<span color=\"#ff6c00\">HP</>总会越打越少。\
如果想替换出战角色，则需消耗XX<span color=\"#ff6c00\">金刚凝胶</>。（在本次教学中，临时免费）",
	},
	[113211010] = {
		id = 113211010,
		text = "己方角色在下一场战斗中，会继承前一场战斗的<span color=\"#ff6c00\">HP</>。\
——也就是说，在高压难度之下，角色的<span color=\"#ff6c00\">HP</>总会越打越少。\
如果想替换出战角色，则需消耗<span color=\"#ff6c00\">金刚凝胶</>。",
	},
	[113211011] = {
		id = 113211011,
		text = "每次使用战舰技能，消耗一发<span color=\"#ff6c00\">舰武载弹</>。\
<span color=\"#ff6c00\">舰武载弹</>和金刚凝胶一样，都是在远航中获得，在航程结束时不保留的。",
	},
	[113211012] = {
		id = 113211012,
		text = "每次远航中，先后有3个<span color=\"#ff6c00\">败者首领</>，会出现在<span color=\"#ff6c00\">巡航基地</>附近，每回合向<span color=\"#ff6c00\">巡航基地</>移动1格。\
<span color=\"#ff6c00\">败者首领</>抵达<span color=\"#ff6c00\">巡航基地</>后，每回合扣取1点<span color=\"#ff6c00\">生存值</>。\
战胜所有的<span color=\"#ff6c00\">败者首领</>，本次远航即<span color=\"#ff6c00\">胜利</>结束。",
	},
	[113211013] = {
		id = 113211013,
		text = "星图中存在着从一开始就可以透过迷雾、直接见到的<span color=\"#ff6c00\">商店类坐标</>。\
商店对远航是重要的，请注意规划路线。\
在星图的远处，也存在着从一开始就可以透过迷雾、直接见到的<span color=\"#ff6c00\">邪星燔祭</>。\
<span color=\"#ff6c00\">邪星燔祭</>是远航中最困难的战斗（本次教学星图中没有，请在后续探索），如能战胜，可以获得额外奖励。",
	},
	[113220001] = {
		id = 113220001,
		text = "一艘失事的运输船，孤零零地飘流在宇宙空间中。\
你启动了扫描仪，发现里面还有一些乘员撤离时来不及带走的货物。",
	},
	[113220002] = {
		id = 113220002,
		text = "附近的贸易港向你求助，希望你让渡一层保护膜发生器，因为他们在附近空域感到危险。\
他们愿意提供高额报酬。",
	},
	[113220003] = {
		id = 113220003,
		text = "你驶入了一片空域，从四周散布的残骸来看，有一大批本以为自己是猎人的海盗变成了猎物。你并不清楚是谁对他们下的手，不过他们已经离开了，这片空域只剩下绵延不绝的战舰残骸和装备废料。\
但在把它看成「寻宝之旅」前，还是要注意海盗们的优良传统：包括但不限于诡雷和自动炮台的各种陷阱。",
	},
	[113220004] = {
		id = 113220004,
		text = "一台小运输机撞到你战舰的护盾上，把自己撞关了机。\
商队的主人向你致歉，说运输机是他们正在销毁的故障品。他们愿意赔偿此次事故造成的损失。",
	},
	[113220005] = {
		id = 113220005,
		text = "",
	},
	[113220006] = {
		id = 113220006,
		text = "你进入这片空域没多久，附近科研空间站的主管就嚷嚷说你干扰了他们的观测数据。\
不过，在你用自己的数据补上之后，主管立刻变得兴高采烈起来，邀请你去空间站做客。\
愉快的聊天时光很快就结束了。作为提供海量数据的报酬，主管慷慨地提供了一份模块化设备的设计稿。",
	},
	[113220007] = {
		id = 113220007,
		text = "失去动力的理事会武器运输船出现在你的扫描仪上，你尝试发送通信请求，但没有获得任何回应。\
看来所有乘员不是死了就是弃船离开了。你需要在它爆炸之前尽快决断。",
	},
	[113220008] = {
		id = 113220008,
		text = "你在宇宙中解决了一只巨型半机械「败者」之后，附近的一个科研空间站对你表示了感谢。\
作为你对这明显大有问题的「故障运输组」闭口不言的报酬，他们希望你能看得上他们的一些数据，或者科研成果。",
	},
	[113220009] = {
		id = 113220009,
		text = "一艘船向你发送了一个奇怪的请求：他希望向你购买一套船员所用的餐具。\
怪人自称船员生活用品收藏家，而你觉得反正餐具也不值钱……",
	},
	[113220010] = {
		id = 113220010,
		text = "一艘飞船找上了你，询问是否愿意提供一些引擎运行数据。\
通话者自称造船厂设计师，希望收集一些市场用户的需求。\
他愿意为此提供一些报酬，答应他的请求并没什么损失。",
	},
	[113220011] = {
		id = 113220011,
		text = "这片星区似乎在庆祝什么节日，你甚至从舷窗都能看到五颜六色的礼花和灯光。\
庆典上的射击气球小游戏……嗯……比赛规则里没写「禁止职业选手参赛」。",
	},
	[113220012] = {
		id = 113220012,
		text = "",
	},
	[113220013] = {
		id = 113220013,
		text = "「培养皿理财」的经理联系了你，向你推销一种超自然理财产品。",
	},
	[113220014] = {
		id = 113220014,
		text = "一座外形华美的小型空间站，向你发送了通信请求。\
站主表示他租用了「这艘游艇」，在外游玩，现在需要一些金刚凝胶，库存却刚好告罄了。\
他希望用他手头的东西向你换取一些金刚凝胶。",
	},
	[113220015] = {
		id = 113220015,
		text = "空间站的站长向你告知，他们正在研究一个将诺伦尼姆高效转化的项目。\
很幸运，通过交涉，你可以分享一些成果。",
	},
	[113220016] = {
		id = 113220016,
		text = "一场突发的诺伦航道乱流。在乱流中，太空的景象变得扭曲模糊。\
奇特的颜色和光芒交织在一起，你立刻让引擎满速运转，可是脱离这片乱流并不简单。\
现在，虽然你勉强离开了乱流中心，但你从取景窗都还能看到一个货柜信标的光点——那个在乱流中心做着布朗运动的就是了。",
	},
	[113220017] = {
		id = 113220017,
		text = "",
	},
	[113220018] = {
		id = 113220018,
		text = "",
	},
	[113220019] = {
		id = 113220019,
		text = "",
	},
	[113220020] = {
		id = 113220020,
		text = "进入道场时，道场的教官一眼就认出你是经验丰富的资深人士，而非求学者。\
但他们表示，如果能你能共享一些对武装的操纵数据，那他们就愿意免费向你的船员们赠送一套教材，和一次现场课程。",
	},
	[113220021] = {
		id = 113220021,
		text = "进入道场时，道场的教官一眼就认出你是经验丰富的资深人士，而非求学者。\
但他们表示，如果能你能共享一些对武装的操纵数据，那他们就愿意免费向你的船员们赠送一套教材，和一次现场课程。",
	},
	[113220022] = {
		id = 113220022,
		text = "一群猎人发来通讯，希望你能够协助他们猎捕「败者」。\
事成之后，他们会向你分享一些富余的建筑蓝图。",
	},
	[113220023] = {
		id = 113220023,
		text = "一群赏金猎人发来通讯，他们的船在战斗中被打坏了引擎。\
他们希望你能够把它拖拽到附近的安全区，他们愿意为此分你一些建筑蓝图。",
	},
	[113220024] = {
		id = 113220024,
		text = "监视「败者」活动的哨站向你求助。他们的耗材已经消耗殆尽，但补给依然遥遥无期。\
哨兵们希望用建筑蓝图向你换取武力上的帮助，来解燃眉之急。",
	},
	[113220025] = {
		id = 113220025,
		text = "一群海盗——对，没错，海盗——向你求助。\
他们说有人跑来「黑吃黑」，但他们早已金盆洗手，当年作恶时所用的装备也不剩多少，所以无力自卫。",
	},
	[113220026] = {
		id = 113220026,
		text = "金刚凝胶不是一种物质，而是诺伦尼姆（Nornium）在物质界——也就是宏观宇宙——的投影。",
	},
	[113220027] = {
		id = 113220027,
		text = "一只巨大的败者孤零零地飘荡在附近，它早已死去很久，但它身上却有异常高的能量读数。\
调查之后，你发现导致它成为「败者」的那次燔祭，其实只是莫名中断，而并结束。\
王星辐照的能量仍然在它体内，并未固化成型。这样的能量完全可以稍作加工，为你所用——比如为你的巡航基地加固一层保护膜。",
	},
	[113220028] = {
		id = 113220028,
		text = "眼前的东西让你想到一句老话：生命总能自寻出路。",
	},
	[113220029] = {
		id = 113220029,
		text = "一种曾经并不罕见，但如今已经很难找到大型矿床的的太空矿物：甜热浮石。\
在拓扑变换为「内天体」成分时，无毒无副作用。\
——正是由于证明了这一点，它的价格才开始了连绵不绝的逐步攀升。",
	},
	[113220030] = {
		id = 113220030,
		text = "本来这只是一次惯例的全舰自检，但是自检程序运行之后没多久，整艘船就断电了。\
航行已经让船员们都够累了，大家刚好放个假，顺便让船开始自检。\
没想到，自检过程中的备件仓库AI，从角落里自行翻出了被大家完全遗忘的好东西……",
	},
	[113220031] = {
		id = 113220031,
		text = "明明船里的空气过滤系统工作正常，可你却闻到了一股不祥的刺鼻气味。在宇宙中，这种情形只可能是由超凡因素引发。\
一场不正规的燔祭仪式——在神秘的建筑中，有大量形迹可疑的邪教徒，还有缭绕全场的硫磺气味，以及堆放在中央祭坛上的一些，极其违法的……祭品。\
「燔祭」本该是「人对星的仪式」，但你却发现这场仪式的献祭对象，是一个伪装成王星的「败者」。",
	},
	[113220032] = {
		id = 113220032,
		text = "护盾发生仪、星相仪和雷达同时发出了啸叫。\
摆渡人来到你的面前，告诉你，前进是有风险的，但如果拒绝摆渡，他就不再恭候。",
	},
	[113220036] = {
		id = 113220036,
		text = "【PH】事件描述 - 信风角色卡",
	},
