	},
	[113220077] = {
		id = 113220077,
		text = "向斩击祭坛祈祷吧——虽然不知道是谁在回应，但你会获得「斩击」的回报。",
	},
	[113220078] = {
		id = 113220078,
		text = "向枪击祭坛祈祷吧——虽然不知道是谁在回应，但你会获得「枪击」的回报。",
	},
	[113220079] = {
