	[113221000] = {
		id = 113221000,
		text = "一艘，或者说半艘，损坏的废船，出现在了你的面前。\
看标志，似乎是什么生物科研组织。你开始猜测这艘船只剩一半的理由了。\
读数显示，货舱里已经没有生物反应，只有废船本身还值点钱。",
	},
	[113221001] = {
		id = 113221001,
		text = "一种曾经并不罕见，但如今已经很难找到大型矿床的的太空矿物：甜热浮石。\
在拓扑变换为「内天体」成分时，无毒无副作用。\
——正是由于证明了这一点，它的价格才开始了连绵不绝的逐步攀升。",
	},
	[113221002] = {
		id = 113221002,
		text = "眼前的东西让你想到一句老话：生命总能自寻出路。",
	},
	[113221003] = {
		id = 113221003,
		text = "本来这只是一次惯例的全舰自检，但是自检程序运行之后没多久，整艘船就断电了。\
航行已经让船员们都够累了，大家刚好放个假，顺便让船开始自检。\
没想到，自检过程中的备件仓库AI，从角落里自行翻出了被大家完全遗忘的好东西……",
	},
	[113221004] = {
		id = 113221004,
		text = "一艘，或者说半艘，损坏的废船，出现在了你的面前。\
看标志，似乎是什么生物科研组织。你开始猜测这艘船只剩一半的理由了。\
读数显示，货舱里已经没有生物反应，只有废船本身还值点钱。",
	},
	[113221005] = {
		id = 113221005,
		text = "一种曾经并不罕见，但如今已经很难找到大型矿床的的太空矿物：甜热浮石。\
在拓扑变换为「内天体」成分时，无毒无副作用。\
——正是由于证明了这一点，它的价格才开始了连绵不绝的逐步攀升。",
	},
	[113221006] = {
		id = 113221006,
		text = "眼前的东西让你想到一句老话：生命总能自寻出路。",
	},
	[113221007] = {
		id = 113221007,
		text = "本来这只是一次惯例的全舰自检，但是自检程序运行之后没多久，整艘船就断电了。\
航行已经让船员们都够累了，大家刚好放个假，顺便让船开始自检。\
没想到，自检过程中的备件仓库AI，从角落里自行翻出了被大家完全遗忘的好东西……",
	},
	[113221008] = {
		id = 113221008,
		text = "一艘，或者说半艘，损坏的废船，出现在了你的面前。\
看标志，似乎是什么生物科研组织。你开始猜测这艘船只剩一半的理由了。\
读数显示，货舱里已经没有生物反应，只有废船本身还值点钱。",
	},
	[113221009] = {
		id = 113221009,
		text = "一种曾经并不罕见，但如今已经很难找到大型矿床的的太空矿物：甜热浮石。\
在拓扑变换为「内天体」成分时，无毒无副作用。\
——正是由于证明了这一点，它的价格才开始了连绵不绝的逐步攀升。",
	},
	[113221010] = {
		id = 113221010,
		text = "眼前的东西让你想到一句老话：生命总能自寻出路。",
	},
	[113221011] = {
		id = 113221011,
		text = "本来这只是一次惯例的全舰自检，但是自检程序运行之后没多久，整艘船就断电了。\
航行已经让船员们都够累了，大家刚好放个假，顺便让船开始自检。\
没想到，自检过程中的备件仓库AI，从角落里自行翻出了被大家完全遗忘的好东西……",
	},
	[113250201] = {
		id = 113250201,
		text = "一条紧急求助信息发送到了你的船上，信息来源是附近的一处「败者」残骸。\
研究「败者」生态的学者遭到了生物材料猎手的无差别袭击，他们没有任何自卫能力，只能恳求拯救。",
	},
	[113250202] = {
		id = 113250202,
		text = "附近的贸易港向你求助，希望你保护他们。他们愿意提供高额报酬。",
	},
	[113250203] = {
		id = 113250203,
		text = "一位打扮光鲜的富豪狼狈的向你求助。他说他是一位「败者」遗骸收藏家，收集藏品的时候被打劫了。\
他雇佣的保镖已经作鸟兽散，急需任何愿意提供帮助的人来保护他。",
	},
	[113250204] = {
		id = 113250204,
		text = "一群海盗——对，没错，海盗——向你求助。\
他们说有人跑来「黑吃黑」，但他们早已金盆洗手，当年作恶时所用的装备也不剩多少，所以无力自卫。",
	},
	[113260101] = {
		id = 113260101,
		text = "观测员回报说，出现了像是遥远星云、实际上却又近得多的一种现象。\
这个报告让船员们感到一种格外的安心，因为他们知道那是「领航星兽」的赐福，作为三种航行星象之一，能将一些事象导向更良性的结果。",
	},
	[113260201] = {
		id = 113260201,
		text = "进入星区时，你感到周围比之前的空域亮了一些。观测四周时，你发现了如同龙状星云般的现象——那是「护航邪龙」的赐福，一般不会照在你这种正直人士的身上……不过，管它呢。\
作为三种航行星象之一，「护航邪龙」通常而言有助于财富概念的上升。",
	},
	[113260301] = {
		id = 113260301,
		text = "跃迁结束时，船上几乎所有读数全都变得异常起来。\
这种良性的异常，来源于一团看似星云、实则降临在附近星域的宇宙现象：「司航蜂鸟」的赐福。作为三种航行星象之一，司航蜂鸟会在战斗中令你化险为夷。",
	},
	[113270101] = {
		id = 113270101,
		text = "相遇的时候，并非商队的营业时间，\
但他们还是热情地发来讯息，招呼你去消费一番。",
	},
	[113270201] = {
		id = 113270201,
		text = "虽然他们的本业是海盗，但做起生意来的态度不算太差，甚至可以给出「中等偏下」的好评——也就是明显高于某些网红小吃店主。\
不过，如果你在他们面前露出破绽，他们可能就会对你的实力重新评估，来决定要不要继续在你面前扮商人了。",
	},
	[113280101] = {
		id = 113280101,
		text = "一群猎人发来通讯，希望你能够协助他们猎捕「败者」。\
事成之后，他们会向你分享一些富余的弹药。",
	},
	[113280201] = {
		id = 113280201,
		text = "一群赏金猎人发来通讯，他们的船在战斗中被打坏了引擎。\
他们希望你能够把它拖拽到附近的安全区，他们愿意为此分你一些燃料。",
	},
	[113280301] = {
		id = 113280301,
		text = "一座外形华美的小型空间站，向你发送了通信请求。\
站主表示他租用了「这艘游艇」，在外游玩，但他错估了燃料的存量。\
他希望用他手头的东西向你换取一些燃料。",
	},
	[113280401] = {
		id = 113280401,
		text = "空间站的站长向你告知，他们在研究一个将诺伦尼姆高效转化的项目，但不幸花光了研究预算。\
他希望用一些研究副产物，向你换取急需的预算和耗材。",
	},
	[113280501] = {
		id = 113280501,
		text = "监视「败者」活动的哨站向你求助。他们的耗材已经消耗殆尽，但补给依然遥遥无期。\
哨兵们希望用多余的弹药向你换取金刚凝胶，来解燃眉之急。",
	},
	[113280601] = {
		id = 113280601,
		text = "「培养皿理财」的经理联系了你，向你推销理财产品。",
	},
	[113280701] = {
		id = 113280701,
		text = "「培养皿投资」的经理联系了你，向你推销投资项目。",
	},
	[113280801] = {
		id = 113280801,
		text = "眼前的东西让你想到一句老话：生命总能自寻出路。",
	},
	[113280802] = {
		id = 113280802,
		text = "一种曾经并不罕见，但如今已经很难找到大型矿床的的太空矿物：甜热浮石。\
在拓扑变换为「内天体」成分时，无毒无副作用。\
——正是由于证明了这一点，它的价格才开始了连绵不绝的逐步攀升。",
	},
	[113280901] = {
		id = 113280901,
		text = "一艘失事的运输船，孤零零地飘流在宇宙空间中。\
你启动了扫描仪，发现里面还有一些乘员撤离时来不及带走的货物。",
	},
	[113281001] = {
		id = 113281001,
		text = "一艘，或者说半艘，损坏的废船，出现在了面前。\
看标志，似乎是什么科研组织。你开始猜测这艘船只剩一半的理由了。\
读数显示，货舱里还有一些内容不明的货物。",
	},
	[113281101] = {
		id = 113281101,
		text = "失去动力的理事会武器运输船出现在你的扫描仪上，你尝试发送通信请求，但没有获得任何回应。\
看来所有乘员不是死了就是弃船离开了。",
	},
	[113281201] = {
		id = 113281201,
		text = "跃迁之后，你发现战舰正身处在一团诺伦粒子云中。\
严格来说，它并不是粒子云，甚至不是一种物质，而是诺伦尼姆正在向物质界「降下」的一种过程。",
	},
	[113281301] = {
		id = 113281301,
		text = "进入道场时，道场的教官一眼就认出你是经验丰富的资深人士，而非求学者。\
但他们表示，如果能你能共享一些对武装的操纵数据，那他们就愿意免费向你的船员们赠送一套教材，和一次现场课程。",
	},
	[113281401] = {
		id = 113281401,
		text = "一台小运输机撞到你战舰的护盾上，把自己撞关了机。\
商队的主人向你致歉，说运输机是他们正在销毁的故障品。他们愿意赔偿此次事故造成的损失。",
	},
	[113281501] = {
		id = 113281501,
		text = "附近的空间站发生了一场小事故，几个货柜从货港飞了出来。\
你帮他们捞回了货舱后，货港负责人按规矩该给你一笔佣金。不过他们流动资金短缺，所以希望用一些资源或者商品来代替佣金。",
	},
	[113281601] = {
		id = 113281601,
		text = "你在宇宙中解决了一只巨型半机械「败者」之后，附近的一个科研空间站对你表示了感谢。\
作为你对这明显大有问题的「故障运输组」闭口不言的报酬，他们希望你能看得上他们的一些数据，或者科研成果。",
	},
	[113281701] = {
		id = 113281701,
		text = "一艘船向你发送了一个奇怪的请求：他希望向你购买一套船员所用的餐具。\
怪人自称船员生活用品收藏家，而你觉得反正餐具也不值钱……",
	},
	[113281801] = {
		id = 113281801,
		text = "一艘飞船找上了你，询问是否愿意提供一些引擎运行数据。\
通话者自称造船厂设计师，希望收集一些市场用户的需求。\
他愿意为此提供一些报酬，答应他的请求并没什么损失。",
	},
	[113281901] = {
		id = 113281901,
		text = "在跃迁结束时，你感到一阵头晕目眩。\
这种不适，似乎是来源于那颗「宣告者」之星，或称「信使星」的……辐射。\
你意识到眼前有一封信，需要由你来拆封——",
	},
	[113291101] = {
		id = 113291101,
		text = "星图上的蓝色连线，代表了「已经探索」，前往时不需要消耗燃料。\
而白色连线的相邻坐标，需要消耗1份诺伦燃料，跃迁抵达。\
超过1格距离的坐标，不可以直接跃迁，需要一步一步前往。\
在界面右侧，可以看到「诺伦燃料」的剩余量。",
	},
	[113291401] = {
		id = 113291401,
		text = "虽然「假助手」仍然保持着初见面时那种，基本上只会回复「1」的印象，但在逐渐相识以后，小鱼发现，对方是个很聪明的人，而且极有耐心，仿佛一切事务对他来说都只是待办事项。\
不需要反复确认，在他回复你「1」的时候，你就已经可以相信，他会把事情办妥。",
	},
	[113291501] = {
		id = 113291501,
		text = "而小鱼自己是一个怎样的人呢？\
……从这个故事以「小鱼上大当」为开端来看，也大概可以猜到，小鱼不是一个非常可靠的人。\
不过，「假助手」对小鱼的观感也还算可以。作为一个笨手笨脚的临时船员，她最大的好处是不反驳自己。\
虽然派她去给生态舱的绿植浇水的时候，她浇坏了放在一边的音响。\
但在修完音响以后，她给船上选的BGM的品味算是勉强过关。",
	},
	[113291601] = {
		id = 113291601,
		text = "前方出现了理事会的守军。\
跃迁结束的一瞬间，你们已经互相探测到了彼此的存在。",
	},
	[113292101] = {
		id = 113292101,
		text = "在星图上，有时会见到一些可以打捞的资源。\
比如各种贵金属，在航行中会被自动兑换成理事会的「赎罪奖券」。这是一种航行中的代币，只能在单次航行中使用。\
在界面右侧，可以看到「赎罪奖券」的数量。\
消费赦免了罪，从而获得进入乐园的资格——这就是「复乐园理事会」发行「赎罪奖券」的含义。",
	},
	[113292201] = {
		id = 113292201,
		text = "这是第二种航行时所的资源，金刚凝胶。\
它也是一种航行中的代币，我们很快就会用到它。\
在界面右侧，可以看到「金刚凝胶」的数量。\
金刚凝胶不是一种物质，而是诺伦尼姆（Nornium）在物质界——也就是宏观宇宙——的投影。",
	},
	[113292301] = {
		id = 113292301,
		text = "第三种航行时所的资源，影响因子。\
这是最后一种航行中的代币，三种代币都不会保留到下次航行。\
在界面右侧，可以看到「影响因子」的数量。\
作为代币的影响因子，是对科研成果与资料的一种转化。",
	},
	[113292401] = {
		id = 113292401,
		text = "在航行中，遇到一般的战斗时，战斗后的奖励，会是3选1的「建筑蓝图」。\
造出建筑以后，会让你在战斗中获得一些……强大的，或者稀奇古怪的能力。\
下次跃迁时，试着从战斗中获取「建筑蓝图」吧。",
	},
	[113292501] = {
		id = 113292501,
		text = "有了建筑蓝图，就可以安排工人来建造。\
星图上有「建筑格」，去那里部署你的新建筑吧。",
	},
	[113292601] = {
		id = 113292601,
		text = "许多建筑的名字里，存在着相同的字眼，这被称为「字段」。\
获得「字段」建筑时，星图界面上会亮起一格计数。当计数格凑满一竖条时，「字段」效果就会生效。\
等会就在界面上点击一下「字段」，看看效果吧。\
另外，当你有3个同样的建筑时，你可以选择晋升，增强建筑，并且获得一个「异宝」作为奖励。\
晋升的操作，仍然是在「建筑格」完成。\
来，这是三张一样的蓝图，拿去试试。",
	},
	[113292701] = {
		id = 113292701,
		text = "水星（Mercury），墨丘利之星，在占星术的意义上，影响着人类的智力和通讯活动的效率。\
在水星逆行时，即所谓「水逆」时期，通常是文书错误、信息丢失、机械故障、交通干扰，以及各类相关问题频发的时段。\
为此，「复乐园理事会」推动了一项拆解水星天的计划，以永久根除水逆问题。\
但由于水星拆除前的星相动乱，水逆的影响就如同回光返照，达到了有史以来的最强。\
因此，这一路上，缇缇波芙用巫毒术干扰通信的工作，进行得非常顺利。\
九成以上领队星等不足的理事会守军，都如杂鱼般被缇缇波芙轻松游过了身旁，没有激起一丝波澜。",
	},
	[113292801] = {
		id = 113292801,
		text = "即使阻隔了通讯支援，但在越接近理事卿所在地时，布满了空间的守卫们的抵抗，还是不可避免地变得越来越强。\
他们的个人实力并不突出，但明显对莎乐美足够忠诚，不愿从信风面前逃跑。\
越是极度重要的时刻，越必须选用这些人作为最后一道防线，而非选用顶级强者做护卫——这是那位「第一理事卿」的性格，也是她的人生守则。\
突入至此，已是身陷重围。为了保障信风能够无伤地见到理事卿，科斯明船长与缇缇波芙决定，在敌方精英最密集的地方下船，为信风拦截追兵。\
根据科斯明船长的布置，世界政府的援军也已做足准备，埋伏在一次跃迁即可跨越的距离之外，很快就会精准地投入战场。",
	},
	[113311000] = {
		id = 113311000,
		text = "「总览界面」和其它……",
	},
	[113311001] = {
		id = 113311001,
		text = "关于「连线」",
	},
	[113311002] = {
		id = 113311002,
		text = "关于「金刚凝胶」",
	},
	[113311003] = {
		id = 113311003,
		text = "关于「建筑」",
	},
	[113311004] = {
		id = 113311004,
		text = "关于「浪费」",
	},
	[113311005] = {
		id = 113311005,
		text = "关于「拆除」",
	},
	[113311006] = {
		id = 113311006,
		text = "关于「字段」",
	},
	[113311007] = {
		id = 113311007,
		text = "关于「晋升」",
	},
	[113311008] = {
		id = 113311008,
		text = "关于「关键词」",
