	[721010101] = {
		id = 721010101,
		text = "点按#双剑六连击，在最后一击时，武装巨剑上的十字星会亮起。|\
长按#一次迅捷冲刺斩击。",
	},
	[721010102] = {
		id = 721010102,
		text = "点按#使用武装巨剑横向斩击。若在十字星亮起时精确点按，则获得强化|\
长按#以射程更远的星光横向扫过战场，若有额外召唤的武装巨剑，则引爆所有武装巨剑。|\
强化#发动更强的斩击，出手时暂时霸体并有暂时的巨额免伤，并为辉光技充能，并立即刷新本技能冷却时间。",
	},
	[721010103] = {
		id = 721010103,
		text = "点按#额外召唤四座武装巨剑，攻击场上敌人。额外召唤的巨剑也可被视为「十字星亮起」，生效时消耗1座巨剑。",
	},
	[721010104] = {
		id = 721010104,
		text = "点按#向指定方向闪避。|\
闪避时轻攻击#发动一次闪避斩。|\
若成功闪避伤害，则在接下来的一次闪避斩时，武装巨剑上的十字星会亮起。",
	},
	[721010106] = {
		id = 721010106,
		text = "被动#在目标铁壁烧坠期间，切换折光上场时，立即发动追击。",
	},
	[721010111] = {
		id = 721010111,
		text = "被动#使用荧光技，或每引爆一座武装巨剑，一段时间内攻击力提高，可以叠加5层。",
	},
	[721010113] = {
		id = 721010113,
		text = "被动#每若干次轻攻击，额外获取辉光技能量。",
	},
	[721010114] = {
		id = 721010114,
		text = "被动#在濒死时免疫一次死亡，并立即恢复一定生命值。该效果有触发间隔。",
	},
	[721010117] = {
		id = 721010117,
		text = "被动#长按荧光技引爆武装巨剑，或强化荧光技命中目标时，降低目标物理和超凡防御。",
	},
	[721010118] = {
		id = 721010118,
		text = "被动#使用辉光技后，荧光技造成的伤害提高。",
	},
	[721010119] = {
		id = 721010119,
		text = "被动#使用强化荧光技，或引爆武装巨剑时，一段时间内暴击伤害提高。",
	},
	[731010101] = {
		id = 731010101,
		text = "点按第一段伤害|点按第二段伤害|点按第三段伤害|点按第四段伤害|点按第五段伤害|点按第六段伤害|\
长按冲刺斩击伤害",
	},
	[731010102] = {
		id = 731010102,
		text = "点按伤害|\
长按伤害|\
强化伤害|\
引爆伤害",
	},
	[731010103] = {
		id = 731010103,
		text = "点按伤害|武装巨剑数量",
	},
	[731010104] = {
		id = 731010104,
		text = "闪避斩伤害",
	},
	[731010106] = {
		id = 731010106,
		text = "追击伤害",
	},
	[731010111] = {
		id = 731010111,
		text = "持续时间|攻击增加",
	},
	[731010113] = {
		id = 731010113,
		text = "轻攻击次数|获取辉光技能量",
	},
	[731010114] = {
		id = 731010114,
		text = "触发间隔",
	},
	[731010117] = {
