	},
	[731010119] = {
		id = 731010119,
		text = "暴击伤害提高|持续时间",
	},
	[721010201] = {
		id = 721010201,
		text = "点按#使用霰弹射击模式攻击。|\
长按#蓄力射击。",
	},
	[721010202] = {
		id = 721010202,
		text = "点按#进入瞄准模式。使轻攻击形式变化，且疾驰技效果替换为能量盾。|\
再次点按#退出瞄准模式。",
	},
	[721010203] = {
		id = 721010203,
		text = "点按#召唤暗星能量攻击目标，减少目标防御，并对周围敌人造成伤害。",
	},
	[721010204] = {
		id = 721010204,
		text = "点按#向指定方向闪避。|\
瞄准模式下点按#开启一次能量盾，进行格挡（巨额减伤）。|\
瞄准模式下长按#持续消耗疾驰技能量开启能量盾，进行持续格挡（巨额减伤）。每次受伤时额外消耗疾驰技能量。",
	},
	[721010205] = {
		id = 721010205,
		text = "被动#霰弹模式下，若疾驰技成功闪避伤害，则点亮1个储能罐，并为辉光技充能。|\
瞄准模式下，每次格挡成功，点亮1个储能罐，并为辉光技充能。|\
储能罐亮起时，增加25%攻击力，在任意轻攻击（点按或长按）后熄灭。",
	},
	[721010211] = {
		id = 721010211,
		text = "被动#攻击力提升，受到伤害时失效一段时间。",
	},
	[721010214] = {
		id = 721010214,
		text = "被动#蓄力时长将增加对敌人铁壁值的削减。若蓄力过程中受到伤害，将重置该效果。",
	},
	[721010216] = {
		id = 721010216,
		text = "被动#使敌人铁壁烧坠时，暴击率增加一段时间。",
	},
	[721010217] = {
		id = 721010217,
		text = "被动#使用荧光技切换形态后，接下来的2次蓄力攻击额外削减敌人的铁壁值。",
	},
	[721010218] = {
		id = 721010218,
		text = "被动#使敌人铁壁烧坠时，获得2个储能罐，且一段时间内蓄力轻攻击不消耗储能罐。",
	},
	[721010219] = {
		id = 721010219,
		text = "被动#瞄准模式下，每次格挡成功，获得基于生命值比例的护盾。",
	},
	[731010201] = {
		id = 731010201,
		text = "点按伤害|\
长按第一段伤害|长按第二段伤害",
	},
	[731010202] = {
		id = 731010202,
		text = "瞄准模式点按伤害|\
瞄准模式长按第一段伤害|瞄准模式长按第二段伤害",
	},
	[731010203] = {
		id = 731010203,
		text = "点按伤害",
	},
