	},
	[731010214] = {
		id = 731010214,
		text = "每秒额外削减铁壁值|最大额外削减铁壁值",
	},
	[731010216] = {
		id = 731010216,
		text = "暴击率增加|持续时间",
	},
	[731010217] = {
