	},
	[721020101] = {
		id = 721020101,
		text = "点按#命令机仆发射激光。|\
长按#蓄力后召唤蝙蝠眼，蓄力越久，召唤的蝙蝠眼越多。蓄力结束后，所有蝙蝠眼同时发射激光。",
	},
	[721020102] = {
		id = 721020102,
		text = "长按#下令机仆保护在场角色，获得减伤与霸体。减伤将逐渐递减，持续期间逐渐为辉光技充能。|\
该技能可主动取消。",
	},
	[721020103] = {
		id = 721020103,
		text = "点按#召唤12个蝙蝠眼，连续发射激光，造成多段伤害，并在最后造成巨额范围伤害。爆炸结束后，若条件允许，理事卿将自动退场。|\
机仆将留在场上，继承理事卿的轻攻击和荧光技，与当前在场的角色共同行动。在此期间，无法切换理事卿上场，持续一段时间后结束。|",
	},
	[721020104] = {
		id = 721020104,
		text = "点按#向指定方向闪避。",
	},
	[721020105] = {
		id = 721020105,
		text = "被动#当理事卿的蝙蝠眼或机仆攻击命中时，对目标施加1层「下位」标记，减少目标防御，可叠加30层。每次叠加可刷新持续时间。",
	},
	[721020106] = {
		id = 721020106,
		text = "被动#当场上角色受到致命伤害时，理事卿将自动切换上场，抵挡此伤害。|\
该效果仅当机仆不在场，且场上角色不为理事卿时生效，生效后进入冷却。",
	},
	[721020111] = {
		id = 721020111,
		text = "被动#轻攻击（包括机仆的协同攻击）命中未受到「下位」影响的敌人时，额外叠加「下位」状态。",
	},
	[721020112] = {
		id = 721020112,
		text = "被动#每层「下位」使敌人受到来自机仆的伤害提高。",
	},
	[721020113] = {
		id = 721020113,
		text = "被动#「下位」叠加层数上限提高，使用辉光技后全队暴击伤害提升。",
	},
	[721020114] = {
		id = 721020114,
		text = "被动#敌人死亡时，根据「下位」叠加层数，对周围敌人造成伤害。",
	},
	[721020115] = {
		id = 721020115,
		text = "被动#当敌人的攻击命中受荧光技保护的我方角色时，会被额外叠加「下位」状态。",
	},
	[721020116] = {
		id = 721020116,
		text = "被动#机仆的协同轻攻击，将使在场上的角色的下一次荧光技伤害提高。该效果可以叠加。",
	},
	[731020101] = {
		id = 731020101,
		text = "点按第一段伤害|点按第二段伤害|点按第三段伤害|点按第四段伤害|点按第五段伤害|\
长按伤害",
