	[731020113] = {
		id = 731020113,
		text = "额外叠层上限|暴击伤害提升|持续时间",
	},
	[731020114] = {
		id = 731020114,
		text = "每层攻击力倍率",
	},
	[731020115] = {
		id = 731020115,
		text = "叠加层数",
	},
	[731020116] = {
		id = 731020116,
		text = "荧光技伤害提高|叠加层数",
	},
	[721030101] = {
		id = 721030101,
		text = "点按#以快拳发动连击。|\
长按#蓄力后打出射程更远的拳劲。",
	},
	[721030102] = {
		id = 721030102,
		text = "点按#重拳连击，每拳都需要在武装闪光时精确发出，才可继续连击。连击成功时为辉光技充能。",
	},
	[721030103] = {
		id = 721030103,
		text = "点按#疾风骤雨的非人级拳击，持续期间可自由移动。",
	},
	[721030104] = {
		id = 721030104,
		text = "点按#向指定方向闪避。|\
受击后点按#精湛的受身术，脱离控制并霸体，然后进入一小段子弹时间。",
	},
	[721030111] = {
		id = 721030111,
		text = "被动#敌人死亡后，下一次任意技能将造成额外伤害。",
	},
	[721030112] = {
		id = 721030112,
		text = "被动#受到伤害时，获得持续吸收基于最大生命值伤害的护盾。",
	},
	[721030113] = {
		id = 721030113,
		text = "被动#根据附近的敌人数量，获得物理和超凡防御力，或攻击力提升。",
	},
	[721030114] = {
		id = 721030114,
		text = "被动#敌人死亡时，恢复基于最大生命值的HP，生命值高于50%时失效。",
	},
	[721030115] = {
		id = 721030115,
		text = "被动#生命值低于50%时，增加暴击率。",
	},
	[721030116] = {
		id = 721030116,
		text = "被动#使用荧光技时，使造成的物理伤害提高，如果生命值大于50%则消耗20%当前生命值。",
	},
	[721030117] = {
		id = 721030117,
		text = "被动#使用辉光技后，提升全队角色的物理伤害。",
	},
	[721030118] = {
		id = 721030118,
		text = "被动#进入关卡后，根据最大生命值提升攻击力。",
	},
	[721030119] = {
		id = 721030119,
		text = "被动#荧光技消耗一定当前生命值，并附加已经损失生命值一定比例的伤害。",
	},
	[721030120] = {
		id = 721030120,
		text = "被动#处于后台时，分摊前台角色承受的伤害，血量低于一定比例时失效。",
	},
	[721030121] = {
		id = 721030121,
		text = "被动#使用荧光技后，使下一次辉光技造成的伤害提高，可叠加。",
	},
	[721030122] = {
		id = 721030122,
		text = "被动#释放辉光技时，附加已经损失生命值一定比例的伤害，之后回复60%已损失生命值。",
	},
	[731030101] = {
		id = 731030101,
		text = "点按第一段伤害|点按第二段伤害|点按第三段伤害|点按第四段伤害|点按第五段伤害|远距离冲格伤害|\
长按第一段伤害|长按第二段伤害|",
	},
	[731030102] = {
