		text = "点按伤害",
	},
	[731030104] = {
		id = 731030104,
		text = "暂无",
	},
	[731030117] = {
		id = 731030117,
		text = "全队物理伤害提升|持续时间",
	},
	[731030118] = {
		id = 731030118,
		text = "每点生命值攻击力提升",
	},
	[731030119] = {
		id = 731030119,
		text = "当前生命值消耗|损失生命值附加比例",
	},
	[731030120] = {
