		text = "损失生命值附加比例",
	},
	[721040101] = {
		id = 721040101,
		text = "点按#以太刀带出幻影，进行中距离的斩击。|\
长按#蓄力后进行一次快速的小拔刀，蓄力满时为辉光技充能。|\
变身状态下点按#挥出巨大太刀，附带一次向外散发的额外刀气。|\
变身状态下长按#蓄力后挥出巨大太刀，附带一次向外散发的额外刀气，蓄力满时为辉光技充能。",
	},
	[721040102] = {
		id = 721040102,
		text = "长按#蓄力后锁定多个敌人，发射刀轮，蓄力越久，刀轮越多。蓄力满时为辉光技充能。|\
变身状态下长按#蓄力后锁定多个敌人，发射小翼之羽，蓄力越久，小翼之羽越多。蓄力满时为辉光技充能。",
	},
	[721040103] = {
		id = 721040103,
		text = "点按#对场上敌人发动斩击，并在一定时间内变身，转换自身武装的形态，组装巨大太刀与「北方的小翼」。",
	},
	[721040104] = {
		id = 721040104,
		text = "点按#向指定方向瞬移。",
	},
	[721040113] = {
		id = 721040113,
		text = "被动#荧光技命中时，有概率重置荧光技冷却时间。该效果有触发间隔。",
	},
	[721040114] = {
		id = 721040114,
		text = "被动#基于任意两次攻击之间移动的距离，造成额外伤害。",
	},
	[721040115] = {
		id = 721040115,
		text = "被动#辉光技变身的持续时间增加。",
	},
	[721040117] = {
		id = 721040117,
		text = "被动#辉光技变身结束后，获得辉光技能量。变身状态下，虚无质伤害提高。",
	},
	[721040118] = {
		id = 721040118,
		text = "被动#轻攻击和荧光技的蓄力状态下，角色的抗打断力提高。角色移动时，轻攻击和荧光技伤害提高，停止移动一段时间后效果消失。",
	},
	[721040119] = {
		id = 721040119,
		text = "被动#使用荧光技后，接下来的数次攻击必定暴击且暴击伤害增加。",
	},
	[731040101] = {
		id = 731040101,
		text = "点按第一段伤害|点按第二段伤害|点按第三段伤害|点按第四段伤害|点按第五段伤害|远距离冲格伤害|\
长按伤害",
	},
	[731040102] = {
