		text = "长按第一段伤害|长按第二段伤害|长按第三段伤害|长按第四段伤害",
	},
	[731040103] = {
		id = 731040103,
		text = "武装形态连击<佩刀>|\
点按第一段伤害|点按第二段伤害|点按第三段伤害|点按第四段伤害|点按第五段伤害|长按第一段伤害|长按第二段伤害|刀气伤害|\
武装形态慢启动小镰鼬|\
长按第一段伤害|长按第二段伤害|长按第三段伤害|长按第四段伤害|",
