	},
	[721050101] = {
		id = 721050101,
		text = "点按#巨刃五连击。|\
长按#一次蓄力重击。",
	},
	[721050102] = {
		id = 721050102,
		text = "点按#根据目标状态，自动切换武技。每次使用与上次不同的武技，就会为辉光技充能。|\
全力重斩#目标铁壁烧坠时。|\
投刃与追击#目标处在近距离时。|\
光束照射#目标处在中距离时。|\
定身法#目标高速移动时。|\
能量球场#目标处在远距离时。能量球场造成伤害时为辉光技充能。|\
反制#自身被击飞不受控时。这一种荧光技冷却时间极短，且为受身技能。|",
	},
	[721050103] = {
		id = 721050103,
		text = "点按#以自身武装变形为信使星之门，引导诺伦线的扭曲与压迫，成为毁灭之光。|\
门后的天体可能有两种情况：陨石；小行星。",
	},
	[721050104] = {
		id = 721050104,
		text = "点按#向指定方向闪避。|\
闪避时轻攻击#发动一次闪避斩。",
	},
	[721050114] = {
		id = 721050114,
		text = "被动#轻攻击命中时，额外削减敌人铁壁值，蓄力时效果提升。",
	},
	[721050115] = {
		id = 721050115,
		text = "被动#使用辉光技时，门后的天体可能有三种情况：陨石；小行星；圆形卫星。",
	},
	[721050116] = {
		id = 721050116,
		text = "被动#使用辉光技时，门后出现圆形卫星的概率上升。",
	},
	[721050117] = {
		id = 721050117,
		text = "被动#使用辉光技后，全队攻击力提高。",
	},
	[721050118] = {
		id = 721050118,
		text = "被动#每秒自动回复辉光能量，不在场上时回复量增加，并会自动释放辉光技。",
	},
	[721050119] = {
		id = 721050119,
		text = "被动#对力场、粒子、灾厄、侵蚀、虚无质目标造成的伤害提高。",
	},
