	},
	[731050119] = {
		id = 731050119,
		text = "对粒子质伤害提高|对力场质伤害提高|对灾厄质伤害提高|对侵蚀质伤害提高|对虚无质伤害提高",
	},
	[721060101] = {
		id = 721060101,
		text = "点按#炮击目标，产生爆炸。每次炮击积蓄热量。近身时变为近战攻击。|\
长按#机炮连射，期间仍可自由移动。连射期间不断积蓄热量。|\
过热#热量情况可在武装上看到红灯。过热后无法攻击或使用技能。",
	},
	[721060102] = {
		id = 721060102,
		text = "长按#蓄力后发射多枚【导弹】，命中时产生爆炸。",
	},
	[721060103] = {
		id = 721060103,
		text = "点按#张开能够减少受到伤害的能量盾，并以盾架炮，持续一段时间。发动期间按键发生变化，获得大威力炮击键（可点按）。并且武装机身不断自动射出【导弹】，直至结束。",
	},
	[721060104] = {
		id = 721060104,
		text = "点按#向指定方向闪避。|\
长按#主动散热，并为辉光技充能。期间仍可自由移动，但移速降低。",
	},
	[721060112] = {
		id = 721060112,
		text = "被动#辉光技命中时，全队获取辉光技能量。",
	},
	[721060113] = {
		id = 721060113,
		text = "被动#轻攻击命中时，增加攻击力，可以叠加。切换目标时失效。",
	},
	[721060114] = {
		id = 721060114,
		text = "被动#轻攻击频率增加，暴击率提高。若短期内连续受到伤害，则失效一段时间。",
	},
	[721060117] = {
		id = 721060117,
		text = "被动#使用辉光技时，每有一个蓝灯，使全队轻攻击造成的伤害提高一段时间。",
	},
	[721060118] = {
		id = 721060118,
		text = "被动#公主不在场上时，在场的角色每次使用荧光技或辉光技，都会为公主的辉光技充能。",
	},
	[721060119] = {
		id = 721060119,
		text = "被动#使用辉光技后，暴击率和暴击伤害提高。",
	},
	[721060120] = {
