	[721070101] = {
		id = 721070101,
		text = "点按#鞭剑五连击。每段连击使1片护盾片亮起。|\
长按#挥出九头蛇之影，使1片护盾片亮起。命中敌人时向自身拉近。命中敌人为辉光技充能。",
	},
	[721070102] = {
		id = 721070102,
		text = "长按#摆出防御架势，根据护盾片数量增加大量物理防御力和少量超凡防御力，蓄力期间持续吸引附近的敌人。长按松开时，发动一次范围攻击，消耗所有亮起的护盾片，增加伤害。|\
护盾片全亮时#长按期间霸体。",
	},
	[721070103] = {
		id = 721070103,
		text = "点按#发出正义的律师斥责，攻击敌人，并使全部护盾片亮起。|",
	},
	[721070104] = {
