		text = "点按#向指定方向闪避。|\
闪避时轻攻击#发动一次闪避斩。",
	},
	[721070105] = {
		id = 721070105,
		text = "被动#仅在满生命时，减少受到的伤害。",
	},
	[721070106] = {
		id = 721070106,
		text = "被动#使用辉光技后，获得1次计数的无敌。",
	},
	[721070107] = {
		id = 721070107,
		text = "被动#完全无视一定程度以下的小额伤害。",
	},
	[721070111] = {
		id = 721070111,
		text = "被动#基于物理和超凡防御力，提升攻击力。",
	},
	[721070112] = {
		id = 721070112,
		text = "被动#每片亮起的护盾片都提高荧光技的暴击伤害。当全部护盾片亮起时，使用荧光技将立刻刷新荧光技的冷却时间。",
	},
	[721070113] = {
		id = 721070113,
		text = "被动#使用辉光技后，物理和超凡防御力提高。",
	},
	[721070114] = {
		id = 721070114,
		text = "被动#荧光技每命中一个敌人，增加侵蚀质伤害，可叠加。",
	},
	[721070115] = {
		id = 721070115,
		text = "被动#使用辉光技后，下2次荧光技不消耗护盾片。",
