3段#后撤，霸体，向前攻击。|\
4段#引力塌缩，高频大范围伤害。|",
	},
	[721080103] = {
		id = 721080103,
		text = "点按#召唤全身武装。|\
根据使用时的辉光技能量累积，有三层不同的变身增益。",
