	},
	[721080105] = {
		id = 721080105,
		text = "被动#浮塔伤害随派出时间衰减，其衰减可由光亮度判断。损失的伤害会转化成角色本体的防御。",
	},
	[721080111] = {
		id = 721080111,
		text = "被动#浮塔的伤害不再随时间衰减，但是每个浮塔最多进行10次攻击。",
	},
	[721080112] = {
		id = 721080112,
		text = "被动#变身状态下，使周围敌人的灾厄抗性降低。",
	},
	[721080113] = {
		id = 721080113,
		text = "被动#以任意能量开启辉光技变身时，都会获得第三层增益。同时，根据开启时拥有的辉光技能量，提升灾厄伤害。",
	},
	[721080114] = {
		id = 721080114,
		text = "被动#浮塔每次命中时计数，收回浮塔时，每层计数提高其伤害与辉光技能量获取。",
