	[813000001] = {
		id = 813000001,
		text = "宇宙是个遍布威胁的地方，敌人总会像趋光的飞虫一般找上门来。",
	},
	[813000002] = {
		id = 813000002,
		text = "在宇宙探索时，来自建筑的帮助，总能让远航变得事半功倍。",
	},
	[813000003] = {
		id = 813000003,
		text = "机械设备长期闲置，就容易出现问题。战舰和手机一样，都要适当用用。",
	},
	[813000004] = {
		id = 813000004,
		text = "没有销量，设计建筑的工程师们就不会研发新的产品。",
	},
	[813000005] = {
		id = 813000005,
		text = "合理的消费能够促进经济循环。作为将要长住「无序之都」的客人，请适度地支持当地经济。",
	},
	[813000006] = {
		id = 813000006,
		text = "辐射后的组织液，漂浮着小宇宙的星相——肝、肺、胃、脾、胆、胰、肾、脑。\
以及恒星的「签名」所在：心脏。",
	},
	[813000007] = {
		id = 813000007,
		text = "暂时用不上的事物，可以通过「红王白后」的炼金术，发掘它在其它领域的重要性。",
	},
	[813000008] = {
		id = 813000008,
		text = "维护星域安全、收集资材……「危航调度处」每天都会发布新的赏金任务。",
	},
	[813000009] = {
		id = 813000009,
		text = "欢迎回来，太阳系的游侠。",
	},
	[813000010] = {
		id = 813000010,
		text = "建筑都有各自的效果，多多尝试，才能了解透彻。请部署一些带有「燃烧」关键词的建筑。",
	},
	[813000011] = {
		id = 813000011,
		text = "建筑都有各自的效果，多多尝试，才能了解透彻。请部署一些带有「导弹」关键词的建筑。",
	},
	[813000012] = {
