	[818001101] = {
		id = 818001101,
		text = "【梦境提升】\
◆BOSS粒子抗性降低30%\
\
【战斗特征】\
◆多种形式的光弹攻击\
◆HP下降到一定程度时，不再伪装「十字」状态，显露真身\
◆显露真身时，从本体结晶中脱落3枚伪神碎片，与本体产生高热连线。此时本体无敌，需要优先处理伪神碎片\
◆显露真身后，攻击手段将更加丰富",
	},
	[818001102] = {
		id = 818001102,
		text = "【梦境提升】\
◆BOSS力场抗性降低30%\
\
【战斗特征】\
◆多种形式的投枪\
◆多种形式的激光\
◆「有翼之目」浮游炮的攻击，触碰时会留下有害烟雾\
◆持续引发震荡时，若靠近会被击退\
◆HP下降到一定程度时，理事卿将发射巨大光柱、令浮游炮协同攻击。在齐射结束后，理事卿的巨型武装将变形，进入下一战斗模式\
◆变形后，巨型武装「眼眶」中的「左目」与「右目」将脱离本体，成为独立作战单位，建议优先处理",
	},
	[818001103] = {
		id = 818001103,
		text = "【梦境提升】\
◆BOSS动能抗性降低30%\
\
【战斗特征】\
◆多种形式的长枪连击\
◆投掷长枪时，在轨迹上留下一片陨石地带\
◆挥动光拳发出的光流，将引爆它所触及的陨石地带\
◆在铁壁烧坠之后，骑士将拔出日蚀之剑，发射大量剑光\
◆拔出日蚀之剑的骑士，将在一段时间内同时使用枪与剑战斗（剑中寄宿了过量的光芒，敬请小心），直到时间结束，重新陷入日蚀\
\
",
	},
	[818001104] = {
		id = 818001104,
		text = "【梦境提升】\
◆超凡伤害增加50%\
\
【战斗特征】\
◆多种形式的光弹攻击\
◆HP下降到一定程度时，不再伪装「十字」状态，显露真身\
◆显露真身时，从本体结晶中脱落3枚伪神碎片，与本体产生高热连线。此时本体无敌，需要优先处理伪神碎片\
◆显露真身后，攻击手段将更加丰富",
	},
	[818001105] = {
		id = 818001105,
		text = "【梦境提升】\
◆超凡伤害增加50%\
\
