		text = "图文教学",
	},
	[825006047] = {
		id = 825006047,
		text = "图文教学",
	},
	[826001000] = {
		id = 826001000,
		text = "需要在敌人中找出<span color=\"#ff6c00\">不同阵营的那一个</>，优先击杀。\
当击杀了「错误的敌人」时，会召唤更多「错误的敌人」。\
击杀了「正确的敌人」，就会停止召唤了。",
	},
	[826001001] = {
		id = 826001001,
		text = "使用键盘WASD，进行四方向移动。",
	},
	[826001002] = {
		id = 826001002,
		text = "点击鼠标左键，可以使用<span color=\"#ff6c00\">轻攻击</>。长按可以<span color=\"#ff6c00\">蓄力</>。",
	},
	[826001003] = {
		id = 826001003,
		text = "点击鼠标右键，可以使用<span color=\"#ff6c00\">荧光技</>，长按可以<span color=\"#ff6c00\">蓄力</>。",
	},
	[826001004] = {
		id = 826001004,
		text = "当辉光技充能满时，点击R键，可以使用<span color=\"#ff6c00\">辉光技</>。",
	},
	[826001005] = {
		id = 826001005,
		text = "点击空格键，可以使用<span color=\"#ff6c00\">疾驰技</>，会朝向移动方向闪避并规避伤害。\
<span color=\"#ff6c00\">疾驰技</>需要消耗疾驰能量，疾驰能量自动回复。",
	},
	[826001006] = {
		id = 826001006,
		text = "对于部分角色，在点按<span color=\"#ff6c00\">疾驰技</>后，紧接着<span color=\"#ff6c00\">轻攻击</>，可以使用闪避斩。\
闪避斩通常是一个比轻攻击更强力的攻击技能。",
	},
	[826001007] = {
		id = 826001007,
		text = "屏幕中央显示着被<span color=\"#ff6c00\">锁定</>的敌人。\
点击Q键/E键，就可以将锁定目标切换为位于<span color=\"#ff6c00\">左/右</>侧的另一个敌人。",
	},
	[826001008] = {
		id = 826001008,
		text = "对于部分角色，长按<span color=\"#ff6c00\">疾驰技</>可以进行远距离冲刺，迅速接近敌人。\
关于此类特殊效果，详见角色的技能描述。",
	},
	[826001009] = {
		id = 826001009,
		text = "对于每个角色，辉光技充能的来源是不同的。\
信风在敌人数量较多的情况下使用<span color=\"#ff6c00\">荧光技</>时，则会获得大量辉光技充能。\
其他角色的充能手段，详见角色的技能描述。",
	},
	[826001010] = {
		id = 826001010,
		text = "图中所示的是敌人的HP条与护盾条。\
敌人受伤时，先消耗<span color=\"#ff6c00\">护盾</>，再消耗<span color=\"#ff6c00\">HP</>。",
	},
	[826001011] = {
		id = 826001011,
		text = "图中所示的是敌人的<span color=\"#ff6c00\">命质</>。\
命质共有六种，分别是<span color=\"#ff6c00\">物理</>命质：粒子、动能、力场；<span color=\"#ff6c00\">超凡</>命质：灾厄、侵蚀、虚无。\
它们呈现出攻防上的克制关系，例如<span color=\"#ff6c00\">粒子质</>的攻击，对<span color=\"#ff6c00\">动能质</>的敌人伤害更高。",
	},
	[826001012] = {
		id = 826001012,
		text = "点击T键，可以使用战舰技能。（每艘战舰都有不同技能）\
每次使用，消耗一发<span color=\"#ff6c00\">舰武载弹</>。\
仅在部分玩法中可以召唤战舰。",
	},
	[826001013] = {
		id = 826001013,
		text = "在锁定框边缘，有<span color=\"#ff6c00\">铁壁值</>的红色进度条。\
使用各种攻击手段，把敌人的<span color=\"#ff6c00\">铁壁值</>清零，就会使敌人进入<span color=\"#ff6c00\">铁壁烧坠</>状态。",
	},
	[826001014] = {
		id = 826001014,
		text = "点击X键/C键，可以把屏幕下方的「HP与头像」区域中，<span color=\"#ff6c00\">左/右</>头像对应的角色切换上场。",
	},
	[826001015] = {
		id = 826001015,
		text = "小鱼在消耗<span color=\"#ff6c00\">浮游炮能量</>时，会获得辉光技充能。",
	},
	[826001016] = {
		id = 826001016,
		text = "部分敌人能够发动<span color=\"#ff6c00\">高危技能</>，发动时有红光提示危险。\
找准时机，使用<span color=\"#ff6c00\">精确反击</>，可以打断高危技能，并使该敌人受到极大惩罚（某些敌人甚至会立刻死亡）。",
	},
	[826001017] = {
		id = 826001017,
		text = "信风的闪避斩即为<span color=\"#ff6c00\">精确反击</>技能，而小鱼没有精确反击能力。\
一般来说，近战角色都具备精确反击能力。少量远程角色也具备精确反击能力。\
各角色的<span color=\"#ff6c00\">精确反击</>技能，详见其技能描述。",
	},
	[826001018] = {
		id = 826001018,
		text = "辉光技施放的临时文本",
	},
	[826001019] = {
		id = 826001019,
		text = "<span color=\"#ff6c00\">铁壁烧坠</>状态中的敌人，一段时间内毫无还手之力，且受到的伤害更高。",
	},
	[826001020] = {
		id = 826001020,
		text = "小鱼可以通过轻攻击等手段积攒浮游炮能量，进而强化小鱼的浮游炮。强化浮游炮可以通过荧光技、疾驰技释放。积攒的能量越多，伤害越高。",
	},
	[826002001] = {
		id = 826002001,
		text = "使用虚拟摇杆，进行多方向移动。",
	},
	[826002002] = {
		id = 826002002,
		text = "点击图中红箭头指向的按键，可以使用<span color=\"#ff6c00\">轻攻击</>。长按可以<span color=\"#ff6c00\">蓄力</>。\
点击图中黄箭头指向的按键，可以使用<span color=\"#ff6c00\">荧光技</>，长按可以<span color=\"#ff6c00\">蓄力</>。\
当辉光技充能满时，点击图中绿箭头指向的按键，可以使用<span color=\"#ff6c00\">辉光技</>。",
	},
	[826002003] = {
		id = 826002003,
		text = "点击图中左下角按键，可以使用<span color=\"#ff6c00\">疾驰技</>。若在向某方向移动时使用，则疾驰方向会朝向移动方向。\
<span color=\"#ff6c00\">疾驰技</>需要消耗疾驰能量，疾驰能量自动回复。",
	},
	[826002004] = {
		id = 826002004,
		text = "对于部分角色，长按<span color=\"#ff6c00\">疾驰技</>可以进行远距离冲刺，迅速接近敌人。\
关于此类特殊效果，详见角色的技能描述。",
	},
	[826002005] = {
		id = 826002005,
		text = "对于部分角色，在点按<span color=\"#ff6c00\">左、右、后向的疾驰技</>后，紧接着<span color=\"#ff6c00\">轻攻击</>，可以使用闪避斩。\
闪避斩通常是一个比轻攻击更强力的攻击技能。",
	},
	[826002006] = {
		id = 826002006,
		text = "屏幕中央显示着被<span color=\"#ff6c00\">锁定</>的敌人。\
在屏幕<span color=\"#ff6c00\">中间空白区域</>，向<span color=\"#ff6c00\">左/右</>滑动，就可以将锁定目标切换为位于<span color=\"#ff6c00\">左/右</>侧的另一个敌人。",
	},
	[826002007] = {
		id = 826002007,
		text = "图中所示的是敌人的HP条与护盾条。\
敌人受伤时，先消耗<span color=\"#ff6c00\">护盾</>，再消耗<span color=\"#ff6c00\">HP</>。",
	},
	[826002008] = {
		id = 826002008,
		text = "图中所示的是敌人的<span color=\"#ff6c00\">命质</>。\
命质共有六种，分别是<span color=\"#ff6c00\">物理</>命质：粒子、动能、力场；<span color=\"#ff6c00\">超凡</>命质：灾厄、侵蚀、虚无。\
它们呈现出攻防上的克制关系，例如<span color=\"#ff6c00\">粒子质</>的攻击，对<span color=\"#ff6c00\">动能质</>的敌人伤害更高。",
	},
	[826002009] = {
		id = 826002009,
		text = "点击屏幕右侧，如图位置的按钮，可以使用战舰技能。（每艘战舰都有不同技能）\
每次使用，消耗一发<span color=\"#ff6c00\">舰武载弹</>。\
仅在部分玩法中可以召唤战舰。",
	},
	[826002010] = {
		id = 826002010,
		text = "在锁定框边缘，有<span color=\"#ff6c00\">铁壁值</>的红色进度条。\
使用各种攻击手段，把敌人的<span color=\"#ff6c00\">铁壁值</>清零，就会使敌人进入<span color=\"#ff6c00\">铁壁烧坠</>状态，一段时间内毫无还手之力，且受到的伤害更高。",
	},
	[826002011] = {
		id = 826002011,
		text = "在屏幕下方的「HP与头像」区域，向<span color=\"#ff6c00\">左/右</>滑动，就可以把<span color=\"#ff6c00\">右/左</>头像对应的角色切换上场。",
	},
	[826002012] = {
		id = 826002012,
		text = "对于每个角色，辉光技充能的来源是不同的。\
信风每次使用<span color=\"#ff6c00\">荧光技</>时，如果与上一次用出了<span color=\"#ff6c00\">不同</>的技能，则会获得辉光技充能。\
小鱼在消耗<span color=\"#ff6c00\">连击点</>时，会获得辉光技充能。\
其他角色的充能手段，详见角色的技能描述。",
	},
	[826002013] = {
		id = 826002013,
		text = "部分敌人能够发动<span color=\"#ff6c00\">高危技能</>，发动时有红光提示危险。\
找准时机，使用<span color=\"#ff6c00\">精确反击</>，可以打断高危技能，并使该敌人受到极大惩罚（某些敌人甚至会立刻死亡）。",
	},
	[826002014] = {
		id = 826002014,
		text = "信风的闪避斩即为<span color=\"#ff6c00\">精确反击</>技能，而小鱼没有精确反击能力。\
一般来说，近战角色都具备精确反击能力。少量远程角色也具备精确反击能力。\
各角色的<span color=\"#ff6c00\">精确反击</>技能，详见其技能描述。",
	},
	[826002015] = {
		id = 826002015,
		text = "辉光技施放的临时文本",
	},
	[826002016] = {
		id = 826002016,
		text = "<span color=\"#ff6c00\">铁壁烧坠</>状态中的敌人，一段时间内毫无还手之力，且受到的伤害更高。",
	},
	[826003001] = {
		id = 826003001,
		text = "在轻攻击最后一段时，折光背后武装上的<span color=\"#ff6c00\">十字星</>会闪光，此时精准地使用荧光技，就能获得强化，并重置其CD，并为辉光技充能。\
辉光技召唤的<span color=\"#ff6c00\">十字星</>大剑，也可以用荧光技<span color=\"#ff6c00\">击碎</>，算作成功强化，获得所有对应奖励。",
	},
	[826003002] = {
		id = 826003002,
		text = "折光在濒死时，能够残血复活。\
在敌人<span color=\"#ff6c00\">铁壁烧坠</>时，换上折光，她会发动一次强力的旋转斩击。",
	},
	[826003003] = {
		id = 826003003,
		text = "霰弹模式下，当闪避的<span color=\"#ff6c00\">无敌帧</>成功规避了伤害，会点亮1储能罐，并为辉光技充能。\
狙击模式下，无法闪避，疾驰技效果变为<span color=\"#ff6c00\">格挡</>（可以连点，还可以长按）。\
当<span color=\"#ff6c00\">格挡</>成功，会点亮1储能罐，并为辉光技充能。",
	},
	[826003004] = {
		id = 826003004,
		text = "在霰弹模式下，闪避后立刻接荧光技，可以触发快速切换。\
狙击模式下，折光全程<span color=\"#ff6c00\">霸体</>。\
双战斗模式都可以消耗储能罐，得到进攻上的增强效果。",
	},
	[826003005] = {
		id = 826003005,
		text = "使用辉光技之前，可以把十四娘当做一个<span color=\"#ff6c00\">挂机角色</>。\
用轻攻击<span color=\"#ff6c00\">放出</>浮塔，然后就可以挂机看浮塔打伤害（越挂机攻击越低、防御越高）。\
可以用荧光技<span color=\"#ff6c00\">召回</>浮塔，穿过敌人时造成伤害，并为辉光技充能。",
	},
	[826003006] = {
		id = 826003006,
		text = "使用辉光技后，变成近战角色。\
轻攻击与荧光技之间，会形成四种不同的<span color=\"#ff6c00\">连段</>，打出不同的技能效果。",
	},
	[826003007] = {
		id = 826003007,
		text = "有四种可以蓄力的攻击，每一种达到最高阶蓄力时，都会为辉光技充能。\
攻击命中时会叠加暴击率，而在发生暴击时移除。",
	},
	[826003008] = {
		id = 826003008,
		text = "针对不同的战场情况，信风会自动使用不同的荧光技，共有6种。\
每次使用荧光技时，如果与上一个不同，则会为辉光技充能。\
信风的闪避斩可用于<span color=\"#ff6c00\">精确反击</>。",
	},
	[826003009] = {
		id = 826003009,
		text = "每段荧光技都需要在闪光时精准按下，只要不断，就可以一直继续下去。\
高连段的荧光技，会为辉光技充能。\
逆戟雀的疾驰技是一个<span color=\"#ff6c00\">受身</>技能，被控时也可以使用。",
	},
	[826003010] = {
		id = 826003010,
		text = "在受伤后的一瞬间<span color=\"#ff6c00\">受身</>，会触发<span color=\"#ff6c00\">子弹时间</>。\
结合星位效果，逆戟雀有一系列有助于生存的被动，且在HP较少时输出更高。",
	},
	[826003011] = {
		id = 826003011,
		text = "点按轻攻击，或使用辉光技，都能获得<span color=\"#ff6c00\">护盾片</>。\
长按荧光技时，大幅增强生存能力，并持续抓取附近的敌人。<span color=\"#ff6c00\">护盾片</>全亮时，长按荧光技获得霸体。\
松开时，消耗所有<span color=\"#ff6c00\">护盾片</>发动攻击。\
长按轻攻击，可瞬间抓取敌人，根据命中敌人的数量为辉光技充能。",
	},
	[826003012] = {
		id = 826003012,
		text = "点按轻攻击、蓄力轻攻击、蓄力荧光技，都会根据其本身的「达成阶段」，来增加<span color=\"#ff6c00\">连击点</>。\
可以通过点按荧光技，或疾驰技，来消耗<span color=\"#ff6c00\">连击点</>，发出强力的导弹，并为辉光技充能。\
辉光技会使<span color=\"#ff6c00\">连击点</>立刻满点。",
	},
	[826003013] = {
		id = 826003013,
		text = "轻攻击与荧光技，都会积攒<span color=\"#ff6c00\">热量</>。<span color=\"#ff6c00\">热量</>满时，无法再用此类进攻手段。\
长按疾驰技，可以<span color=\"#ff6c00\">主动散热</>，且此行为会为辉光技充能。\
辉光技开启后，会有一套不积攒热量的独立攻击手段，且不断自动发射导弹。\
被敌人近身时，「点按的轻攻击」自动变为近战，弹开敌人。",
	},
	[826003014] = {
		id = 826003014,
		text = "轻攻击与荧光技命中敌人，可以为敌人添加<span color=\"#ff6c00\">下位</>，降低敌人的物理防御，最多叠加30层，层数越高，效果持续时间越长。\
长按疾驰技，可以在前方生成<span color=\"#ff6c00\">护盾</>，降低受到的伤害并将部分反弹给敌人。\
辉光技开启后，会切换至下一位角色，并且装甲会留在场上协调攻击",
	},
	[826004001] = {
		id = 826004001,
		text = "请从主菜单的此处进入<span color=\"#ff6c00\">任务系统</>。",
	},
	[826004002] = {
		id = 826004002,
		text = "<span color=\"#ff6c00\">日常任务</>开放了！\
请从主菜单的任务按钮进入，每天都会自动接取新的日常任务。\
点击任务界面中的<span color=\"#ff6c00\">问号</>按钮，可以查看更多介绍。",
	},
	[826004003] = {
		id = 826004003,
		text = "<span color=\"#ff6c00\">目标奖励册</>开放了！\
请从主菜单的此处进入。\
完成<span color=\"#ff6c00\">一整页</>目标，可以领取额外奖励，然后开放<span color=\"#ff6c00\">下一页</>。",
	},
	[826004004] = {
		id = 826004004,
		text = "<span color=\"#ff6c00\">眠眠的战斗教室</>开放了！\
请从主菜单的此处进入。\
在这个活动中，你可以试用所有角色。根据完成的<span color=\"#ff6c00\">挑战目标</>，获得对应奖励。",
	},
	[826004005] = {
		id = 826004005,
		text = "这就是能够改变故事走向的<span color=\"#ff6c00\">时珊瑚树</>系统。\
由于本次是通过DEAD END进入，所以在选择某个<span color=\"#ff6c00\">节点</>之前，无法离开。\
从DEAD END进入时珊瑚树时，都无法自由离开。\
当然，你也可以在任意的自由时光里，随时打开时珊瑚树系统，跳转故事的节点。\
平时，请从主菜单的此处进入<span color=\"#ff6c00\">时珊瑚树</>。\
进入界面后，点击<span color=\"#ff6c00\">问号</>按钮，可以查看更多介绍。",
	},
	[826004006] = {
		id = 826004006,
		text = "请从主菜单的此处进入<span color=\"#ff6c00\">百科图鉴</>。\
剧情中所有已提及的<span color=\"#ff6c00\">高亮词</>，与曾经弹出过的所有<span color=\"#ff6c00\">图文教学</>，都在其中收录。",
	},
	[826004007] = {
		id = 826004007,
		text = "<span color=\"#ff6c00\">角色升级</>开放了！\
请从主菜单的此处进入，然后点击<span color=\"#ff6c00\">升级</>按钮。",
	},
	[826004008] = {
		id = 826004008,
		text = "<span color=\"#ff6c00\">武器升级</>开放了！\
请从主菜单的此处进入，然后选择<span color=\"#ff6c00\">武器</>页签。",
	},
	[826004009] = {
		id = 826004009,
		text = "<span color=\"#ff6c00\">技能升级</>开放了！\
请从主菜单的此处进入，选择<span color=\"#ff6c00\">技能</>页签，然后点击其中一个技能。",
	},
	[826004010] = {
		id = 826004010,
		text = "<span color=\"#ff6c00\">星位系统</>开放了！\
请从主菜单的此处进入，选择<span color=\"#ff6c00\">星位</>页签，从<span color=\"#ff6c00\">最初的</>星位开始查看。",
	},
	[826004011] = {
		id = 826004011,
		text = "<span color=\"#ff6c00\">每日危航</>开放了！\
请垂询<span color=\"#ff6c00\">一三五先生</>或<span color=\"#ff6c00\">二四六小姐</>。\
每天你都会得到新的<span color=\"#ff6c00\">危航许可</>，用于开启危航。\
点击每日危航界面中的<span color=\"#ff6c00\">问号</>按钮，可以查看更多介绍。",
	},
	[826004012] = {
		id = 826004012,
		text = "<span color=\"#ff6c00\">内天体熔铸</>开放了！\
请前往<span color=\"#ff6c00\">内天之星</>，尝试熔铸<span color=\"#ff6c00\">各部位</>的内天体。\
点击内天之星界面中的<span color=\"#ff6c00\">问号</>按钮，可以查看更多介绍。",
	},
	[826004013] = {
		id = 826004013,
		text = "<span color=\"#ff6c00\">远航支援商店</>开放了！\
在那里，可以购买永久强化，在远航中全程生效。",
	},
	[826004014] = {
		id = 826004014,
		text = "<span color=\"#ff6c00\">套房快乐趴</>系统就此开放了！\
从你所在的街区，有两个入口，可以回到刚才所见的，位于时间之外的总统套房。\
它们分别是<span color=\"#ff6c00\">莲花王宫酒店的二楼</>，和<span color=\"#ff6c00\">中央广场的自助面板</>。",
	},
	[826004015] = {
		id = 826004015,
		text = "对话中的任何<span color=\"#ff6c00\">高亮词</>，都可以点击，查看它的解释。",
	},
	[826004016] = {
		id = 826004016,
		text = "<span color=\"#ff6c00\">点击</>即可跳过本句对话。\
<span color=\"#ff6c00\">长按</>可以<span color=\"#ff6c00\">快速</>跳过对话。",
	},
	[826004017] = {
		id = 826004017,
		text = "在通讯框上<span color=\"#ff6c00\">点击</>，即可跳过本句通讯框对话。",
	},
	[826004018] = {
		id = 826004018,
		text = "在这里，我们顺便讲解一下<span color=\"#ff6c00\">稀有度</>。\
游戏中的所有武器、内天体、建筑蓝图……种种物品，全都遵循<span color=\"#ff6c00\">从1星到6星</>的稀有度规则。\
但在6星之上，偶尔还能见到更为稀有的<span color=\"#ff6c00\">辉光秘宝</>……",
	},
	[826004019] = {
		id = 826004019,
		text = "使用键盘WASD，进行多方向移动。",
	},
	[826004020] = {
		id = 826004020,
		text = "点击空格键，可以跳跃。",
	},
	[826004021] = {
		id = 826004021,
		text = "点击此处的按钮，可以在<span color=\"#ff6c00\">舰桥视角</>与<span color=\"#ff6c00\">星图视角</>之间切换。",
	},
	[826004022] = {
		id = 826004022,
		text = "<span color=\"#ff6c00\">接机系统</>开放了！\
在这里，你可以使用两种不同的机票，抽取多种卡池内的<span color=\"#ff6c00\">幻形</>与<span color=\"#ff6c00\">武器</>。\
不同卡池的特殊机制，详见卡池说明。",
	},
	[826004023] = {
		id = 826004023,
		text = "<span color=\"#ff6c00\">梦境灵修</>开放了！\
在这里，你将与各种首领级敌人在虚拟交战中遭遇。\
根据战斗中的评分，你将获取排名，得到丰厚奖励。",
	},
	[826004024] = {
		id = 826004024,
		text = "<span color=\"#ff6c00\">活动系统</>开放了！\
主菜单的此处，会定期推送当前的活动。\
点击主菜单中的活动按钮，可以查看正在举办中的全部活动。",
	},
	[826004025] = {
		id = 826004025,
		text = "在游戏的大部分时间里，鼠标是隐藏着的。\
按住键盘上的Alt键，就能召唤出鼠标。",
	},
	[826004026] = {
		id = 826004026,
		text = "点击屏幕右上角的<span color=\"#ff6c00\">按钮</>，安放家具。\
安放家具时，请注意观察对应的<span color=\"#ff6c00\">套房区域</>。\
总统套房也处于「时珊瑚枝」的影响之下。你新布置的那些家具，似乎有人正在使用……\
请前往对应的<span color=\"#ff6c00\">套房区域</>，寻找你安放的家具。",
	},
	[826004027] = {
		id = 826004027,
		text = "家具自带一个试用幻形，试用幻形将随版本<span color=\"#ff6c00\">不定期更换</>，敬请注意。\
如果你拥有别的幻形，就可以随时更换自己拥有的幻形。\
在家具互动中，当你的手触碰到了<span color=\"#ff6c00\">特别的位置</>，她们就会有所反应。\
详情请见互动期间的屏幕说明。",
	},
	[826004028] = {
		id = 826004028,
		text = "赛文楼德大王的特别提示！\
<span color=\"#ff6c00\">这里是时间之外，而你是拆信之人。</>\
在接机时，如果你觉得她们对你的亲昵程度，超过了你现在的认知，那也正常。\
她们的出发站点，可能是不久后的未来。\
而那未来，也是你必将经历的。",
	},
	[826004029] = {
		id = 826004029,
		text = "借助时空的乱流，赛文楼德大王已经偷偷在你的口袋里塞了十张<span color=\"#ff6c00\">都城机票</>！\
现在，请尝试进行<span color=\"#ff6c00\">十次接机</>。\
列车驶来之后，你可以自己走向车门，亲手<span color=\"#ff6c00\">开门</>，也可以使用快捷按钮开门。",
	},
	[826004030] = {
		id = 826004030,
		text = "刚才体验的卡池【异枝与重聚】，每天都可以免费接机一次。\
也请多多体验开放中的其它卡池。\
目前最推荐的，是卡池【契约初成】。你可以最多体验500次免费接机，并自选最想要的10次接机结果。详情请见卡池本身的介绍。\
未来，你可以随时点击主菜单的<span color=\"#ff6c00\">接机</>按钮，进入时间之外的站点。",
	},
	[826004031] = {
		id = 826004031,
		text = "呀！又是我，你的好朋友赛文楼德大王。\
怎么，被吓到了吗？\
听好了，虽然我们身处命运之线（Nornium）交错的可疑空间，但我不是可疑人士。\
虽然我接下来会带你去一个更可疑的地方，但我不是可疑人士。\
更可疑的地方……嗯，它的名字叫做<span color=\"#ff6c00\">套房快乐趴</>！\
你会喜欢那里的……那是你即将拥有的产业，我只是提前带你去看看它。\
相信赛文楼德大王吧！她比你更了解你自己。",
	},
	[826004032] = {
		id = 826004032,
		text = "今后，你可以随时使用这台穿梭机离开无序之都，登上自己的战舰，进行<span color=\"#ff6c00\">远航</>。\
在<span color=\"#ff6c00\">远航</>中，可以获取各类收益，包括仅能从远航中获得的独特材料。",
	},
	[826004033] = {
		id = 826004033,
		text = "在舰桥上层，每次登上舰桥的初始位置附近，你可以找到<span color=\"#ff6c00\">舰桥助手</>。\
如果有事需要<span color=\"#ff6c00\">临时返回</>无序之都，或者想要<span color=\"#ff6c00\">放弃</>当前的远航，都可以寻求她的服务。",
	},
	[826004034] = {
		id = 826004034,
		text = "铛铛！没想到会在这里遇见孤王？还是早就想到了？\
之前孤王说过，「这是你即将拥有的产业，我只是提前带你看看」——你现在明白其中的含义了？\
在时珊瑚树上的「发信」，让你部分超越了时间。而在这里——时间之外、时间之上——所有美好的经历都同时存在，甚至提前存在。在以后的<span color=\"#ff6c00\">版本</>，说不定会增加新的玩法……\
啊，你是不是想问我，什么是系统、什么是版本？\
因为我们不在对话框里，所以你问不了，略略略。",
	},
	[826004035] = {
		id = 826004035,
		text = "每天的套房互动，都有一定量的<span color=\"#ff6c00\">王宫点数</>，可以获取。\
在互动时，只要界面上显示着尚未耗尽的<span color=\"#ff6c00\">莲花王宫</>图像，那么，在进行<span color=\"#ff6c00\">特殊互动</>后，就可以获得王宫点数。\
王宫点数可以用于<span color=\"#ff6c00\">兑换家具</>。\
获得重复家具时，也会获得王宫点数。",
	},
	[826005001] = {
		id = 826005001,
		text = "星图上的<span color=\"#ff6c00\">有色连线</>，代表了「已经探索」，前往时不需要消耗回合。\
而<span color=\"#ff6c00\">白色连线</>的相邻坐标，需要消耗1回合，跃迁抵达。\
<span color=\"#ff6c00\">无连线</>的坐标，不可直接抵达。",
	},
	[826005002] = {
		id = 826005002,
		text = "在单次远航期间，我们会获得一种名为<span color=\"#ff6c00\">金刚凝胶</>的资源（航程结束时不保留）。\
金刚凝胶可以做很多事，包括建造建筑、晋升建筑、刷新选择、替换队员……\
宇宙中的游商，也支持用金刚凝胶购买货物。",
	},
	[826005003] = {
		id = 826005003,
		text = "一般的遭遇战过后，奖励是3选1的<span color=\"#ff6c00\">建筑蓝图</>。\
造出<span color=\"#ff6c00\">建筑</>以后，会让你在战斗中获得一些……强大的，或者稀奇古怪的能力。",
	},
	[826005004] = {
		id = 826005004,
		text = "有了<span color=\"#ff6c00\">建筑蓝图</>，就可以安排工人来建造。\
星图上有<span color=\"#ff6c00\">建筑格</>，去那里部署你的新建筑吧。",
	},
	[826005005] = {
		id = 826005005,
		text = "手中的<span color=\"#ff6c00\">建筑蓝图</>超过<span color=\"#ff6c00\">10张</>时，就无法获得新的建筑蓝图了。\
请时刻注意这一点，否则就只能放弃多出的建筑蓝图，白白浪费。",
	},
	[826005006] = {
		id = 826005006,
		text = "<span color=\"#ff6c00\">拆除</>建筑时，返还30金刚凝胶。\
因此，有不需要的<span color=\"#ff6c00\">建筑蓝图</>时，可以在空的<span color=\"#ff6c00\">建筑格</>上操作一番，换取金刚凝胶，也可有效避免手中的建筑蓝图达到10张。\
<span color=\"#ff6c00\">召回</>建筑时，需要花费金刚凝胶。（在本次教学中，临时免费）\
被<span color=\"#ff6c00\">召回</>的建筑，将化作建筑蓝图，回归手中。\
请注意，在<span color=\"#ff6c00\">建筑格界面上方</>，可以<span color=\"#ff6c00\">快捷选择</>所有建筑格。",
	},
	[826005007] = {
		id = 826005007,
		text = "许多建筑的名字里，存在着相同的字眼，这被称为<span color=\"#ff6c00\">字段</>。\
部署<span color=\"#ff6c00\">字段</>建筑时，星图界面上会亮起一格计数。\
当计数格凑满一竖条时，<span color=\"#ff6c00\">字段</>效果就会生效。",
	},
	[826005008] = {
		id = 826005008,
		text = "当你有3个同样的建筑时，你可以选择<span color=\"#ff6c00\">晋升</>，得到更强的建筑，并获得一个<span color=\"#ff6c00\">异宝</>作为奖励。\
晋升的操作，仍然是在<span color=\"#ff6c00\">建筑格</>完成。\
<span color=\"#ff6c00\">晋升</>建筑时，花费50金刚凝胶。\
你获得了3张相同的<span color=\"#ff6c00\">建筑蓝图</>，现在回到前面的<span color=\"#ff6c00\">建筑格</>，去试试晋升吧。",
	},
	[826005009] = {
		id = 826005009,
		text = "你获得了3张相同的<span color=\"#ff6c00\">建筑蓝图</>，现在回到前面的<span color=\"#ff6c00\">建筑格</>，去试试晋升吧。",
	},
	[826005010] = {
		id = 826005010,
		text = "许多建筑的效果描述里，存在着相同的字眼，这被称为<span color=\"#ff6c00\">关键词</>。\
异宝的<span color=\"#ff6c00\">关键词</>，以及部分角色技能中的<span color=\"#ff6c00\">关键词</>，也都是通用的。\
除了通用的建筑以外，也有一些建筑的效果，只对特定角色生效。",
	},
	[826005011] = {
		id = 826005011,
		text = "己方角色在下一场战斗中，会继承前一场战斗的<span color=\"#ff6c00\">HP</>。\
——也就是说，在高压难度之下，角色的<span color=\"#ff6c00\">HP</>总会越打越少。\
如果想替换出战角色，则需消耗<span color=\"#ff6c00\">金刚凝胶</>。",
	},
	[826005012] = {
		id = 826005012,
		text = "在战斗失败后，角色<span color=\"#ff6c00\">HP</>会回满，但会扣取1点<span color=\"#ff6c00\">生存值</>。\
<span color=\"#ff6c00\">生存值</>归零后，本次远航即告失败。",
	},
	[826005013] = {
		id = 826005013,
		text = "每次使用战舰技能，消耗一发<span color=\"#ff6c00\">舰武载弹</>。\
<span color=\"#ff6c00\">舰武载弹</>和金刚凝胶一样，都是在远航中获得，在航程结束时不保留的。",
	},
	[826005014] = {
		id = 826005014,
		text = "每次远航中，先后有3个<span color=\"#ff6c00\">败者首领</>，会出现在<span color=\"#ff6c00\">巡航基地</>附近，每回合向<span color=\"#ff6c00\">巡航基地</>移动1格。\
<span color=\"#ff6c00\">败者首领</>抵达<span color=\"#ff6c00\">巡航基地</>后，每回合扣取1点<span color=\"#ff6c00\">生存值</>。\
战胜所有的<span color=\"#ff6c00\">败者首领</>，本次远航即<span color=\"#ff6c00\">胜利</>结束。",
	},
	[826005015] = {
		id = 826005015,
		text = "星图中存在着从一开始就可以透过迷雾、直接见到的<span color=\"#ff6c00\">商店类坐标</>。\
商店对远航是重要的，请注意规划路线。\
在星图的远处，也存在着从一开始就可以透过迷雾、直接见到的<span color=\"#ff6c00\">邪星燔祭</>。\
<span color=\"#ff6c00\">邪星燔祭</>是远航中最困难的战斗（本次教学星图中没有，请在后续探索），如能战胜，可以获得额外奖励。",
	},
	[826005016] = {
		id = 826005016,
		text = "在<span color=\"#ff6c00\">总览界面</>中，可以看到<span color=\"#ff6c00\">败者首领</>还有多少回合抵达，以及其它各种有用的信息。",
	},
	[826005017] = {
		id = 826005017,
		text = "在初次体验远航时，就对<span color=\"#ff6c00\">败者首领</>一串三，也许并不是新人的正常追求……\
本次的「引导式远航」，只要胜过第一个<span color=\"#ff6c00\">败者首领</>，就可成功结束了。",
	},
	[826005018] = {
		id = 826005018,
		text = "也请在后续的挑战中，不必立刻追求完全的「通关」。\
战胜了任何一个<span color=\"#ff6c00\">败者首领</>，都会得到奖励。\
请利用这些奖励<span color=\"#ff6c00\">成长</>起来，然后获取完全的<span color=\"#ff6c00\">胜利</>吧。",
	},
	[826006001] = {
		id = 826006001,
		text = "<span color=\"#ff6c00\">长按</>轻攻击，将发动一次迅捷冲刺斩击。",
	},
	[826006002] = {
		id = 826006002,
		text = "在轻攻击的连击<span color=\"#ff6c00\">最后一击</>时，或疾驰技<span color=\"#ff6c00\">成功闪避</>伤害时，武装巨剑上的十字星会亮起。\
此时<span color=\"#ff6c00\">精确点按</>荧光技，将发动更强的斩击，并立即刷新荧光技冷却时间。",
	},
	[826006003] = {
		id = 826006003,
		text = "<span color=\"#ff6c00\">辉光技额外召唤的</>武装巨剑，也可被视为「十字星亮起」。\
对被插入额外武装巨剑的目标，荧光技也可发动更强的斩击并刷新。",
	},
	[826006004] = {
		id = 826006004,
		text = "<span color=\"#ff6c00\">长按</>轻攻击，蓄力后打出射程更远的拳劲。",
	},
	[826006005] = {
		id = 826006005,
		text = "逆戟雀的疾驰技是一个<span color=\"#ff6c00\">受身</>技能，角色不受控时也可以使用。\
在受伤后的一瞬间<span color=\"#ff6c00\">点按</>疾驰技，会触发<span color=\"#ff6c00\">子弹时间</>。",
	},
	[826006006] = {
		id = 826006006,
		text = "每段荧光技都需要在闪光时<span color=\"#ff6c00\">精确点按</>，可以无限连击。\
高连段的荧光技，会为辉光技充能。",
	},
	[826006007] = {
		id = 826006007,
		text = "逆戟雀的辉光技，持续期间可自由移动。",
	},
	[826006008] = {
		id = 826006008,
		text = "变身前后的轻攻击，都可以<span color=\"#ff6c00\">长按</>以蓄力。",
	},
	[826006009] = {
		id = 826006009,
		text = "变身前后的荧光技，都可以长按，也可以<span color=\"#ff6c00\">点按</>立即释放。",
	},
	[826006010] = {
		id = 826006010,
		text = "变身前后的荧光技，<span color=\"#ff6c00\">长按</>时将锁定多个敌人，且蓄力满时为辉光技充能。",
	},
	[826006011] = {
		id = 826006011,
		text = "目标处在近距离时，荧光技使用投刃与追击。",
	},
	[826006012] = {
		id = 826006012,
		text = "目标处在中距离时，荧光技使用光束照射。",
	},
	[826006013] = {
		id = 826006013,
		text = "目标处在远距离时，荧光技使用能量球场，造成伤害时为辉光技充能。",
	},
	[826006014] = {
		id = 826006014,
		text = "目标高速移动时，荧光技使用定身法。",
	},
	[826006015] = {
		id = 826006015,
		text = "自身被击飞不受控时，荧光技为<span color=\"#ff6c00\">受身</>技能，反制敌人。\
这一种荧光技冷却时间极短。",
	},
	[826006016] = {
		id = 826006016,
		text = "目标铁壁烧坠时，荧光技使用全力重斩，造成高额伤害。",
	},
	[826006017] = {
		id = 826006017,
		text = "辉光技，以自身武装变形为信使星之门，引导诺伦线的扭曲与压迫，成为毁灭之光。",
	},
	[826006018] = {
		id = 826006018,
		text = "点按轻攻击，炮击目标，产生爆炸。每次炮击积蓄热量。近身时变为近战攻击。\
过热后无法攻击或使用技能。",
	},
	[826006019] = {
		id = 826006019,
		text = "长按轻攻击，机炮连射，期间仍可自由移动。连射期间不断积蓄热量。\
过热后无法攻击或使用技能。",
	},
	[826006020] = {
		id = 826006020,
		text = "长按疾驰技，主动散热，并为辉光技充能。期间仍可自由移动，但移速降低。",
	},
	[826006021] = {
		id = 826006021,
		text = "点按轻攻击，鞭剑五连击。每段连击使1片护盾片亮起。\
长按轻攻击，拉近敌人，使1片护盾片亮起。",
	},
	[826006022] = {
		id = 826006022,
		text = "长按荧光技增加防御，消耗全部护盾片，松开时造成伤害。（防御与伤害都基于亮起护盾片数量）\
蓄力期间持续吸附敌人。若护盾片全亮，则蓄力期间霸体。",
	},
	[826006023] = {
		id = 826006023,
		text = "点按辉光技，发出正义的律师斥责，攻击敌人，并使全部护盾片亮起。",
	},
	[826006024] = {
		id = 826006024,
		text = "若疾驰技成功闪避伤害，则点亮1个储能罐，并为辉光技充能。",
	},
	[826006025] = {
		id = 826006025,
		text = "储能罐亮起时，增加25%攻击力，在任意轻攻击（点按或长按）后熄灭。",
	},
	[826006026] = {
		id = 826006026,
		text = "点按荧光技，进入瞄准模式。使轻攻击形式变化，且疾驰技效果替换为能量盾。\
能量盾每次格挡成功，点亮1个储能罐，并为辉光技充能。",
	},
	[826006027] = {
		id = 826006027,
		text = "点按轻攻击派出浮塔，使其自动攻击目标，自身不在场时浮塔仍存在。",
	},
	[826006028] = {
		id = 826006028,
		text = "点按荧光技召回所有浮塔，召回过程中，若浮塔穿过敌人，则对其造成伤害，并为辉光技充能。",
	},
	[826006029] = {
		id = 826006029,
		text = "辉光技召唤全身武装，变身。根据使用时的辉光技能量累积，有三层不同的变身增益。",
	},
	[826006030] = {
		id = 826006030,
		text = "点按轻攻击，浮塔五连击，根据段数获取连击点。",
	},
	[826006031] = {
		id = 826006031,
		text = "使用疾驰技，或点按荧光技时，都可以消耗连击点，发射强力导弹。",
	},
	[826006032] = {
		id = 826006032,
		text = "辉光技，调用全部浮塔，进行弹幕轰炸，立刻获得4连击点。",
	},
	[826006033] = {
		id = 826006033,
		text = "变身后，点按荧光技，将根据当前轻攻击连段，使用不同的效果。\
0-2段：将身前的敌人拉向自己。",
	},
	[826006034] = {
		id = 826006034,
		text = "变身后，点按荧光技，将根据当前轻攻击连段，使用不同的效果。\
3段：后撤，霸体，向前攻击。",
	},
	[826006035] = {
		id = 826006035,
		text = "变身后，点按荧光技，将根据当前轻攻击连段，使用不同的效果。\
4段：引力塌缩，高频大范围伤害。",
	},
	[826006036] = {
		id = 826006036,
		text = "辉光技，额外召唤四座武装巨剑，插入场上最多四个敌人，使其无法移动。",
	},
	[826006037] = {
		id = 826006037,
		text = "辉光技对场上敌人发动斩击，并在一定时间内变身，组装巨大太刀，改变轻攻击与荧光技。",
	},
	[826006038] = {
		id = 826006038,
		text = "变身后的轻攻击，不论点按还是长按，都附带额外发射的刀气。\
变身后的轻攻击，可以多蓄力一段。",
	},
	[826006039] = {
		id = 826006039,
		text = "瞄准模式下，点按或长按疾驰技，可开启或持续开启能量盾，格挡伤害时点亮能量罐。",
	},
	[826006040] = {
		id = 826006040,
		text = "瞄准模式下，攻击距离大幅提升。",
	},
	[826006041] = {
		id = 826006041,
		text = "长按荧光技，蓄力后发射多枚导弹，命中时产生爆炸。",
	},
	[826006042] = {
		id = 826006042,
		text = "辉光技发动期间，按键发生变化，获得大威力炮击键，并且武装机身不断自动射出导弹，直至结束。",
	},
	[826006043] = {
		id = 826006043,
		text = "点按或长按轻攻击，施加「下位」标记，减少防御，可叠加30层。",
	},
	[826006044] = {
		id = 826006044,
		text = "长按荧光技，下令机仆保护在场角色，获得减伤与霸体。持续期间逐渐为辉光技充能。",
	},
	[826006045] = {
		id = 826006045,
		text = "使用辉光技后，机仆将留在场上，继承理事卿的轻攻击和荧光技，与当前在场的角色共同行动。",
	},
	[826006046] = {
		id = 826006046,
		text = "机仆也能对敌人施加「下位」标记。",
	},
	[826006047] = {
		id = 826006047,
		text = "辉光技，召唤暗星能量攻击目标，减少目标防御，并对周围敌人造成伤害。",
	},
	[826006048] = {
		id = 826006048,
		text = "长按荧光技，也可获取连击点。松开时消耗连击点发射强化导弹。",
	},
	[832000010] = {
		id = 832000010,
		text = "亿万星体的辐射，亿万种不同的波长，亘古及今，影响着遥远空间之外的物种命运。 \
所谓「本命星」，是指与特定人类个体，在非现实层面上相连的恒星，这一概念的形成，晚于1999年NASA对土星环异变的观测。\
随后的探索，在天文学与生物学等领域展开。\
目前人类已知的是，每一个独立的人类个体，都有一颗「本命星」与之对应。\
与本命星相连的人类个体，能够通过特定手段，激活与星体的联系，从而获得各种超凡能力。\
在不断涌现的超人们的带领下，人类文明取得了飞速的发展。",
	},
	[832000011] = {
		id = 832000011,
		text = "肉眼可分辨的本命星（亮度在6等以上），在全天域中不超过7000颗。\
即使算上仪器探测的暗星，其数量亦是有限。\
因此，大多数人都只能感受到本命星在宇宙中的大致方位。由于太过黯淡，是无法加以观测的。 \
如果一个人的本命星是肉眼可见的，那他就能从内宇宙召唤「武装」，被世人称作「王星祭主」。\
而10等以上的本命星，也会为人带来一些超自然的能力。",
	},
	[832000012] = {
		id = 832000012,
		text = "北斗第二亮星，星等1.79，人称「小天罡」的「贪狼星」。\
大熊座的主星，α星。\
亦即北斗之「天枢」。\
这颗恒星的星命就是赚钱，而且还是二等亮星，所以董画屏赚了超多钱。",
	},
	[832000013] = {
		id = 832000013,
		text = "风水，是调整环境布局，以达到与自然和谐相处的一种哲学。\
将这个概念扩展到太空，就形成了「宇宙风水」理论。\
这一理论的成立并非天然，它的诞生与「本命星」相关理论一样，晚于1999年NASA对土星环异变的观测。\
宇宙的风水，行星星体位置，和能量流的调整，与地球的风水大不相同，需要更多代人的不懈研究。\
目前，在不同行星，或不在星体表面出生的人类，其生辰八字的推算，就已日趋成熟……",
	},
	[832000014] = {
		id = 832000014,
		text = "「签名的联结」，是一种将不同的「恶魔签名」组合在一起的技术。\
每个恶魔的签名，都蕴含着独特的力量。当这些签名被恰当地联结时，它们才能形成强大的协作。\
不正确的联结，可能导致不可预测的后果，比如星光失控、命运纷乱，或现实的破裂。\
因此，「签名的联结」被视为一种高级且危险的技术，只有少数精英人士才能尝试。",
	},
	[832000015] = {
		id = 832000015,
		text = "「恶魔签名」是一种复杂的几何符号，象征着宇宙中飘浮的光基球形生物——「星活体」，或称「恶魔」。\
这些符号是恒星间的语言，用于传递信息和能量。\
每个签名都是独特的，包含了一颗恒星的特性和能量波动。\
人类通过解读和使用这些符号，与恒星建立联系，从而获得对能量的访问和理解。\
因其与传统神秘学中恶魔符号的意外相似性，人们将这些图案称为「恶魔签名」。",
	},
	[832000016] = {
		id = 832000016,
		text = "身为王星祭主之人，可以唤醒内宇宙的「武装」，进入宇宙作战。\
通常来说，除非从小严格训练，否则人们一般都在接近成年时初步觉醒内宇宙的内观。\
本命星亮到肉眼可见的地步，也就是6等亮星以上，才有把「内宇宙」的武装，变换到「外宇宙」的可能性。",
	},
	[832000017] = {
		id = 832000017,
		text = "名医，汞珠糖。\
祖传老西医，本职是继承了「理发师放血医」传统的「四体液医师」，同时也博采众长，精擅各种替代疗法，包括但不限于：\
瑜伽、灵修、中医、冥想、薰香、巫蛊、点穴、催眠、顺势疗法、蒙古大夫……\
在性格方面，汞珠糖属于「懒狗哲学家、史努比系角色」。\
虽然她会遵守医师的誓言，但站在「我佛不渡憨批」的立场，不会主动去找不听话的病人掰扯——也就是说，是见蔡桓公的时候第一次就会跑路的类型。\
「毕竟不听话的病人是工作压力来源的八成嘛。」其本人如是说。",
	},
	[832000018] = {
		id = 832000018,
		text = "威尔士神话把北冕座称为Caer Arianrhod，意为「银环城堡」。阿拉伯人曾把北冕座称为الفكة‎，意为「分离」或「破碎」，指星座类似打散的珠宝。\
在希腊，北冕星座内的七颗小星构成的华冠，是酒神送给阿里阿德涅的新婚礼物。\
但北冕座π星（贯索一）并非这顶冠冕上最著名的七颗宝石，而是冠冕碎裂时散落的珠线。",
	},
	[832000019] = {
		id = 832000019,
		text = "肉眼可分辨的本命星（亮度在6等以上），在全天域中不超过7000颗。\
即使算上仪器探测的暗星，其数量亦是有限。\
因此，大多数人都只能感受到本命星在宇宙中的大致方位。由于太过黯淡，是无法加以观测的。 \
如果一个人的本命星是肉眼可见的，那他就能从内宇宙召唤「武装」，被世人称作「王星祭主」。",
	},
	[832000020] = {
		id = 832000020,
		text = "理事卿莎乐美的本命星，南鱼座α，是全天仅20颗的一等亮星——「邪眼恒星」北落师门。\
古代波斯将北落师门、毕宿五、心宿二、轩辕十四，称为四大王星。\
而这也是当今太阳系文明的认知中，位居众星之上的「四帝星」。",
	},
	[832000021] = {
		id = 832000021,
		text = "在真实的星相学中，是什么因素在施加「命运剪切力」？\
人类尚不清楚它的具体性质，但在杞忧王的指导下，确实可以在宏观宇宙触及它的影子。\
研究者将该因素的物质界投影称作诺伦尼姆（Nornium），由此，也会将对命运的剪切力简称为「诺伦力」。\
目前，诺伦尼姆在太阳系中存在的形态包括：\
金刚凝胶投影（比空气轻、比钻石硬，即为你在远航中开采的主要矿物）\
空间反流体投影（拥有与「黏性」相反的特质，即为构造跃迁航道之风）\
半活体投影（体现出某种单细胞生物的特性，即为「承哀王」泪瓶的本质）\
……等等。",
	},
	[832000022] = {
		id = 832000022,
		text = "水星在占星术的意义上，影响着人类的智力和通讯活动的效率。\
水逆时期通常是文书错误、信息丢失、机械故障、交通干扰，以及各类细节相关问题频发的时段。\
为此，「复乐园理事会」推动了一项拆解水星的计划，以永久根除水逆问题。",
	},
	[832000023] = {
		id = 832000023,
		text = "大陵五（Algol），英仙座β星——「食尸鬼与蛇女之眼」。\
自古以来的占星家，都认为它是最凶恶的凶星。\
在希腊是美杜莎之眼，在阿拉伯是食尸鬼之首。\
希伯来人说它属于莉莉丝，或者撒旦。中国人说它是大陵墓里的朽骨积尸，「不明为吉」。\
每隔68小时49分钟，这颗凶星就会「眨眼」8小时。",
	},
	[832000024] = {
		id = 832000024,
		text = "王星祭主呼唤王星时，身体表面浮现出的犄角。\
由于王星的痕迹被附会为「恶魔签名」，这种犄角也理所当然地被俗称为了「恶魔的犄角」。\
祭主在宇宙中战斗，所用的机甲武装，就是捏碎「角」以后的一种变化。",
	},
	[832000025] = {
		id = 832000025,
		text = "小时候，就像搞笑角色那样，小鱼在跑出悬崖之后，只要意识还没反应过来「该结束了」，就能不受物理规律限制，再跑几步。\
当时小鱼也费解过，是不是自我催眠类的能力。\
但后来她发现这能力不仅对自己，而对其它物体也有效，但很难总结规律。\
两百多年后的今天，小鱼在你的帮助下，终于看清了星命的全貌——是「线」。\
而这线的完整效用，则是「稍微延缓事物的损毁、终结、衰亡」。",
	},
	[832000026] = {
		id = 832000026,
		text = "王星授予人类的「真实星相学」，以数学而论，属于一种内部和外部的拓扑变换。\
辐射后的组织液，漂浮着小宇宙的星相——肝、肺、胃、肾、脑。\
以及恒星恶魔的「签名」所在：心脏。\
土星天的「星环异观」，原理也大致如此。小宇宙和大宇宙，总是一一对应的。\
引导天星与命运的神经丛，在拓扑层面上延伸，借此驱动武装。",
	},
	[832000027] = {
		id = 832000027,
		text = "「败者」，太阳系最凶残的怪物种群。\
最近，似乎有一群「败者」在无序之都附近大量聚集。",
	},
	[832000028] = {
		id = 832000028,
		text = "当过强的星命之光照射人类时，大量受选者往往无法承受光中的辐照，灼烧而死……\
尸体化作怪物，称为「败者」。\
「败者」的成因是多样的。有的恒星之光不够稳定，也有弱者注定无法实现自己的天命，被恒星抛弃。\
有人对命运动摇，走向绝路。有人强硬地改变自己的命运——有成功的例子——但如果做过了头，也会遭到恒星的厌恶。\
弱者中的弱者，则是被中枢、理事会之流的庞大组织，压得喘不过气，被迫走上不情愿的命运之路……\
这样的人，是最容易失败的。\
然而，可悲的是，这样的人在我们的世界，是最多的。\
「恶魔」这个称谓，只是对天上恒星的一种俗称。\
出于每一位王星祭主在沟通星光时，都会从身体某一部位长出犄角的巧合……\
也出于每一个人心中，对那最终到来的失败……对「败者」这个词语本身的，来自基因深处的恐惧。",
	},
	[832000029] = {
		id = 832000029,
		text = "正是因为「第二命星」仓促混乱的生效，才让你的身躯开始了「败者化」。\
这或许是来自双重契约与背叛——与星体的「重婚」是不被允许的。\
「败者」是未能成功获取亮星青睐之人所化，而复活后身体不稳定的你，去吸取「败者」的力量，则可以避免自己也变成「败者」。\
这种疗伤方式，也多亏了「吸血恶魔」现在是你的半身，否则无法实行。\
但如果是理事卿亲自来做，她一定会更高效地，去杀人。\
因为「败者」，说到底也只是劣化的智人。",
	},
	[832000030] = {
		id = 832000030,
		text = "「捕蛇者之手」，天市右垣九。\
Yed Prior，蛇夫座δ，星等2.73。\
借助这医神捕蛇之手，不论是做手术，还是炼金，汞珠糖超凡的手指都绝对可靠。",
	},
	[832000031] = {
		id = 832000031,
		text = "你从本命星得到的能力，被你描述为「信使总可以比别人早知道些东西，只要他愿意拆开信封。」\
在小鱼呼唤恶魔犄角时，你似乎「看见」了什么，由此判断她的绝症是虚假的。\
在战斗中，那些荧光技的多变，或许也是因为你比别人多「看见」了什么。\
你也会受到本命星照耀的副作用，「拆信」所见的事物，介于真实和虚幻之间。\
一定程度上，损害视力。\
或者说，需要从幻视里分辨真伪。",
	},
	[832000032] = {
		id = 832000032,
		text = "时间是一棵不断分叉的珊瑚，人们住在不同的「时珊瑚枝」上。\
人类应该生活在单线的时间之内，这是常识——即使亮星照耀之人也应该如此。\
但你能够拆开来自其它「时珊瑚枝」的信封，因此，是「能见者」。\
这「拆信」的代价，就是不可控的未来……是那些由你一手造成的珊瑚分支。\
为了帮助你不陷入时间的乱流，某人为你创造了「时珊瑚枝管理系统」。\
利用这个系统，你可以在时空之间任意跳跃，也可以主动向其它珊瑚枝上的你「发信」。\
拆开「平行时间来信」的你，或许能够趋吉避凶、完成一些本来做不到的事……",
	},
	[832000033] = {
		id = 832000033,
		text = "NASA，即美国国家航空航天局，成立于1958年，是美国政府负责国家航空和太空计划的机构。NASA的主要任务包括太空探索、地球观测以及航天技术研发。\
历史上，NASA成功实施了多项重大太空任务，包括阿波罗月球登陆计划、航天飞机计划以及火星探测器的发射。\
1999年，NASA 观测到了土星环的一系列异常现象：星环纹理以奇特的方式重组，形成了令人困惑的图案。",
	},
	[832000034] = {
		id = 832000034,
		text = "「六边形风暴」是土星北极区域的一种独特气象现象。\
风水中最强调「藏风纳气」，而这正是太阳系内最佳风水宝地之一。\
风暴结构的显著特征，是其几乎完美的六边形形状，每条边长约13,800公里，足以容纳两个半地球。\
巨大的六边形风暴在土星大气层中持续旋转，其环流类似于地球上的飓风，内部环境极为恶劣，风速极高，气流混乱。\
它的色彩和纹理随季节变化而变化，显示了土星大气的复杂和多变。但尽管存在多年，这个风暴的形状和尺寸，仍保持了惊人的稳定性。",
	},
	[832000035] = {
		id = 832000035,
		text = "于深空之海静默燃烧的、鲸鱼般的诸恒星，正是照亮命运的天上诸王——名为「星活体」的光基球形生物（Animales Esférico）。",
	},
	[832000036] = {
		id = 832000036,
		text = "当过强的星命之光照射人类时，大量受选者往往无法承受光中的辐照，灼烧而死……\
尸体化作怪物，称为「败者」。\
如此种种现象（犄角、败者、签名……），都让人觉得「星活体」与地球文化的「恶魔」有关。\
但或许真正的因果关系是，人受命运（Norn）折磨，在痛苦中看见诺伦尼姆（Nornium）的幻象，在文化记忆中留下了「恶魔」的印记……",
	},
	[832000037] = {
		id = 832000037,
		text = "「小行星撞击」是当小行星或类似天体与地球或其他行星相撞的事件。这类事件在太阳系中相当普遍。撞击的影响因小行星的大小、速度、撞击角度和地点而有所不同。\
地球历史上有小行星撞击的明显记录。例如，大约6600万年前，巨大的小行星撞击地球，引发了一次大规模的生物灭绝。这一撞击释放了巨大的能量，导致全球性的气候变化和生态环境的破坏。\
对于其他行星，例如月球上的陨石坑，也是小行星撞击的结果。火星和其他行星上也观察到了类似的撞击痕迹。\
过去的科学家通过观察小行星轨道来评估其对地球的潜在威胁。他们研究了多种方法来改变可能威胁地球的小行星轨道，包括利用重力牵引、撞击飞行器和核爆炸。",
	},
	[832000038] = {
		id = 832000038,
		text = "金星的魔力，总能激起人心中的种种欲望。\
让人想要用金钱和权力，交换至高的肉体享受。\
沉湎于超过大脑承受能力的浮华，会让人丧失正常的思维判别能力。\
这就引发了一种特殊的心理疾病——\
它的症状就是，「无论身处太阳系的哪个角落，都会幻想自己正在金星天的黄金地段疯狂消费」。",
	},
	[832000039] = {
		id = 832000039,
		text = "由莎乐美治下的金星政府发行，在太阳系流通最广的货币。\
外观轮廓类似扇贝，象征维纳斯（金星）的诞生。",
	},
	[832000040] = {
		id = 832000040,
		text = "「第二命星」是基于「本命星」研究的延伸，指人类个体与第二颗恒星建立的额外联系。\
小鱼遭遇的那种骗局，其目标只是「命星转移技术」的皮毛而已。\
也许他们是想冷冻受害者的躯壳，努力复现理事卿的技术。\
但理事卿本人的最新研究进度，是独一无二的「命星保存能力」。\
当然，理事卿认为：本命星的迁移，必须秘而不宣。因为知识应该保存在最安全的地方——也就是最强者的脑子里。\
「第二命星」技术的第一个实验对象，只能是她自己。\
只是，她对「第二命星」的燔祭尚未完毕，就被你的那次刺杀打断。\
在混乱中，那颗「第二命星」同时复活了你和理事卿，这才导致了现在的状况。",
	},
	[832000041] = {
		id = 832000041,
		text = "王星授予人类的「真实星相学」，以数学而论，属于一种内部和外部的拓扑变换。\
辐射后的组织液，漂浮着小宇宙的星相——肝、肺、胃、肾、脑。\
以及恒星恶魔的「签名」所在：心脏。\
土星天的「星环异观」，原理也大致如此。小宇宙和大宇宙，总是一一对应的。\
引导天星与命运的神经丛，在拓扑层面上延伸，借此驱动武装。",
	},
	[832000042] = {
		id = 832000042,
		text = "在本命星的帮助下，从人类的创造力中，诞生了许多事物，提升了太阳系文明所能触及的范围。\
但也有人用创造力与星命去寻求……如何利用强大的本命星，更好地欺压弱者。\
他们即将利用大陵五（Algol），英仙座β星——「食尸鬼与蛇女之眼」——故意制造行星级的灾难，然后再去救灾，来提升人民的归属感，和就业率。\
他们拥有创造「无眠之人」的能力，本可以让世上几个最聪明的大脑免疫睡眠之苦……\
但他们没有这样做，而是让恒星之光四散，换取了上万名「可牺牲员工」每天少睡一小时。\
注视这一切的人，是「复乐园理事会」的「第一理事卿」，她是太阳系里最有权势的人。\
理事卿拥有比英仙座β星（食尸鬼与蛇女之眼）更亮的眼睛，那就是「四帝星」之一的邪眼恒星，北落师门。\
一年前，理事卿遭遇刺杀而亡……\
可惜，理事会的邪恶统治并未落幕。",
	},
	[832000043] = {
		id = 832000043,
		text = "莎乐美死后的这一年里，「理事会」的诸寡头之间山头林立，互不相服，分裂至今。但即使莎乐美已死，太阳系各地都还留有她的诸多黑白产业，遍布各个领域，是太阳系内非常重要的一方巨大势力。\
而至今「理事会」中仍有极高呼声，不希望莎乐美的产业走向解体。也有一批人不相信莎乐美真的已被信风杀死，一直在追寻她的下落。\
另一边，即使是「中枢」与「义人」，如今也已发现：虽然莎乐美的当年统治并不高尚，但这个没有莎乐美约束黑道势力的世界，反而变得更糟糕了。\
那些互相争斗的金融寡头与黑道大佬们，也在争斗中了解了一个事实，那就是仅凭自己的力量，没有办法吃下整只利维坦的尸体。\
曾经的那位复乐园第一理事卿，或许就是以自己的魅力与胸襟，包容了那些被其他人当做「危害与异物」排斥的东西吧。",
	},
	[832000044] = {
		id = 832000044,
		text = "理事会正群龙无首，人人无不怀念理事卿莎乐美。\
