但理事卿是唯一能整合理事会的人！是唯一强大到能带领理事会，压制「中枢」的强者、智者！兄弟们已经别无选择，这个「理事卿之声」……不管他要贪大家多少钱、抢大家多少权……他也已经是大家仅存的希望了！\
——怀抱着如此崇拜的心情，属于你的理事会分部，开始了日常性的运转。",
	},
	[832000045] = {
		id = 832000045,
		text = "水星在占星术的意义上，影响着人类的智力和通讯活动的效率。\
水逆时期通常是文书错误、信息丢失、机械故障、交通干扰，以及各类细节相关问题频发的时段。\
