	},
	[832000047] = {
		id = 832000047,
		text = "在当今的太阳系内，太空海盗的来源非常复杂。\
比如「线团海盗」，活跃于该隐环（小行星带），是在乱象中堕落了的，曾经合法的领航者们。\
由于木星天的缺位，小行星带受木星引力影响而形成的「柯克伍德空隙」，其形态发生了改变。旅者在附近必须寻求领航者的帮助，否则无法穿越迷阵。\
在太阳系海盗的鄙视链上，这种从向导改为打劫的行当，也属于万人唾弃的最底层。\
比如「复古海盗」，由一群富裕人士，带着自己的私人飞船组成。这些人通常会将自己的飞船制作成真正的「船」的造型，甚至会安装桅杆和风帆。他们会饲养一只鹦鹉作为宠物、故意将义肢做成棍状或勾爪的形状、留着奇怪的胡子、戴着三角帽，并以骷髅作为自己的旗帜。\
董画屏海盗团的未来，或许也会向着不可预测的方向，产生新的变化……",
	},
	[832000048] = {
		id = 832000048,
		text = "互不相识的三十六义人，简称「义人」。\
「义人」并不统率任何势力，他们只是太阳系的游侠。\
作为太阳系三大力量中的一方，这三十六位势单力孤、甚至互相之间可能从未见面的「义人」，或许只会让人觉得无用且怪异。\
但曾经迈入现代文明的世界，在新纪元却被邪教与寡头瓜分的现实，已足够令人绝望。\
就是在这样绝望的浮世，人才会期待那最渺茫的一线希望……或者奇迹。",
	},
	[832000049] = {
		id = 832000049,
		text = "乏味而停滞、平庸而腐败，比理事会稍微无害，但还是相当有害的……世界政府。\
一年前的太阳系两大势力之一，相对大反派「复乐园理事会」而言的……无能的小反派，世界政府。\
在通常的认知中，面对世界政府的腐朽，以及理事会的种种恶行，人们总会期待某位「义人」的降临，而「义人」也往往能够回应人们的期待。\
但奇怪的是，在那次刺杀理事卿的行动中，世界政府成为了科斯明船长邀来的临时盟友……",
	},
	[832000050] = {
		id = 832000050,
		text = "如今世界政府已被篡权，新成立的机构叫做「无尽全盛统合中枢」，简称「中枢」，现在与理事会并立为太阳系两极势力，分庭抗礼。\
据说「无尽全盛统合中枢」的前身，是一个尊奉「-26.7等亮星，太阳」的小众邪教。\
篡夺了世界政府的统治之后，这邪教也就立刻变成了正规宗教。\
世界政府被「中枢」政变篡权后的这一年里，「中枢」的膨胀速度无可抑制。\
终于，在一年后的今天，它已几乎与理事会平起平坐了。",
	},
	[832000051] = {
		id = 832000051,
		text = "由于海王天的力量掌管幻觉、梦境、精神的修行……等等方面，在初步接触并受到影响之后，人们决定开发并享受它所带来的、逃离世俗和物质世界的功能。\
每个阶层和身份的人，都能在海王天附近的能量场中用特殊的方式找到慰藉，这成为了控制宗教、贵族和贫民们的好手段。\
随着大气层被慢慢清除，海王星的地幔甲烷、氨和水被收集、储存，用于建设围绕在海王星周边的人造卫星。\
这些人造卫星的轨道靠近海王星，以利用潮汐力带来的更多热量。\
各式豪华卫星脱离了卫星的刻板印象，是富人们的度假天堂。",
	},
	[832000052] = {
		id = 832000052,
		text = "旧王国，亦即地球，作为人类文明的起源地，承载着众多历史时期的遗产。\
在旧王国的大地上，留有许多科技爆炸时期的初期开发痕迹，与还在维持运作的旧设备。\
地球低轨道区域上有若干空间定居点，包括奥尼尔圆柱和环形空间站，这些结构展示了人类太空探索的早期形态。\
连接地球与月球的主电梯——也是唯一横跨地月的超长电梯，被暗中命名为「脐带」。\
月面的巨型人造恶魔签名，是为了捕获早已死去的虚星（计都罗睺）的影响。\
而「脐带」在星相学上，则被寄予了「重新降生」的期待。\
这件事是机密中的机密，只有少数理事会高层知晓。",
	},
	[832000053] = {
		id = 832000053,
		text = "金星，被称为「晨星」或「夜星」，是太阳系中第二颗行星，以其亮白的外观和接近地球的轨道而闻名。\
从天文学角度来看，金星的环境极端且恶劣，拥有浓厚的二氧化碳大气层和极高的表面温度，这使得它在传统意义上不适宜居住或资源开发。\
然而，在「真正的星相学」被引入之后，金星因占星学中的象征意义——「一切物质和肉体幸福的给与者」——而被赋予特殊地位。\
金星具有某种神秘的力量，可以促进人类社会的财富增长，因此，金星被理事会定为太阳系的金融和娱乐中心，一个汇集和放大人类欲望的地方。\
在这里，人们可以体验到古今中外所有可能的、现存的，甚至是未来的享乐方式。\
为了维持这一中心地位，大批量的物资从星系各处被运送到金星，而维持补给线的航路，也成为了潜在的消费者。",
	},
	[832000054] = {
		id = 832000054,
		text = "「星环异观」是一项宏大的宇宙工程，整个土星环被改造，成为大量恶魔签名的联结。这一改造不仅是技术上的壮举，也是对「太空风水」理论的实践和验证。\
在「星环异观」的设计中，土星环的每一块冰石和尘埃都被精确地排列和雕刻，形成了一个巨大的恶魔签名网络。这个网络是太阳系内「真实星相学」的一切运作的基础，是太阳系文明最为核心的部分。\
为了使太阳系内的「占星魔法」成立，土星环上联结的恶魔签名是不断更新的。\
在这个过程中，统治着太阳系各个部分的不同势力都介入参与了此事，在其中添加了有利于自己的规则。\
而这也暴露出了一个事实：只要对土星环进行改动或者破坏，就能让各大组织的立身之本受到动摇，或是让新的组织崛起。",
	},
	[832000055] = {
		id = 832000055,
		text = "有名的、中立的太空城，位于「土星天」。\
包括理事会在内的各种势力，都被欢迎进入，乱七八糟地共存着。\
那里的城主很强，共存的各方虽然有时也会抢地盘，但从没人想过要征服，或者吞并「无序之都」。\
你曾经伪造过一张「无序之都」通行证，附带一个假身份，以及一个新的名字（和信风一样，也是你的多个名字之一）。\
所以，「无序之都」恰巧是你比较方便混进去的地方。",
	},
	[832000056] = {
		id = 832000056,
		text = "在「无序之都」，你逐渐在理事会的影响之外，也发现了许多「中枢」的影响。\
所谓「瘦死的骆驼比马大」，理事会现在仍有包括「第一繁荣星天」金星天在内的四大基本盘，对半壁太阳系的掌控依旧稳定。\
但理事会在他们的高管看来「本该一家独大」，而绝不该是一年后的现状：与「中枢」形成了意料之外的僵持局面。\
对理事会全盛时期的追忆，就构成了某些高管每天悔恨哀叹的主要内容。",
	},
	[832000057] = {
		id = 832000057,
		text = "你折服了斋藤大佐的画面，在随后短短几小时的信息传播之中，取得了理事会分部大量成员的信任。\
随后，你对「无序之都」的理事会分部发表了公开演讲。\
你自称理事卿的使者，宣布理事卿尚在人间。\
你说，理事卿需要在无人知晓之地休养，不能遭受打扰……当然，她曾经的手下全都明白，这句话的意思是，避免篡位者威胁到虚弱的自己。\
这就是理事卿本人的性格，这让你变得更加可信了。\
在这之后，你开始接管「无序之都」的理事会分部。",
	},
	[832000058] = {
		id = 832000058,
		text = "巴比伦人建立了星座与黄道十二宫的体系，揭示了星相与生命的联结。\
他们的术法由埃及和希腊继承。希腊人所说的小宇宙和大宇宙，也是为了表示自然界的微小尘埃（如人类），与更巨大的飘浮实物（如恒星）之间的关系。\
印度的吠陀占星学（周谛示），又被称为「光的学术」。这种术法利用了光线格局构成的星盘，来研究人体能量如何被天体能量辐射、烧灼、同化。\
而在中国，则有「果老星宗」、「七政四余」、「紫微斗数」，为皇家所恐惧。\
他们的恐惧并非虚妄——历代中国君王最忌讳的妖星「荧惑」，在人类离开地球的宇宙纪元，也引发了太阳系内最大的一场灾难。",
	},
	[832000059] = {
		id = 832000059,
		text = "作为一位祖传老西医，汞珠糖与炼金术关系颇深。\
而在炼金术中，两条蛇缠绕成倒置的众神使者手杖，就代表汞元素，属阴，和太阳相对立。\
当硫（太阳）和汞（月亮）被放在一起的时候，它们通常被描绘成「红王」和「白后」。",
	},
	[832000060] = {
		id = 832000060,
		text = "老板娘（逆戟雀）的诸多生意之一。\
其中一家分店，开在了最显眼的「莲花王宫酒店」的大堂吧台。",
	},
	[832000061] = {
