	},
	[832000066] = {
		id = 832000066,
		text = "莲花王宫酒店是一家跨太阳系的豪华连锁酒店，起源于旧王国时代的泰国，以结合传统泰国建筑风格和现代豪华设施而著称。\
该连锁酒店在金星天、旧王国、无序之都和海王天设有主要分店。每个分店的设计既反映了所在地的特色，又保持了品牌的经典泰国元素。",
	},
	[832000067] = {
		id = 832000067,
		text = "「商场菇」是一种设在金星表面上空的，半圆形的悬浮商业空间站。\
在金星的大气层中遍布着「商场菇」，从宇宙中俯瞰，呈现大大小小的圆形。\
这些结构以其独特的菇状设计和高效的空间利用而著称，成为了金星商业活动的重要中心。\
商场菇的设计充分考虑了金星恶劣的大气环境，采用了先进的悬浮技术和环境控制系统，确保了空间站内部的人类活动和商业运营的可行性。",
	},
	[832000068] = {
		id = 832000068,
		text = "在过往的2012年，人类世界仍在努力登土之际，土星环的改造就已彻底完成。\
