由于魔法力量最充足，魔法侧的事物在土星天是最多的。\
基于同样理由，土星天也是「败者」最喜爱的一个星天。\
土星周边的许多小天体都曾被识别为卫星，不过，为了更加精确地建造恶魔签名法阵，许多环内的大冰晶和小行星都被拆解为更加细碎的形态，只留下了那些因为各种原因无法根除，或是离环边缘较远的大型卫星。",
	},
	[832000069] = {
		id = 832000069,
		text = "如今世界政府已被篡权，新成立的机构叫做「无尽全盛统合中枢」，简称「中枢」，现在与理事会并立为太阳系两极势力，分庭抗礼。\
据说「无尽全盛统合中枢」的前身，是一个尊奉「-26.7等亮星，太阳」的小众邪教。\
篡夺了世界政府的统治之后，这邪教也就立刻变成了正规宗教。\
世界政府被「中枢」政变篡权后的这一年里，「中枢」的膨胀速度无可抑制。\
终于，在一年后的今天，它已几乎与理事会平起平坐了。",
	},
	[832000070] = {
		id = 832000070,
		text = "一年前那次刺杀行动之后，缇缇波芙开始专注于反抗「中枢」，活跃了一段时间，然后消失。\
你对「中枢」知之甚少，所以在这次任务过后，你开始注意起了对「中枢」的观察，也准备特意去接一些与「中枢」相关的任务。",
	},
	[832000071] = {
		id = 832000071,
		text = "当初科斯明牵头，与世界政府合作，刺杀理事卿莎乐美，其实是他为了建立「中枢」做准备。\
你和理事卿一「死」，船长就背叛了你，与「中枢六尽」的其余五人发动了政变，篡位上台，以「无尽全盛统合中枢」替代了世界政府。\
此后，在理事卿缺位、理事会内部一片混乱，无暇顾及「中枢」时，又是科斯明船长运筹帷幄，在真空期内迅速地催生了「中枢」对太阳系的席卷。\
毫不夸张地说，「中枢」能在区区一年之内，对被篡权的世界政府完成改造、统合，离了「义尽的科斯明」这个人，是完全做不到的。",
	},
	[832000072] = {
		id = 832000072,
		text = "这一年来，总有很多人盛传，理事卿还活着。\
时不时会有一些神秘现象出现，被迷信的人们安到理事卿的头上。\
