	},
	[832000074] = {
		id = 832000074,
		text = "斋藤大佐为了建立新的商城，拆除了一座城市氧气生成塔（它是重要的基础设施，但大佐说它无法修复，已经开始泄漏有毒气体了）。\
市民们早已开始迎接新建的奢侈品商城，生成氧气的基础设施已被遗忘。\
但部分遗留在太空中的废弃机械，正在生成氧气以外的东西。\
有毒气体……或者一些有毒气体以外的东西，吸引了一群「败者」的母巢迁移。\
