	},
	[832000075] = {
		id = 832000075,
		text = "在吠陀占星学中，木星有着「所有行星的上师与指导者」这种神秘意味上的重要性，大部分时候，不管木星处于任何的星宫，都会强化好的星相效果，亦或是由本身占据星宫为所有的事情带来好运。\
即使其他行星位置不佳，如果木星在星图中的位置强而有力，就能得到最后一刻的援助，以渡过困难时期。\
这就是土星环总控天象、而木星成为天象最大变数的理由。\
另外，木星大红斑是太阳系最大的风暴。用风暴去压迫蝴蝶，可以说是「逆蝴蝶效应」。\
基于这些重要性，「中枢」认为，将木星完全控制，就是势力立足于太阳系的最大基本盘。\
木星是整个人工星相体系中，最重要的一张「万能牌」。\
所以，必须优先投入资源确保对木星轨迹的控制。",
	},
	[832000076] = {
		id = 832000076,
		text = "真命总统、第二行星无眠至权、冬日帝星照耀的受命者、复乐园第一理事卿、总控四天之主——\
复乐园理事会的理事卿，莎乐美。\
聪慧、优雅又邪恶，彬彬有礼的超级强者。\
世上愿意对面包说「请」、「谢谢」、「对不起」的吸血鬼可不太多，而她正是其中之一。\
一年前，理事卿遭遇刺杀而亡。",
	},
	[832000077] = {
		id = 832000077,
		text = "莎乐美死后的这一年里，「理事会」的诸寡头之间山头林立，互不相服，分裂至今。但即使莎乐美已死，太阳系各地都还留有她的诸多黑白产业，遍布各个领域，是太阳系内非常重要的一方巨大势力。\
而至今「理事会」中仍有极高呼声，不希望莎乐美的产业走向解体。也有一批人不相信莎乐美真的已被信风杀死，一直在追寻她的下落。\
另一边，即使是「中枢」与「义人」，如今也已发现：虽然莎乐美的当年统治并不高尚，但这个没有莎乐美约束黑道势力的世界，反而变得更糟糕了。\
那些互相争斗的金融寡头与黑道大佬们，也在争斗中了解了一个事实，那就是仅凭自己的力量，没有办法吃下整只利维坦的尸体。\
曾经的那位复乐园第一理事卿，或许就是以自己的魅力与胸襟，包容了那些被其他人当做「危害与异物」排斥的东西吧。",
	},
	[832000078] = {
		id = 832000078,
		text = "这一年来，总有很多人盛传，理事卿还活着。\
时不时会有一些神秘现象出现，被迷信的人们安到理事卿的头上。\
迷信活动升级——并如理事会的传统那般商业化——以后，就有人开始沟通理事卿那无处不在的「眼」的意志。\
比如无序之都的「帝星祭典」上，就售卖着一种以理事卿的生平和成就为主题，最近非常流行的神秘学小道具：「命运卡」。",
	},
	[832000079] = {
		id = 832000079,
		text = "你伪装了自己的身份，使用假名、带着理事卿莎乐美的力量，来到了理事会在「无序之都」的据点，自称第一理事卿的使者——「理事卿之声」。\
