你从本命星得到的能力，被你描述为「信使总可以比别人早知道些东西，只要他愿意拆开信封。」\
在小鱼呼唤恶魔犄角时，你比别人「看见」得更多，由此判断她的绝症是虚假的。\
在战斗中，那些荧光技的多变，或许也是因为你比别人多「看见」了什么。",
	},
	[832000081] = {
		id = 832000081,
		text = "「信风」是你所使用的上一个名字，你进入「无序之都」时，为自己取了现用的名字。\
而你最新的名字，则是「理事卿之声」。",
	},
	[832000082] = {
		id = 832000082,
		text = "作为「义人」，你常与来自欧洲的「科斯明船长」，和来自非洲的「缇缇波芙」，一同行动。\
在外人眼里，你就是这三人里的队长，毕竟你是影响太阳系格局的「三十六义人」之一。\
但其实，科斯明船长才是那个像大哥一样，带领大家前进的人。\
在他身上，有一种胸有成竹的「船长」气派，行动总是足够斩钉截铁、不容置疑、干净利落。\
就算他作为船长把船开进宇宙鲸鱼嘴里了，你也一定会觉得那是宇宙鲸鱼的错。\
其实，作为船长和大哥的他，总是必须思考很多。只是在队友面前，他永远不会表露焦虑的一面。\
他尽量只让队友看到自己的可靠，放任他们来依靠自己。",
	},
	[832000083] = {
		id = 832000083,
		text = "科斯明船长……就是「中枢」的六大创始人之一，「中枢六尽」中的……「义尽的科斯明」。\
当初科斯明牵头，与世界政府合作，刺杀理事卿莎乐美，其实是他为了建立「中枢」做准备。\
你和理事卿一「死」，船长就背叛了你，与「中枢六尽」的其余五人发动了政变，篡位上台，以「无尽全盛统合中枢」替代了世界政府。",
	},
	[832000084] = {
		id = 832000084,
		text = "作为「义人」，你常与来自欧洲的「科斯明船长」，和来自非洲的「缇缇波芙」，一同行动。\
缇缇不是「义人」，但你们因同一位老师的教导，而成为了共同行动的游侠。\
缇缇波芙（Tete Povu）是斯瓦希里语的名字，意为「易散的泡沫」。\
她是航海家、博物家、收藏家、巫术家，以及诗人。\
是来自坦桑尼亚部落的非洲姑娘，生长于乞力马扎罗山下。",
	},
	[832000085] = {
		id = 832000085,
		text = "曾经，你们三人的老师逝世之前，曾经拜托过缇缇，要她教导你「正常的情感」。\
因为老师觉得你从小生活在与世隔绝的环境，虽然后来成为了著名的传奇强者、游侠，但老师担心你在情感方面仍有缺失。\
而原本就喜欢你的缇缇波芙，在实践这种「教导」时，总是偏向爱情的方向。\
过去，刚开始学习的你，进展似乎不太顺利。\
但在刺杀事件一年后的时间线上，你即将开始运用缇缇所授的技巧，成功出师……",
	},
	[832000086] = {
		id = 832000086,
		text = "从摩琳娜口中，你获得了令你不可置信的消息。\
摩琳娜说，缇缇早就死了，死于「中枢六尽」的围攻……",
	},
	[832000087] = {
		id = 832000087,
		text = "名医，汞珠糖。\
祖传老西医，本职是继承了「理发师放血医」传统的「四体液医师」，同时也博采众长，精擅各种替代疗法，包括但不限于：\
瑜伽、灵修、中医、冥想、薰香、巫蛊、点穴、催眠、顺势疗法、蒙古大夫……\
在性格方面，汞珠糖属于「懒狗哲学家、史努比系角色」。\
虽然她会遵守医师的誓言，但站在「我佛不渡憨批」的立场，不会主动去找不听话的病人掰扯——也就是说，是见蔡桓公的时候第一次就会跑路的类型。\
「毕竟不听话的病人是工作压力来源的八成嘛。」其本人如是说。",
	},
	[832000088] = {
		id = 832000088,
		text = "你与小鱼来到了「无序之都」，被一位叫做逆戟雀的商人当做了偷渡客，提供了一些无偿的帮助。",
	},
	[832000089] = {
		id = 832000089,
		text = "在老板娘逆戟雀的介绍下，你接到了一份佣兵的工作。\
按照她的指引，你找到了阿特拉斯公司的「中间人」，展开了你在无序之都附近的活动。",
	},
	[832000090] = {
		id = 832000090,
		text = "老板娘是「无序之都」最大的黑市商人，生意规模比之前她自谦的描述要大得多。\
她也有一些明面上的生意，比如这著名的连锁饮品店「多冰少沙」。\
在店里买饮料时附赠的小模型，逐渐演变成了一套非常流行的集换式模型对战游戏。\
不知不觉间，这套模型对战游戏的收入，超过了她原本经营的黑市本业……",
	},
	[832000091] = {
		id = 832000091,
		text = "你在太空黑市亲眼目睹了一次老板娘被「中枢」刁难的现场。\
这也是你第一次知道，老板娘的生意到底是在被谁刁难——原来，是「中枢」的人。\
于是你让小鱼回船，自己变成了「信风」的形象，出面介入。\
老板娘对「义人信风」的出现，似乎有超乎正常的震动。\
她好像单方面认识信风。\
你也敏锐地察觉到了老板娘的表情，但你自己觉得，你在这次以假身份来到无序之都前，应该不认识老板娘。",
	},
	[832000092] = {
		id = 832000092,
		text = "在与辩才姬打交道的过程中，你意外地发现了一叠文件。\
《重要！「中枢之喉舌」相关！——逆戟雀的官司，有点难办》。\
老板娘在委托辩才姬打官司？\
老板娘最近被「中枢」不断派人刁难，她惹上的麻烦，似乎就是这个「中枢之喉舌」。",
	},
	[832000093] = {
		id = 832000093,
		text = "在老板娘逆戟雀的介绍下，你接到了一份佣兵的工作。\
按照她的指引，你找到了阿特拉斯公司的「中间人」，展开了你在无序之都附近的活动。",
	},
	[832000094] = {
		id = 832000094,
		text = "旧世纪末，七月之上。\
公元1999年，NASA观测到了土星环的异变。\
星环的纹理不再自然，而是构成了「恶魔的签名」。\
2025年，科考队登陆土星，受恶魔指引，进入土星极地的六边形风暴。\
恶魔自称安格禄莫亚，对人类表示了善意，并与人类分享了「真实的星相学」。\
于深空之海静默燃烧的、鲸鱼般的诸恒星，正是照亮命运的天上诸王——名为「星活体」的光基球形生物（Animales Esférico）。\
安格禄莫亚，亦属其中。\
这位带来天上知识的来者，正是「太阳」之君。\
人类获得了来自「本命恒星」的伟力与智识，又利用这全新的力量，积极推动着太阳系本身的「行星级」星相改造。\
自此，智人（Homo sapiens）这一古老又年轻的物种，终于成为了自身起源恒星系的完整主宰。\
而对人类吐露了真相的恶魔安格禄莫亚，却被世人称作King of Kosmikophobia，即「星夜恐骇之王」，或名「杞忧王」。",
	},
	[832000095] = {
		id = 832000095,
		text = "佣兵任务的委托人。\
声称自己是水星天的工人，想要逃往金星天。\
其言行处处透出可疑。\
最终，你发现了李先生的真相。",
	},
	[832000096] = {
		id = 832000096,
		text = "在故事的开头，那位遇事相当沉不住气的办事员。\
他曾经教导小鱼说，如果你身在顶端，那你的前路大概率就只有「向下」这一个方向。\
说不定他就是从伯恩斯这里听到的金句……？\
总之，那个办事员最后确实「向下」了——在坑边被你打下去的。",
	},
	[832000097] = {
		id = 832000097,
		text = "佣兵任务的「目标」。\
被理事会干部伯恩斯先生怀疑出轨的妻子。",
	},
	[832000098] = {
		id = 832000098,
		text = "佣兵任务的委托人。\
理事会的干部。",
	},
	[832000099] = {
		id = 832000099,
		text = "「中枢」高官的公子。\
当街抓走年轻女性，后者惨叫着「谁来救救我」，然后被强行拖走了。\
没有任何人作出反应，气氛和谐的商业街依然气氛和谐。\
连无序之都的警卫与私兵，都对这奇怪的突发事件无动于衷。",
	},
	[832000100] = {
		id = 832000100,
		text = "「无序之都」理事会分部的头目，斋藤大佐，是一个「能沟通理事卿意志」的人。\
斋藤大佐能够召唤理事卿的「机仆」——那套武装机甲的半身——然后声称自己从「机仆」那里，得到了理事卿的指示。\
「机仆降临」，是理事卿在太阳系的各分部，都无人能够做到的，绝无仅有的神迹。\
所以「无序之都」的理事会分部，是太阳系内仅有的，全员严重偏向「理事卿未死」这一说法的理事会分部。\
在普通民众中，有许多人对理事卿既迷信，又怀念。\
在这种背景下，斋藤大佐作为理事卿的代言人，不仅局限于「无序之都」，在土星天全域乃至其它星天，都获取了相当数量的支持者。",
	},
	[832000101] = {
		id = 832000101,
		text = "黑色的士兵——理事卿的机仆，莎乐美武装机甲的半身。\
你很熟悉那机兵的身形。在一年前的刺杀事件中，你自己就曾被它手中的长枪穿刺而过。\
斋藤大佐能够召唤理事卿的「机仆」——那套武装机甲的半身——然后声称自己从「机仆」那里，得到了理事卿的指示。",
	},
	[832000102] = {
		id = 832000102,
		text = "你目前有一半战力封存于理事卿体内，所以只在理事卿愿意借出力量的场合，才有可能暂时恢复全力。\
而理事卿本人暂时困在这只「鱿猫猫头」——她原本的宠物——的躯体里，毫无战力，同样需要你许可，才有可能恢复。\
一年后的今天，莎乐美已随你「共死」了一整年，你们都已不是掌握世间最新资讯的人了。\
但无论世事如何变化，以你们二人互相敌对的立场，都完全不可能许可对方的复原……",
	},
	[832000103] = {
		id = 832000103,
		text = "复乐园的园长。\
鱿猫猫头。\
真命总统、第二行星无眠至权、冬日帝星照耀的受命者、复乐园第一理事卿、总控四天之主。",
	},
	[832000104] = {
		id = 832000104,
		text = "你伪装了自己的身份，使用假名、带着莎乐美的力量，来到了理事会在「无序之都」的据点，自称第一理事卿的使者——「理事卿之声」。\
此时理事会正群龙无首，人人无不怀念莎乐美。见到莎乐美居然派来使者，非常震惊。\
你宣称莎乐美没死，而在莎乐美回归之前，你传达的声音，就是莎乐美的意旨。",
	},
	[832000105] = {
		id = 832000105,
		text = "在理事会安排的秘书+女仆——清凉院眠眠——的帮助下，你开始接手这个理事会分部的统治事务。\
清凉院眠眠，是一个不听命令、懒散、对你阳奉阴违、不停对你的施政能力作出负面评价的女孩。\
性格方面，眠眠完全没有身为「优雅女仆」的自觉，而是一个野得过于明显的野孩子。\
她会拿着咖啡豆和空杯子，对你不耐烦地说「要喝咖啡就自己去泡！」完全不把你放在眼里。（她甚至不知道咖啡豆不是用来直接泡水的）\
眠眠唯一能做的家务是打开扫地机器人。",
	},
	[832000106] = {
		id = 832000106,
		text = "「中枢」的权力核心，不为外人所知。\
即使在「中枢」内部，也只有层级足够的大干部，才知道最高等级干部——「中枢六尽」的存在。\
「无尽全盛统合中枢」的六个「尽头」——那就是「中枢六尽」。\
