		text = "在受伤后的一瞬间点按疾驰技，受身，并触发子弹时间。",
	},
	[835000013] = {
		id = 835000013,
		text = "在闪光时精确点按荧光技，可以无限连击。",
	},
	[835000014] = {
		id = 835000014,
		text = "高连段的荧光技为辉光技充能。满能量后使用辉光技。",
	},
	[835000015] = {
		id = 835000015,
		text = "长按轻攻击以蓄力。",
	},
	[835000016] = {
		id = 835000016,
		text = "点按立刻释放荧光技。",
	},
	[835000017] = {
		id = 835000017,
		text = "长按荧光技，锁定多个敌人，且蓄力满时为辉光技充能。",
	},
	[835000018] = {
		id = 835000018,
		text = "根据不同的战场状况，荧光技将自动变化。其中根据敌人距离有三种变化。",
	},
	[835000019] = {
		id = 835000019,
		text = "目标高速移动时、自身被击飞不受控时、目标铁壁烧坠时，荧光技有三种变化。",
	},
	[835000020] = {
		id = 835000020,
		text = "若辉光技能量不满，先后使用不同的荧光技，可以充能。",
	},
	[835000021] = {
		id = 835000021,
		text = "使用任意轻攻击。",
	},
	[835000022] = {
		id = 835000022,
		text = "长按轻攻击，持续累积热量至最大。",
	},
	[835000023] = {
		id = 835000023,
		text = "长按疾驰技，主动散热。",
	},
	[835000024] = {
		id = 835000024,
		text = "若疾驰技成功闪避伤害，则点亮1个储能罐，并为辉光技充能。",
	},
	[835000025] = {
		id = 835000025,
		text = "储能罐亮起时，增加25%攻击力，在轻攻击后熄灭。",
	},
	[835000026] = {
		id = 835000026,
		text = "使用荧光技，切换为瞄准模式。",
	},
	[835000027] = {
		id = 835000027,
		text = "点按轻攻击，发射最多4座浮塔。",
	},
	[835000028] = {
		id = 835000028,
		text = "发射4座浮塔后，使用荧光技召回。",
	},
	[835000029] = {
		id = 835000029,
		text = "辉光技变身后，在轻攻击0-2段时，点按荧光技。",
	},
	[835000030] = {
		id = 835000030,
		text = "点按轻攻击，浮塔五连击，根据段数获取连击点。",
	},
	[835000031] = {
		id = 835000031,
		text = "使用疾驰技，或点按荧光技时，都可以消耗连击点，发射强力导弹。",
	},
	[835000032] = {
		id = 835000032,
		text = "若辉光技能量不满，消耗连击点可以充能。",
	},
	[835000033] = {
		id = 835000033,
		text = "点按或长按轻攻击，点亮护盾片。",
	},
	[835000034] = {
		id = 835000034,
		text = "点按或长按荧光技，消耗护盾片。",
	},
	[835000035] = {
		id = 835000035,
		text = "使用辉光技。",
	},
	[835000036] = {
		id = 835000036,
		text = "辉光技变身后，在轻攻击3段时，点按荧光技。",
	},
	[835000037] = {
		id = 835000037,
